import time
import math
import signal
import sys
import board
import busio
import adafruit_lsm303_accel
import adafruit_lsm303dlh_mag
import Adafruit_ADS1x15
import pigpio

# --- Configuration ---
MOTOR_DIR_PIN = 20
MOTOR_STEP_PIN = 21
MOTOR_MS0_PIN = 14
MOTOR_MS1_PIN = 15
MOTOR_CW = 1
MOTOR_CCW = 0
MOTOR_RESOLUTION = {
    'Full': (0, 0),
    'Half': (1, 0),
    '1/4': (0, 1),
    '1/8': (1, 1)
}
ADC_GAIN = 1
ADC_MAX_VALUE = 1647
ADC_VOLTAGE_REF = 3.3
PWM_FREQUENCY = 500
I2C_BUS = 1
I2C_ADDRESS = 0x48

# --- Globals for cleanup ---
pi = None
pwm = None
adc = None
i2c = None
accelerometer = None
magnetometer = None
running = True


def signal_handler(signum, frame):
    global running
    running = False


def cleanup():
    global pi, pwm
    if pwm is not None:
        try:
            pwm.set_dutycycle(MOTOR_STEP_PIN, 0)
        except Exception:
            pass
    if pi is not None and pi.connected:
        try:
            pi.write(MOTOR_DIR_PIN, 0)
            pi.write(MOTOR_MS0_PIN, 0)
            pi.write(MOTOR_MS1_PIN, 0)
            pi.set_mode(MOTOR_DIR_PIN, pigpio.INPUT)
            pi.set_mode(MOTOR_STEP_PIN, pigpio.INPUT)
            pi.set_mode(MOTOR_MS0_PIN, pigpio.INPUT)
            pi.set_mode(MOTOR_MS1_PIN, pigpio.INPUT)
        except Exception:
            pass
        try:
            pi.stop()
        except Exception:
            pass


def initialize_gpio():
    global pi
    pi = pigpio.pi()
    if not pi.connected:
        print("Error: Could not connect to pigpio daemon. Is pigpiod running?")
        sys.exit(1)
    for pin in [MOTOR_DIR_PIN, MOTOR_STEP_PIN, MOTOR_MS0_PIN, MOTOR_MS1_PIN]:
        pi.set_mode(pin, pigpio.OUTPUT)
    pi.write(MOTOR_DIR_PIN, MOTOR_CCW)
    pi.write(MOTOR_MS0_PIN, MOTOR_RESOLUTION['Full'][0])
    pi.write(MOTOR_MS1_PIN, MOTOR_RESOLUTION['Full'][1])


def initialize_adc():
    global adc
    try:
        adc = Adafruit_ADS1x15.ADS1015(address=I2C_ADDRESS, busnum=I2C_BUS)
    except Exception as e:
        print(f"Error initializing ADS1015: {e}")
        sys.exit(1)


def initialize_sensors():
    global i2c, accelerometer, magnetometer
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        sys.exit(1)
    try:
        accelerometer = adafruit_lsm303_accel.LSM303_Accel(i2c)
    except Exception as e:
        print(f"Error initializing LSM303 accelerometer: {e}")
        sys.exit(1)
    try:
        magnetometer = adafruit_lsm303dlh_mag.LSM303DLH_Mag(i2c)
    except Exception as e:
        print(f"Error initializing LSM303 magnetometer: {e}")
        sys.exit(1)


def read_adc_channel(channel):
    try:
        return adc.read_adc(channel, gain=ADC_GAIN)
    except Exception as e:
        print(f"Error reading ADC channel {channel}: {e}")
        return None


def convert_to_voltage(adc_value):
    if adc_value is None:
        return None
    return (adc_value / float(ADC_MAX_VALUE)) * ADC_VOLTAGE_REF


def calculate_pwm_duty_cycle(voltage):
    if voltage is None:
        return 0
    return int((voltage / ADC_VOLTAGE_REF) * 255)


def get_acceleration():
    try:
        return accelerometer.acceleration
    except Exception as e:
        print(f"Error reading acceleration: {e}")
        return None


def get_heading():
    try:
        mag_x, mag_y, _ = magnetometer.magnetic
        angle = math.degrees(math.atan2(mag_y, mag_x))
        return angle + 360 if angle < 0 else angle
    except Exception as e:
        print(f"Error reading heading: {e}")
        return None


def main():
    global pwm
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        initialize_gpio()
        initialize_adc()
        initialize_sensors()
        pwm = pi.set_PWM_frequency(MOTOR_STEP_PIN, PWM_FREQUENCY)
        pi.set_PWM_dutycycle(MOTOR_STEP_PIN, 0)
        while running:
            adc_value = read_adc_channel(0)
            voltage = convert_to_voltage(adc_value)
            duty_cycle = calculate_pwm_duty_cycle(voltage)
            try:
                pi.set_PWM_dutycycle(MOTOR_STEP_PIN, duty_cycle)
            except Exception as e:
                print(f"Error setting PWM duty cycle: {e}")
            print(f"ADC Value: {adc_value}, Voltage: {voltage:.2f}V, PWM Duty Cycle: {duty_cycle}")
            acceleration = get_acceleration()
            if acceleration is not None:
                print(f"Acceleration: {acceleration}")
            heading = get_heading()
            if heading is not None:
                print(f"Heading: {heading:.2f} degrees")
            time.sleep(1)
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

