import time
import board
import busio
import adafruit_ads1x15.ads1115 as ADS
from adafruit_ads1x15.analog_in import AnalogIn

# Constants
I2C_ADDRESS = 0x48
GAIN = 1
READ_INTERVAL = 0.5  # seconds


def initialize_adc():
    """Initialize I2C bus and ADS1115 ADC. Returns (i2c, ads) or (None, None) on failure."""
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None, None

    try:
        ads = ADS.ADS1115(i2c, address=I2C_ADDRESS)
        ads.gain = GAIN
    except Exception as e:
        print(f"Error initializing ADS1115 at 0x{I2C_ADDRESS:02X}: {e}")
        return None, None

    return i2c, ads


def read_all_channels(ads):
    """Read all four single-ended channels. Returns list of signed ints or None on error."""
    channels = []
    for ch in range(4):
        try:
            pin = AnalogIn(ads, ch)
            channels.append(pin.value)
        except Exception as e:
            print(f"Error reading channel {ch}: {e}")
            return None
    return channels


def print_header():
    """Print table header."""
    print("| {0:>6} | {1:>6} | {2:>6} | {3:>6} |".format("A0", "A1", "A2", "A3"))
    print("-" * 37)


def main():
    i2c, ads = initialize_adc()
    if i2c is None or ads is None:
        print("ADC initialization failed. Exiting.")
        return

    print("Reading ADS1115 channels (gain=1, +/-4.096V). Press Ctrl-C to quit.")
    print_header()

    try:
        while True:
            values = read_all_channels(ads)
            if values is not None:
                print("| {0:>6} | {1:>6} | {2:>6} | {3:>6} |".format(*values))
            time.sleep(READ_INTERVAL)
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    finally:
        # Release I2C bus resources
        try:
            i2c.deinit()
        except Exception:
            pass


if __name__ == "__main__":
    main()

