import spidev
import time
import signal
import sys

# MQ-2 gas sensor via MCP3008 ADC on SPI bus 0, CS 0, channel 0
SPI_BUS = 0
SPI_DEVICE = 0
ADC_CHANNEL = 0
REFERENCE_VOLTAGE = 3.3
GAIN_FACTOR = 200.0
SAMPLE_COUNT = 12
SAMPLE_INTERVAL = 0.5

class GasSensor:
    """Reads an MQ-2 gas sensor via MCP3008 ADC and converts to ppm."""

    def __init__(self, bus=SPI_BUS, device=SPI_DEVICE, channel=ADC_CHANNEL):
        self.spi = spidev.SpiDev()
        self.channel = channel
        try:
            self.spi.open(bus, device)
            self.spi.max_speed_hz = 1000000
            self.spi.mode = 0
        except OSError as e:
            raise RuntimeError(f"Failed to open SPI bus {bus}, device {device}: {e}")

    def read_raw(self):
        """Read raw 10-bit value from MCP3008 channel (0-1023)."""
        # MCP3008 single-ended read: start bit, config byte, padding
        cmd = [1, (8 + self.channel) << 4, 0]
        try:
            reply = self.spi.xfer2(cmd)
        except OSError as e:
            raise RuntimeError(f"SPI transfer failed: {e}")
        # 10-bit result from reply bytes 1 and 2
        raw = ((reply[1] & 0x03) << 8) | reply[2]
        return raw

    def read_ppm(self):
        """Convert raw ADC value to estimated gas concentration in ppm."""
        raw = self.read_raw()
        voltage = (raw / 1023.0) * REFERENCE_VOLTAGE
        ppm = voltage * GAIN_FACTOR
        return ppm

    def close(self):
        """Release SPI resources."""
        if hasattr(self, 'spi') and self.spi:
            self.spi.close()

def evaluate_alert(ppm):
    """Return alert level string based on ppm threshold."""
    if ppm < 150:
        return "Safe"
    elif ppm < 400:
        return "Warning"
    else:
        return "Danger"

def signal_handler(signum, frame):
    print(f"\nReceived signal {signum}, exiting...")
    sys.exit(0)

def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    sensor = None
    try:
        sensor = GasSensor()
        for i in range(SAMPLE_COUNT):
            try:
                ppm = sensor.read_ppm()
            except RuntimeError as e:
                print(f"Sample {i+1}: SPI error - {e}")
                time.sleep(SAMPLE_INTERVAL)
                continue
            alert = evaluate_alert(ppm)
            print(f"Sample {i+1}: Gas Concentration: {ppm:.2f} ppm - Alert Level: {alert}")
            time.sleep(SAMPLE_INTERVAL)
    except RuntimeError as e:
        print(f"Initialization error: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if sensor:
            sensor.close()

if __name__ == "__main__":
    main()

