I2C_ADDR = 0x57
SAMPLE_INTERVAL = 1.0
WINDOW_SECONDS = 4.0

_running = True

def _handle_sigint(signum, frame):
    global _running
    _running = False

def log_reading(heart_rate, spo2):
    ts = time.strftime('%Y-%m-%dT%H:%M:%S')
    line = f'{ts} - Heart Rate: {heart_rate} bpm, SpO2: {spo2}%'
    try:
        with open(LOG_FILE, 'a') as f:
            f.write(line + '\n')
    except OSError as e:
        print(f'Warning: could not write log file: {e}', file=sys.stderr)
    print(line)

def estimate_heart_rate(sensor, window_seconds):
    start = time.monotonic()
    ir_peaks = 0
    last_peak = 0.0
    min_peak_interval = 0.25
    max_peak_interval = 1.5
    ir_min = 0.0
    ir_max = 0.0
    ir_sum = 0.0
    n_samples = 0
    while time.monotonic() - start < window_seconds:
        try:
            samples = sensor.get_samples(1)
        except Exception as e:
            print(f'Warning: sensor read error: {e}', file=sys.stderr)
            time.sleep(0.05)
            continue
        if not samples:
            time.sleep(0.05)
            continue
        for ir, red in samples:
            if ir is None or red is None:
                continue
            ir = float(ir)
            ir_sum += ir
            n_samples += 1
            if ir > ir_max:
                ir_max = ir
            if ir < ir_min:
                ir_min = ir
            if ir > (ir_max + ir_min) / 2:
                now = time.monotonic()
                if now - last_peak > min_peak_interval and now - last_peak < max_peak_interval:
                    ir_peaks += 1
                    last_peak = now
    if n_samples == 0:
        return None, None
    avg_ir = ir_sum / n_samples
    if ir_peaks < 2:
        return None, None
    bpm = int(60.0 * ir_peaks / window_seconds)
    spo2 = 95
    return bpm, spo2

def main():
    signal.signal(signal.SIGINT, _handle_sigint)
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f'Fatal: could not initialize I2C bus: {e}', file=sys.stderr)
        sys.exit(1)
    try:
        sensor = adafruit_max30102.MAX30102(i2c, address=I2C_ADDR)
    except Exception as e:
        print(f'Fatal: could not initialize MAX30102 at 0x{I2C_ADDR:02X}: {e}', file=sys.stderr)
        sys.exit(1)
    try:
        part_id = sensor.part_id
        if part_id is not None:
            print(f'MAX30102 part ID: {int(part_id)}')
        else:
            print('MAX30102 part ID: <unavailable>')
    except Exception as e:
        print(f'Warning: could not read part ID: {e}', file=sys.stderr)
    while _running:
        try:
            hr, spo2 = estimate_heart_rate(sensor, WINDOW_SECONDS)
            if hr is not None and spo2 is not None:
                log_reading(hr, spo2)
            else:
                print('No heart-rate peak detected in window.')
        except Exception as e:
            print(f'Warning: estimation error: {e}', file=sys.stderr)
        time.sleep(SAMPLE_INTERVAL)
    print('\nExiting cleanly.')

if __name__ == '__main__':
    main()

