import cv2
import time
import signal
import sys
import os
from gpiozero import LED, Button, AngularServo
from gpiozero.exc import GPIOZeroError

LED_PIN = 14
BUTTON_PIN = 15
SERVO_PIN = 18
SERVO_FREQUENCY = 50
SERVO_MIN_DUTY = 2.0
SERVO_MAX_DUTY = 12.0
SERVO_MIN_ANGLE = 0
SERVO_MAX_ANGLE = 180
SERVO_INCREMENT = 20
CASCADE_PATH = '/home/raspberry/RaspPi_CV/haarcascade_frontalface_default.xml'
CAMERA_INDEX = 0
FRAME_WIDTH = 320
FRAME_HEIGHT = 240
WINDOW_NAME = 'Human Detection'

running = True
camera = None
led = None
button = None
servo = None
gui_enabled = True


def signal_handler(signum, frame):
    global running
    running = False


def cleanup():
    global camera, led, button, servo, gui_enabled
    if camera is not None:
        try:
            camera.release()
        except Exception:
            pass
    if gui_enabled:
        try:
            cv2.destroyAllWindows()
        except Exception:
            pass
    for dev in (led, button, servo):
        if dev is not None:
            try:
                dev.close()
            except Exception:
                pass
    print('Cleanup complete.')


def main():
    global running, camera, led, button, servo, gui_enabled

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        led = LED(LED_PIN)
        button = Button(BUTTON_PIN, pull_up=True)
        servo = AngularServo(
            SERVO_PIN,
            initial_angle=SERVO_MIN_ANGLE,
            min_angle=SERVO_MIN_ANGLE,
            max_angle=SERVO_MAX_ANGLE,
            min_pulse_width=SERVO_MIN_DUTY / 100.0 / SERVO_FREQUENCY,
            max_pulse_width=SERVO_MAX_DUTY / 100.0 / SERVO_FREQUENCY,
            frame_width=1.0 / SERVO_FREQUENCY,
        )
    except GPIOZeroError as e:
        print(f'GPIO initialization error: {e}')
        print('Continuing without GPIO control.')
        led = None
        button = None
        servo = None
    except Exception as e:
        print(f'Unexpected GPIO error: {e}')
        print('Continuing without GPIO control.')
        led = None
        button = None
        servo = None

    if not os.path.isfile(CASCADE_PATH):
        print(f'Error: Cascade file not found at {CASCADE_PATH}')
        cleanup()
        sys.exit(0)

    cascade = cv2.CascadeClassifier(CASCADE_PATH)
    if cascade.empty():
        print(f'Error: Failed to load cascade classifier from {CASCADE_PATH}')
        cleanup()
        sys.exit(0)

    try:
        camera = cv2.VideoCapture(CAMERA_INDEX, cv2.CAP_V4L2)
        if not camera.isOpened():
            print(f'Error: Could not open camera at index {CAMERA_INDEX}')
            cleanup()
            sys.exit(0)
    except Exception as e:
        print(f'Error: Camera initialization failed: {e}')
        cleanup()
        sys.exit(0)

    try:
        camera.set(cv2.CAP_PROP_FRAME_WIDTH, FRAME_WIDTH)
        camera.set(cv2.CAP_PROP_FRAME_HEIGHT, FRAME_HEIGHT)
    except Exception:
        pass

    servo_angle = SERVO_MIN_ANGLE
    if servo is not None:
        try:
            servo.angle = servo_angle
        except Exception as e:
            print(f'Warning: Could not set initial servo angle: {e}')

    try:
        while running:
            ret, frame = camera.read()
            if not ret or frame is None:
                print('Error: Could not read frame from camera.')
                break

            try:
                frame = cv2.resize(frame, (FRAME_WIDTH, FRAME_HEIGHT))
            except Exception as e:
                print(f'Warning: Frame resize failed: {e}')

            gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            faces = cascade.detectMultiScale(
                gray, scaleFactor=1.1, minNeighbors=5, minSize=(30, 30)
            )

            for (x, y, w, h) in faces:
                cv2.rectangle(frame, (x, y), (x + w, y + h), (255, 0, 0), 2)

            if len(faces) > 0:
                if led is not None:
                    try:
                        led.on()
                    except Exception as e:
                        print(f'Warning: LED on failed: {e}')
                center_x = FRAME_WIDTH // 2
                face_center_x = (x + x + w) // 2
                if face_center_x > center_x:
                    servo_angle = min(servo_angle + SERVO_INCREMENT, SERVO_MAX_ANGLE)
                else:
                    servo_angle = max(servo_angle - SERVO_INCREMENT, SERVO_MIN_ANGLE)
                if servo is not None:
                    try:
                        servo.angle = servo_angle
                    except Exception as e:
                        print(f'Warning: Servo angle update failed: {e}')
                time.sleep(0.02)
            else:
                if led is not None:
                    try:
                        led.off()
                    except Exception as e:
                        print(f'Warning: LED off failed: {e}')

            if gui_enabled:
                try:
                    cv2.imshow(WINDOW_NAME, frame)
                except Exception as e:
                    print(f'Warning: imshow failed (GUI disabled): {e}')
                    gui_enabled = False
            else:
                try:
                    cv2.imshow(WINDOW_NAME, frame)
                except Exception:
                    pass

            if gui_enabled:
                try:
                    key = cv2.waitKey(1) & 0xFF
                    if key == ord('q'):
                        break
                except Exception as e:
                    print(f'Warning: waitKey failed (GUI disabled): {e}')
                    gui_enabled = False
    except Exception as e:
        print(f'Runtime error: {e}')
    finally:
        cleanup()


if __name__ == '__main__':
    main()

