import cv2
import numpy as np
import signal
import sys
import time
from picamera2 import Picamera2

running = True

def signal_handler(signum, frame):
    global running
    running = False

def cleanup(cameras):
    for cam in cameras:
        if cam is not None:
            try:
                cam.stop()
            except Exception:
                pass
    cv2.destroyAllWindows()

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    cameras = []
    try:
        for i in range(2):
            try:
                cam = Picamera2(camera_num=i)
                config = cam.create_preview_configuration(
                    main={"size": (640, 480), "format": "RGB888"},
                    controls={"FrameDurationLimits": (33333, 33333)},
                )
                cam.configure(config)
                cam.start()
                cameras.append(cam)
            except Exception as e:
                print(f"Error initializing camera {i}: {e}", file=sys.stderr)
                cleanup(cameras)
                sys.exit(1)
    except Exception as e:
        print(f"Unexpected error during initialization: {e}", file=sys.stderr)
        cleanup(cameras)
        sys.exit(1)

    try:
        while running:
            try:
                frame0 = cameras[0].capture_array()
                frame1 = cameras[1].capture_array()
            except Exception as e:
                print(f"Error capturing frames: {e}", file=sys.stderr)
                break

            if frame0 is None or frame1 is None:
                print("Warning: captured None frame, skipping.", file=sys.stderr)
                continue

            combined = np.hstack((frame0, frame1))

            cv2.imshow("Dual CSI Cameras", combined)
            key = cv2.waitKey(30) & 0xFF

            if key == 27:
                break
            if cv2.getWindowProperty("Dual CSI Cameras", cv2.WND_PROP_AUTOSIZE) < 0:
                break
    except KeyboardInterrupt:
        pass
    finally:
        cleanup(cameras)

if __name__ == "__main__":
    main()

