import multiprocessing
import os
import signal
import time
import atexit
import threading
import traceback
import sys
from typing import Optional

from setproctitle import setproctitle

import config
import logsupport as L
from controlevents import CEvent, PostEvent, ConsoleEvent
from utils.utilfuncs import disptime


def _process_alive(pid: int) -> bool:
    """Return True if *pid* is a running process."""
    try:
        os.kill(pid, 0)
        return True
    except ProcessLookupError:
        return False
    except PermissionError:
        return True  # process exists but we lack permission to signal it
    except OSError:
        return False


def _write_tombstone(message: str) -> None:
    """Append *message* and a stack trace to the watchdog tombstone file."""
    try:
        with open('/home/pi/.tombstoneW', 'a') as f:
            f.write(f'{time.time()}: {message}\n')
            traceback.print_stack(file=f)
            f.flush()
    except OSError as e:
        L.Logs.Log(f'Error writing tombstone: {e}', severity=L.ConsoleError)


def _handle_signal(signum: int, frame, code: int, message: str) -> None:
    """Generic signal handler: log, write tombstone, and exit with *code*."""
    try:
        L.Logs.Log(f'Watchdog {os.getpid()} exiting on signal {signum} ({message})')
        _write_tombstone(message)
    except Exception as e:
        print(f'Error in signal handler for {signum}: {e}', file=sys.stderr)
    finally:
        os._exit(code)


def _handle_sigterm(signum, frame):
    """Handle SIGTERM (e.g. from systemd)."""
    _handle_signal(signum, frame, 0, 'SIGTERM from systemd')


def _handle_sigint(signum, frame):
    """Handle SIGINT (Ctrl-C)."""
    _handle_signal(signum, frame, 94, 'SIGINT')


def _handle_sigusr1(signum, frame):
    """Handle SIGUSR1."""
    _handle_signal(signum, frame, 94, 'SIGUSR1')


def _handle_sighup(signum, frame):
    """Handle SIGHUP (ignore, log only)."""
    try:
        L.Logs.Log('Watchdog ignoring SIGHUP')
    except Exception as e:
        print(f'Error handling SIGHUP: {e}', file=sys.stderr)


def _handle_sigabort(signum, frame):
    """Handle SIGABRT."""
    _handle_signal(signum, frame, 93, 'SIGABRT')


def _injector() -> None:
    """Post a FailSafePing event every 30 seconds."""
    L.Logs.Log('Starting watchdog injector')
    while True:
        try:
            now = time.time()
            L.Logs.Log(f'Inject: {now}', severity=L.ConsoleDetailHigh)
            PostEvent(ConsoleEvent(CEvent.FailSafePing, inject=now))
        except Exception as e:
            L.Logs.Log(f'Exception in injector: {e}', severity=L.ConsoleWarning)
        time.sleep(30)


def _watchdog_dying() -> None:
    """Check every 30 seconds that the main thread is alive; kill the watchdog if it dies."""
    L.Logs.Log('Watchdog self-monitoring thread started')
    while True:
        time.sleep(30)
        if not threading.main_thread().is_alive():
            L.Logs.Log('Watchdog main thread died — killing process')
            try:
                os.kill(os.getpid(), signal.SIGINT)
            except OSError:
                pass
            return


def _cleanup() -> None:
    """Ensure the console is terminated if the watchdog exits unexpectedly."""
    L.Logs.Log('Watchdog cleanup — checking console')
    console_pid = getattr(config.sysStore, 'Console_pid', None)
    if console_pid is None:
        L.Logs.Log('No Console_pid in sysStore — nothing to clean up')
        return
    if not _process_alive(console_pid):
        L.Logs.Log(f'Console PID {console_pid} not running — nothing to kill')
        return
    L.Logs.Log(f'Watchdog dying — sending SIGUSR1 to console (PID {console_pid})')
    try:
        os.kill(console_pid, signal.SIGUSR1)
    except OSError as e:
        L.Logs.Log(f'Failed to send SIGUSR1 to console: {e}')
        return
    time.sleep(3)
    if _process_alive(console_pid):
        L.Logs.Log(f'Console did not exit — sending SIGKILL (PID {console_pid})')
        try:
            os.kill(console_pid, signal.SIGKILL)
        except OSError as e:
            L.Logs.Log(f'Failed to send SIGKILL to console: {e}')
    else:
        L.Logs.Log('Console exited after SIGUSR1')


def _log_debug(message: str) -> None:
    """Append *message* with a timestamp to the debug log file."""
    try:
        with open('/home/pi/Console/.HistoryBuffer/hlogW', 'a') as f:
            f.write(f'{disptime()} {message}\n')
            f.flush()
    except OSError as e:
        L.Logs.Log(f'Error writing debug log: {e}', severity=L.ConsoleError)


def _watchdog() -> None:
    """Main watchdog loop."""
    L.Logs.Log('Watchdog starting')
    setproctitle('Console Watchdog')

    signal.signal(signal.SIGTERM, _handle_sigterm)
    signal.signal(signal.SIGINT, _handle_sigint)
    signal.signal(signal.SIGUSR1, _handle_sigusr1)
    signal.signal(signal.SIGHUP, _handle_sighup)
    signal.signal(signal.SIGABRT, _handle_sigabort)

