    console_pid: Optional[int] = getattr(config.sysStore, 'Console_pid', None)
    if console_pid is None:
        L.Logs.Log('No Console_pid in sysStore — exiting', severity=L.ConsoleWarning)
        os._exit(1)

    L.Logs.Log(f'Watchdog started (PID {os.getpid()}) for console (PID {console_pid})')

    keep_alive = multiprocessing.Event()

    injector_thread = threading.Thread(target=_injector, name='InjectorThread', daemon=True)
    injector_thread.start()

    monitor_thread = threading.Thread(target=_watchdog_dying, name='MonitorThread', daemon=True)
    monitor_thread.start()

    while True:
        if keep_alive.wait(60):
            keep_alive.clear()
            L.Logs.Log('Keepalive received')
        else:
            L.Logs.Log('No keepalive within 60 seconds — sending SIGUSR1 to console')
            try:
                os.kill(console_pid, signal.SIGUSR1)
            except OSError as e:
                L.Logs.Log(f'Failed to send SIGUSR1 to console: {e}')
                break
            time.sleep(3)
            if _process_alive(console_pid):
                L.Logs.Log('Console did not exit — sending SIGKILL')
                try:
                    os.kill(console_pid, signal.SIGKILL)
                except OSError as e:
                    L.Logs.Log(f'Failed to send SIGKILL to console: {e}')
                break
            else:
