import atexit
import signal
import sys
import threading
import time
import traceback
from typing import Tuple, Optional

from flask import Flask, render_template, Response, request

from config import Config
from mail_config import MailConfig

try:
    from picamera2 import Picamera2
    from picamera2.encoders import MJPEGEncoder
    from picamera2.outputs import FileOutput
except ImportError:
    print("picamera2 is not installed. Install with: pip install picamera2", file=sys.stderr)
    sys.exit(1)

try:
    from picamera2 import Transform
except ImportError:
    Transform = None

try:
    import cv2
    import numpy as np
except ImportError:
    cv2 = None
    np = None

try:
    from object_detection import ObjectDetection
except ImportError:
    ObjectDetection = None

# ---------------------------------------------------------------------------
# Globals
# ---------------------------------------------------------------------------
app = Flask(__name__)
config = Config()
mail_config = MailConfig()

# type: ignore is used where picamera2 types are unavailable in the stubs.

# ---------------------------------------------------------------------------
# Camera wrapper
# ---------------------------------------------------------------------------
class Camera:
    """Wrapper around picamera2 providing JPEG frames and object detection."""

    def __init__(self, config: Config):
        self.config = config
        self.picam2: Optional[Picamera2] = None
        self._lock = threading.Lock()
        self._running = False
        self._last_email_time = 0.0

        try:
            self.picam2 = Picamera2()
            # Build a video configuration for JPEG streaming at the configured resolution.
            video_config = self.picam2.create_video_configuration(
                main={"size": (config.resolution_width, config.resolution_height), "format": "RGB888"},
                encode="mjpeg",
            )
            self.picam2.configure(video_config)

            # Apply vertical flip via the transform option (no legacy flip parameter).
            if Transform is not None and config.flip:
                self.picam2.camera_config["transform"] = Transform(vflip=True)

            self.picam2.start()
            # Allow a brief warm-up so the first frame is not underexposed.
            time.sleep(1.0)
            self._running = True
        except Exception as e:
            print(f"Error initializing camera: {e}", file=sys.stderr)
            traceback.print_exc()
            self._running = False
            raise

    # -- frame capture -----------------------------------------------------
    def get_frame(self) -> bytes:
        """Return a JPEG-encoded bytes frame, or b'' on error."""
        if not self._running or self.picam2 is None:
            return b""
        try:
            # capture_array returns a numpy array in the configured format.
            array = self.picam2.capture_array()
            if array is None or array.size == 0:
                return b""
            # picamera2 returns RGB888; convert to BGR for OpenCV JPEG encoding.
            if cv2 is not None:
                bgr = cv2.cvtColor(array, cv2.COLOR_RGB2BGR)
                ok, encoded = cv2.imencode(".jpg", bgr)
                if ok:
                    return encoded.tobytes()
            # Fallback: use picamera2's built-in MJPEG encoder if available.
            # (In practice, we use OpenCV for consistent quality; this is a
            # defensive path in case OpenCV is absent or the array is not RGB.)
            return b""
        except Exception as e:
            print(f"Error capturing frame: {e}", file=sys.stderr)
            return b""

    # -- object detection --------------------------------------------------
    def _detect(self, frame: bytes, classifier: object) -> bool:
        """Run the object-detection classifier on a JPEG frame."""
        if not frame:
            return False
        try:
            if cv2 is not None and np is not None:
                arr = np.frombuffer(frame, dtype=np.uint8)
                img = cv2.imdecode(arr, cv2.IMREAD_COLOR)
                if img is None:
                    return False
                return classifier.detect_object(img)
            return False
        except Exception as e:
            print(f"Error during object detection: {e}", file=sys.stderr)
            return False

    def get_object(self, classifier: object) -> Tuple[bytes, bool]:
        """Capture a frame and run object detection."""
        frame = self.get_frame()
        return frame, self._detect(frame, classifier)

    def get_object_with_basic_motion_detection(self) -> Tuple[bytes, bool]:
        """Capture a frame and run basic motion detection."""
        frame = self.get_frame()
        if not frame:
            return frame, False
        try:
            if cv2 is not None and np is not None:
                arr = np.frombuffer(frame, dtype=np.uint8)
                img = cv2.imdecode(arr, cv2.IMREAD_GRAYSCALE)
                if img is None:
                    return frame, False
                return frame, self._basic_motion_detection(img)
            return frame, False
        except Exception as e:
            print(f"Error during motion detection: {e}", file=sys.stderr)
            return frame, False

    # -- motion helper -----------------------------------------------------
    def _basic_motion_detection(self, image: np.ndarray) -> bool:
        """Very basic motion detection: threshold the image and count changes."""
        _, thresh = cv2.threshold(image, 25, 255, cv2.THRESH_BINARY)
        motion_pixels = int(np.count_nonzero(thresh))
        return motion_pixels > 0

    # -- email notification ------------------------------------------------
    def send_email_notification(self, frame: bytes) -> None:
        """Send an email notification if the interval has elapsed."""
        if not self.config.send_email_notifications:
            return
        now = time.time()
        if now - self._last_email_time < self.config.email_send_interval:
            return
        try:
            mail_config.send_email(frame, self.config)
            self._last_email_time = now
        except Exception as e:
            print(f"Error sending email: {e}", file=sys.stderr)

    # -- cleanup -----------------------------------------------------------
    def stop(self) -> None:
        """Release the camera cleanly."""
        if not self._running or self.picam2 is None:
            return
        try:
            self.picam2.stop()
        except Exception as e:
            print(f"Error stopping camera: {e}", file=sys.stderr)
        finally:
            self._running = False


# ---------------------------------------------------------------------------
# Flask routes
# ---------------------------------------------------------------------------
@app.route("/", methods=["GET", "POST"])
def index():
    """Render the configuration form and live-preview toggle."""
    if request.method == "POST":
        config.update_from_form(request.form)
    return render_template("index.html", classifiers=config.classifier_name_mappings, config=config)


def gen(camera: Camera):
    """Generator yielding multipart JPEG frames for the video feed."""
    while camera._running:
        try:
            if config.classifier_name == "motion_detector":
                frame, _ = camera.get_object_with_basic_motion_detection()
            else:
                frame, _ = camera.get_object(config.classifier)

            if frame:
                yield (
                    b"--frame\r\n"
                    b"Content-Type: image/jpeg\r\n\r\n" + frame + b"\r\n\r\n"
                )
            else:
                # Yield a blank frame so the browser keeps the connection alive.
                yield b"--frame\r\nContent-Type: image/jpeg\r\n\r\n\r\n"
        except Exception as e:
            print(f"Error generating video frame: {e}", file=sys.stderr)
            time.sleep(0.1)


@app.route("/video_feed")
def video_feed():
    """Stream JPEG frames as multipart/x-mixed-replace."""
    return Response(
        gen(camera),
        mimetype="multipart/x-mixed-replace; boundary=frame",
    )


# ---------------------------------------------------------------------------
# Background detection thread
# ---------------------------------------------------------------------------
def check_for_objects(camera: Camera):
    """Continuously check for objects and send email notifications."""
    while camera._running:
        try:
            if config.classifier_name == "motion_detector":
                frame, object_detected = camera.get_object_with_basic_motion_detection()
            else:
                frame, object_detected = camera.get_object(config.classifier)

            if object_detected and config.send_email_notifications:
                camera.send_email_notification(frame)

            time.sleep(max(0.1, config.check_for_objects_interval))
        except Exception as e:
            print(f"Error in object detection loop: {e}", file=sys.stderr)
            time.sleep(1.0)


# ---------------------------------------------------------------------------
# Entry point
# ---------------------------------------------------------------------------
def main():
    global camera

    # Initialize classifier
    if ObjectDetection is not None:
        config.classifier = ObjectDetection(config.classifier_name, config.classifier_path)
    else:
        print("Warning: object_detection module not found; object detection disabled.", file=sys.stderr)
        config.classifier = None

    # Initialize camera
    try:
        camera = Camera(config)
    except Exception:
        print("Failed to initialize camera. Exiting.", file=sys.stderr)
        sys.exit(1)

    # Start background detection thread
    object_detection_thread = threading.Thread(
        target=check_for_objects, args=(camera,), daemon=True
    )
    object_detection_thread.start()

    # Graceful shutdown on SIGINT / SIGTERM
    def shutdown(signum, frame):
        print(f"\nReceived signal {signum}, shutting down...")
        camera.stop()
        sys.exit(0)

    signal.signal(signal.SIGINT, shutdown)
    signal.signal(signal.SIGTERM, shutdown)

    # Ensure camera is released on exit
    atexit.register(camera.stop)

    # Run Flask
    app.run(host="0.0.0.0", port=5000, debug=False, threaded=True)


if __name__ == "__main__":
    main()

