cap = None
serial_connection = None

try:
    cap = cv2.VideoCapture(0)
    if not cap.isOpened():
        raise IOError("Cannot open webcam")

    frame = None
    for _ in range(5):
        ret, frame = cap.read()
        if ret and frame is not None:
            break
    if frame is None:
        raise IOError("Cannot read frame from webcam")

    h_frame, w_frame, _ = frame.shape
    center_x = w_frame // 2
    center_y = h_frame // 2
    half_ext = 50
    tracking_enabled = False
    min_HSV = np.array([0, 0, 0])
    max_HSV = np.array([255, 255, 255])

    available_ports = [p.device for p in serial.tools.list_ports.comports()]
    if available_ports:
        target_port = '/dev/ttyACM0'
        if target_port in available_ports:
            try:
                serial_connection = serial.Serial(target_port, 9600, timeout=1)
            except serial.SerialException as e:
                print(f"Warning: could not open {target_port}: {e}")
                serial_connection = None
        else:
            print(f"Info: {target_port} not found, trying first available port")
            try:
                serial_connection = serial.Serial(available_ports[0], 9600, timeout=1)
            except serial.SerialException as e:
                print(f"Warning: could not open any serial port: {e}")
                serial_connection = None
    else:
        print("Warning: no serial ports detected; running in serial-disabled mode")

    while running:
        ret, frame = cap.read()
        if not ret or frame is None:
            print("Warning: frame read failed, exiting loop")
            break

        h_frame, w_frame, _ = frame.shape
        center_x = w_frame // 2
        center_y = h_frame // 2

        if tracking_enabled:
            hsv_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2HSV)
            mask = cv2.inRange(hsv_frame, min_HSV, max_HSV)
            contours, _ = cv2.findContours(mask, cv2.RETR_TREE, cv2.CHAIN_APPROX_SIMPLE)

            for contour in contours:
                if cv2.contourArea(contour) > 500:
                    x, y, w, h = cv2.boundingRect(contour)
                    cv2.rectangle(frame, (x, y), (x + w, y + h), (255, 0, 0), 2)

                    ball_x = x + w // 2
                    ball_y = y + h // 2

                    if ball_x > center_x + half_ext and ball_y > center_y + half_ext:
                        position = '1 - Bottom Right'
                    elif ball_x > center_x + half_ext and ball_y < center_y - half_ext:
                        position = '2 - Top Right'
                    elif ball_x < center_x - half_ext and ball_y > center_y + half_ext:
                        position = '3 - Bottom Left'
                    elif ball_x < center_x - half_ext and ball_y < center_y - half_ext:
                        position = '4 - Top Left'
                    else:
                        position = '5 - Center'

                    print(f'Position: {position}')

                    if serial_connection:
                        try:
                            serial_connection.write(position.encode('utf-8'))
                        except serial.SerialException as e:
                            print(f"Serial write error: {e}")

        cv2.imshow("Frame", frame)

        k = cv2.waitKey(1) & 0xFF
        if k == ord('s'):
            tracking_enabled = True
            roi = frame[center_y - half_ext: center_y + half_ext,
                        center_x - half_ext: center_x + half_ext]
            hsv_roi = cv2.cvtColor(roi, cv2.COLOR_BGR2HSV)
            min_HSV = np.array([hsv_roi[:, :, 0].min(), hsv_roi[:, :, 1].min(), hsv_roi[:, :, 2].min()])
            max_HSV = np.array([hsv_roi[:, :, 0].max(), hsv_roi[:, :, 1].max(), hsv_roi[:, :, 2].max()])
            print("Tracking enabled.")
        elif k == ord('o'):
            tracking_enabled = False
            print("Tracking disabled.")
        elif k == 27:
            break

except IOError as e:
    print(f"IOError: {e}")
except Exception as e:
    print(f"Unexpected error: {e}")
finally:
    if cap is not None and cap.isOpened():
        cap.release()
    if serial_connection is not None and serial_connection.is_open:
        serial_connection.close()
    cv2.destroyAllWindows()
    print("Resources released.")

