import json
import logging
import os
import signal
import statistics
import time
from datetime import datetime

try:
    from gpiozero import DigitalOutputDevice, DigitalInputDevice
except Exception:
    DigitalOutputDevice = None
    DigitalInputDevice = None

DEFAULT_CONFIG = {
    "sensors": [
        {"trigger_pin": 17, "echo_pin": 18, "offset": 0.0, "max_distance": 200.0},
        {"trigger_pin": 22, "echo_pin": 23, "offset": 0.0, "max_distance": 200.0},
        {"trigger_pin": 24, "echo_pin": 25, "offset": 0.0, "max_distance": 200.0},
    ],
    "alert_threshold_low": 10.0,
    "alert_threshold_high": 180.0,
    "alert_repeat_delay": 60,
    "log_file": "water_level.log",
}

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def load_config(config_file="config.json"):
    if not os.path.exists(config_file):
        logging.warning("Configuration file not found. Creating default config.json.")
        try:
            with open(config_file, "w") as f:
                json.dump(DEFAULT_CONFIG, f, indent=4)
        except OSError as e:
            logging.error(f"Failed to write default config: {e}")
        return dict(DEFAULT_CONFIG)
    try:
        with open(config_file, "r") as f:
            config = json.load(f)
        required_keys = ["sensors", "alert_threshold_low", "alert_threshold_high",
                         "alert_repeat_delay", "log_file"]
        if not all(k in config for k in required_keys):
            logging.error("Configuration file missing required keys. Using defaults.")
            return dict(DEFAULT_CONFIG)
        if not isinstance(config["sensors"], list) or len(config["sensors"]) == 0:
            logging.error("Sensors list is empty or invalid. Using defaults.")
            return dict(DEFAULT_CONFIG)
        return config
    except (json.JSONDecodeError, OSError) as e:
        logging.error(f"Error loading configuration: {e}. Using defaults.")
        return dict(DEFAULT_CONFIG)


def measure_distance(trigger_pin, echo_pin, offset, max_distance):
    if DigitalOutputDevice is None or DigitalInputDevice is None:
        logging.error("gpiozero not available; cannot measure distance.")
        return None
    try:
        trigger = DigitalOutputDevice(trigger_pin)
        echo = DigitalInputDevice(echo_pin)
        trigger.off()
        time.sleep(0.05)
        trigger.on()
        time.sleep(0.00001)
        trigger.off()
        timeout = time.time() + 0.05
        while echo.value == 0:
            if time.time() > timeout:
                logging.warning(f"Timeout waiting for echo rising edge on pin {echo_pin}")
                trigger.close()
                echo.close()
                return None
        pulse_start = time.time()
        timeout = time.time() + 0.05
        while echo.value == 1:
            if time.time() > timeout:
                logging.warning(f"Timeout waiting for echo falling edge on pin {echo_pin}")
                trigger.close()
                echo.close()
                return None
        pulse_end = time.time()
        pulse_duration = pulse_end - pulse_start
        distance = (pulse_duration * 34300) / 2
        distance += offset
        water_level = max_distance - distance
        trigger.close()
        echo.close()
        return water_level
    except Exception as e:
        logging.error(f"Error measuring distance on trigger {trigger_pin}, echo {echo_pin}: {e}")
        return None


def log_data(log_file, sensor_id, water_level, alert_message=None):
    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    log_entry = f"{timestamp} - Sensor {sensor_id}: Water Level = {water_level:.2f} cm"
    if alert_message:
        log_entry += f" - Alert: {alert_message}"
    try:
        with open(log_file, "a") as f:
            f.write(log_entry + "\n")
    except OSError as e:
        print(f"Error writing to log file: {e}")


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    config = load_config()
    log_file = config["log_file"]
    logging.basicConfig(
        filename=log_file,
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )
    logging.info("Water level monitoring system started.")
    sensor_data = {}
    last_alert_time = {}
    consecutive_errors = {}
    for sensor in config["sensors"]:
        sensor_id = sensor["trigger_pin"]
        sensor_data[sensor_id] = []
        last_alert_time[sensor_id] = None
        consecutive_errors[sensor_id] = 0
    try:
        while _running:
            sensor_readings = {}
            for sensor in config["sensors"]:
                sensor_id = sensor["trigger_pin"]
                distances = []
                for _ in range(3):
                    distance = measure_distance(
                        sensor["trigger_pin"],
                        sensor["echo_pin"],
                        sensor["offset"],
                        sensor["max_distance"],
                    )
                    if distance is not None:
                        distances.append(distance)
                if distances:
                    water_level = statistics.median(distances)
                    sensor_readings[sensor_id] = water_level
                    sensor_data[sensor_id].append(water_level)
                    if len(sensor_data[sensor_id]) > 5:
                        sensor_data[sensor_id].pop(0)
                    consecutive_errors[sensor_id] = 0
                else:
                    logging.warning(f"Failed to get valid reading from sensor {sensor_id}")
                    consecutive_errors[sensor_id] += 1
                    if consecutive_errors[sensor_id] >= 5:
                        logging.error(f"Sensor {sensor_id} failed 5 consecutive readings. Excluding.")
                        sensor_readings[sensor_id] = None
                    else:
                        sensor_readings[sensor_id] = None
            valid_readings = [r for r in sensor_readings.values() if r is not None]
            if valid_readings:
                average_water_level = sum(valid_readings) / len(valid_readings)
                logging.info(f"Average Water Level: {average_water_level:.2f} cm")
                for sensor in config["sensors"]:
                    sensor_id = sensor["trigger_pin"]
                    water_level = sensor_readings.get(sensor_id)
                    if water_level is not None:
                        log_data(log_file, sensor_id, water_level)
                        if water_level < config["alert_threshold_low"]:
                            if (last_alert_time[sensor_id] is None or
                                    (time.time() - last_alert_time[sensor_id] > config["alert_repeat_delay"])):
                                logging.warning(f"Low water level alert for sensor {sensor_id}: {water_level:.2f} cm")
                                log_data(log_file, sensor_id, water_level, "Low water level")
                                last_alert_time[sensor_id] = time.time()
                        elif water_level > config["alert_threshold_high"]:
                            if (last_alert_time[sensor_id] is None or
                                    (time.time() - last_alert_time[sensor_id] > config["alert_repeat_delay"])):
                                logging.warning(f"High water level alert for sensor {sensor_id}: {water_level:.2f} cm")
                                log_data(log_file, sensor_id, water_level, "High water level")
                                last_alert_time[sensor_id] = time.time()
            else:
                logging.warning("No valid sensor readings.")
            time.sleep(5)
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        logging.info("Water level monitoring system stopped.")
        if DigitalOutputDevice is not None:
            for sensor in config["sensors"]:
                try:
                    DigitalOutputDevice(sensor["trigger_pin"]).close()
                except Exception:
                    pass
                try:
                    DigitalInputDevice(sensor["echo_pin"]).close()
                except Exception:
                    pass


if __name__ == "__main__":
    main()

