import cv2
import pyzbar.pyzbar as pyzbar
import time
import datetime
import os
import configparser
import logging
import threading
import queue
import signal
import sys

CONFIG_FILE = 'config.ini'
LOG_FILE = 'inventory.log'
BACKUP_LOG_FILE = 'backup_inventory.log'

DEFAULT_CONFIG = {
    'motion_threshold': '25',
    'redundancy_time_window': '5.0',
    'cloud_upload_interval': '60',
    'frame_buffer_size': '5',
    'reinit_delay': '2.0'
}

class CameraHandler:
    def __init__(self, camera_id, config):
        self.camera_id = camera_id
        self.config = config
        self.cap = None
        self.frame_buffer = queue.Queue(maxsize=config['frame_buffer_size'])
        self.running = True
        self.last_qr_code = None
        self.last_qr_time = 0.0
        self.last_upload_time = 0.0
        self.lock = threading.Lock()
        self.logger = logging.getLogger(f'camera_{camera_id}')
        self.logger.setLevel(logging.INFO)
        self.logger.addHandler(logging.StreamHandler())

    def initialize_camera(self):
        try:
            self.cap = cv2.VideoCapture(self.camera_id)
            if not self.cap.isOpened():
                self.logger.error(f"Failed to open camera {self.camera_id}")
                return False
            self.logger.info(f"Camera {self.camera_id} initialized successfully.")
            return True
        except Exception as e:
            self.logger.error(f"Error initializing camera {self.camera_id}: {e}")
            return False

    def capture_frame(self):
        if self.cap is None:
            return None
        try:
            ret, frame = self.cap.read()
            if not ret:
                self.logger.error(f"Failed to capture frame from camera {self.camera_id}")
                return None
            return frame
        except Exception as e:
            self.logger.error(f"Error capturing frame from camera {self.camera_id}: {e}")
            return None

    def process_frame(self, frame):
        try:
            gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            return gray
        except Exception as e:
            self.logger.error(f"Error processing frame from camera {self.camera_id}: {e}")
            return None

    def detect_motion(self, frame1, frame2):
        try:
            diff = cv2.absdiff(frame1, frame2)
            _, thresh = cv2.threshold(diff, int(self.config['motion_threshold']), 255, cv2.THRESH_BINARY)
            motion = cv2.countNonZero(thresh)
            return motion > 0
        except Exception as e:
            self.logger.error(f"Error detecting motion in camera {self.camera_id}: {e}")
            return False

    def decode_qr_code(self, frame):
        try:
            decoded_objects = pyzbar.decode(frame)
            for obj in decoded_objects:
                qr_data = obj.data.decode('utf-8')
                return qr_data
            return None
        except Exception as e:
            self.logger.error(f"Error decoding QR code in camera {self.camera_id}: {e}")
            return None

    def log_inventory(self, qr_data):
        timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        log_message = f"{timestamp} - Camera {self.camera_id} - QR Code: {qr_data}\n"
        try:
            with open(LOG_FILE, 'a') as f:
                f.write(log_message)
        except Exception as e:
            self.logger.error(f"Error writing to log file: {e}. Writing to backup log.")
            try:
                with open(BACKUP_LOG_FILE, 'a') as f:
                    f.write(log_message)
            except Exception as backup_e:
                self.logger.error(f"Error writing to backup log file: {backup_e}")

    def upload_to_cloud(self):
        try:
            with open(LOG_FILE, 'r') as f:
                data = f.read()
            print(f"Simulating cloud upload for camera {self.camera_id}: {data}")
            with open(LOG_FILE, 'w') as f:
                f.write("")
            self.last_upload_time = time.time()
        except FileNotFoundError:
            self.logger.warning(f"Log file not found for camera {self.camera_id}. Skipping cloud upload.")
        except Exception as e:
            self.logger.error(f"Error uploading to cloud for camera {self.camera_id}: {e}")

    def run(self):
        if not self.initialize_camera():
            return
        previous_frame = None
        while self.running:
            frame = self.capture_frame()
            if frame is None:
                self.logger.error(f"Failed to capture frame from camera {self.camera_id}. Reinitializing...")
                self.cap.release()
                time.sleep(float(self.config['reinit_delay']))
                if not self.initialize_camera():
                    self.logger.error(f"Failed to reinitialize camera {self.camera_id}. Stopping thread.")
                    break
                continue
            processed_frame = self.process_frame(frame)
            if processed_frame is None:
                continue
            if previous_frame is not None:
                if self.detect_motion(previous_frame, processed_frame):
                    qr_data = self.decode_qr_code(processed_frame)
                    if qr_data:
                        with self.lock:
                            current_time = time.time()
                            if (qr_data != self.last_qr_code or
                                (current_time - self.last_qr_time) > float(self.config['redundancy_time_window'])):
                                self.log_inventory(qr_data)
                                self.last_qr_code = qr_data
                                self.last_qr_time = current_time
                                self.last_upload_time = 0.0
            previous_frame = processed_frame
            if not self.frame_buffer.full():
                self.frame_buffer.put(frame)
            if (time.time() - self.last_upload_time) > int(self.config['cloud_upload_interval']):
                self.upload_to_cloud()
        self.cap.release()
        self.logger.info(f"Camera {self.camera_id} thread stopped.")

class CameraManager:
    def __init__(self, config):
        self.config = config
        self.cameras = {}
        self.threads = []
        self.running = True
        self.logger = logging.getLogger('camera_manager')
        self.logger.setLevel(logging.INFO)
        self.logger.addHandler(logging.StreamHandler())

    def add_camera(self, camera_id):
        handler = CameraHandler(camera_id, self.config)
        self.cameras[camera_id] = handler
        thread = threading.Thread(target=handler.run, daemon=True)
        self.threads.append(thread)
        thread.start()

    def stop(self):
        self.running = False
        for handler in self.cameras.values():
            handler.running = False
        for thread in self.threads:
            thread.join()

def load_config(config_file):
    config = configparser.ConfigParser()
    config.read(config_file)
    if not config.has_section('DEFAULT'):
        config.add_section('DEFAULT')
    for key, value in DEFAULT_CONFIG.items():
        if not config.has_option('DEFAULT', key):
            config.set('DEFAULT', key, value)
    return config['DEFAULT']

def main():
    config = load_config(CONFIG_FILE)
    logging.basicConfig(filename='system.log', level=logging.INFO,
                        format='%(asctime)s - %(name)s - %(levelname)s - %(message)s')
    manager = CameraManager(config)
    manager.add_camera(0)
    manager.add_camera(2)
    last_qr_code_time = time.time()
    def signal_handler(sig, frame):
        logging.info("Received interrupt signal. Shutting down...")
        manager.stop()
        sys.exit(0)
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    while True:
        time.sleep(1)
        if time.time() - last_qr_code_time > 30:
            logging.warning("Watchdog triggered: No QR code detected for 30 seconds. Restarting program.")
            os.execv(sys.executable, [sys.executable] + sys.argv)
        for handler in manager.cameras.values():
            with handler.lock:
                if handler.last_qr_time > last_qr_code_time:
                    last_qr_code_time = handler.last_qr_time

if __name__ == "__main__":
    main()

