import sys
import select
import signal
import time
import os
from typing import Tuple, Optional

import cv2
import pygame.mixer
from gpiozero import Button, OutputDevice

import config
import face

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_camera: Optional[cv2.VideoCapture] = None
_door: Optional["hardware.Door"] = None
_button: Optional[Button] = None
_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


class HardwareError(Exception):
    pass


class FaceRecognitionError(Exception):
    pass


class SoundError(Exception):
    pass


# ---------------------------------------------------------------------------
# Sound helpers
# ---------------------------------------------------------------------------
def init_sounds() -> Tuple[pygame.mixer.Sound, pygame.mixer.Sound, pygame.mixer.Sound]:
    """Initialize pygame mixer and load welcome/wait/later sounds on channels 0/1/2."""
    try:
        pygame.mixer.init(frequency=48000, size=-16, channels=1, buffer=1024)
    except pygame.error as exc:
        raise SoundError(f"pygame.mixer.init() failed: {exc}") from exc

    sound_paths = {
        "welcome": config.WELCOME_SOUND_PATH,
        "wait": config.WAIT_SOUND_PATH,
        "later": config.LATER_SOUND_PATH,
    }
    sounds: dict[str, pygame.mixer.Sound] = {}
    for name, path in sound_paths.items():
        if not os.path.isfile(path):
            raise SoundError(f"Sound file not found: {path}")
        try:
            sounds[name] = pygame.mixer.Sound(path)
        except pygame.error as exc:
            raise SoundError(f"Failed to load {name} sound '{path}': {exc}") from exc

    channels = [pygame.mixer.Channel(i) for i in range(3)]
    return sounds["welcome"], sounds["wait"], sounds["later"]


# ---------------------------------------------------------------------------
# Face recognition
# ---------------------------------------------------------------------------
def get_camera() -> cv2.VideoCapture:
    """Open the camera via config.get_camera(); raise on failure."""
    try:
        camera = config.get_camera()
    except Exception as exc:
        raise FaceRecognitionError(f"config.get_camera() raised: {exc}") from exc
    if camera is None or not camera.isOpened():
        raise FaceRecognitionError("Camera could not be opened.")
    return camera


def detect_and_recognize(camera: cv2.VideoCapture) -> bool:
    """Capture a frame, detect a single face, and return True if recognized."""
    ret, image = camera.read()
    if not ret or image is None:
        raise FaceRecognitionError("Could not read image from camera.")

    gray_image = cv2.cvtColor(image, cv2.COLOR_RGB2GRAY)
    face_coords = face.detect_single(gray_image)
    if face_coords is None:
        raise FaceRecognitionError("Could not detect a single face.")

    x, y, w, h = face_coords
    cropped = face.crop(gray_image, x, y, w, h)
    resized = face.resize(cropped)

    label, confidence = config.FACE_RECOGNIZER.predict(resized)
    print(f"Predicted label: {label}, Confidence: {confidence}")

    return label == config.POSITIVE_LABEL and confidence < config.POSITIVE_THRESHOLD


# ---------------------------------------------------------------------------
# Door hardware
# ---------------------------------------------------------------------------
class Door:
    """Thin wrapper around gpiozero OutputDevice for a door lock.

    BCM 17: HIGH = locked, LOW = unlocked.
    """

    def __init__(self, lock_pin: int = 17):
        self._lock = OutputDevice(lock_pin, active_high=True, initial_value=True)

    @property
    def is_locked(self) -> bool:
        return self._lock.is_active

    def lock(self) -> None:
        self._lock.on()

    def unlock(self) -> None:
        self._lock.off()

    def cleanup(self) -> None:
        self._lock.close()


def get_button() -> Button:
    """Return a gpiozero Button on BCM 5 with the internal pull-up enabled.

    Button connects to ground; is_pressed == True when pressed.
    """
    return Button(5, pull_up=True)


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main() -> None:
    global _camera, _door, _button

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # --- Load sounds -------------------------------------------------------
    try:
        welcome_sound, wait_sound, later_sound = init_sounds()
    except SoundError as exc:
        print(f"Sound initialization error: {exc}", file=sys.stderr)
        sys.exit(1)

    # --- Load face recognizer ----------------------------------------------
    if not os.path.isfile(config.TRAINING_FILE):
        print(f"Training file not found: {config.TRAINING_FILE}", file=sys.stderr)
        sys.exit(1)

    try:
        config.FACE_RECOGNIZER = cv2.face.EigenFaceRecognizer_create()
        config.FACE_RECOGNIZER.read(config.TRAINING_FILE)
    except cv2.error as exc:
        print(f"Error loading training data: {exc}", file=sys.stderr)
        sys.exit(1)

    # --- Initialize hardware -----------------------------------------------
    try:
        _camera = get_camera()
        _door = Door(lock_pin=17)
        _button = get_button()
    except (HardwareError, FaceRecognitionError) as exc:
        print(f"Hardware initialization error: {exc}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    print("Running Door Controller...")
    print("Press button to trigger face recognition.")
    print("Press 'l' + Enter to lock the door.")
    print("Press Ctrl-C to quit.")

    try:
        while _running:
            if _button.is_pressed:
                print("Button pressed, looking for face...")
                try:
                    if detect_and_recognize(_camera):
                        print("Recognized face! Unlocking Door...")
                        _door.unlock()
                        welcome_sound.play()
                    else:
                        print("Face not recognized.")
                        later_sound.play()
                        wait_sound.play()
                except FaceRecognitionError as exc:
                    print(f"Recognition error: {exc}", file=sys.stderr)
            elif _door.is_locked and select.select([sys.stdin], [], [], 0.1)[0]:
                line = sys.stdin.readline().strip().lower()
                if line == "l":
                    print("Locking Door...")
                    _door.lock()
                else:
                    print("Unknown command. Press 'l' to lock.")

            time.sleep(0.1)
    finally:
        cleanup()


def cleanup() -> None:
    global _camera, _door, _button
    if _camera is not None:
        _camera.release()
        _camera = None
    if _door is not None:
        _door.cleanup()
        _door = None
    if _button is not None:
        _button.close()
        _button = None
    pygame.mixer.quit()


if __name__ == "__main__":
    main()

