import serial
import sys
import signal

BLUETOOTH_PORT = "/dev/rfcomm4"
BLUETOOTH_BAUD_RATE = 38400


def open_bluetooth_connection(port: str, baudrate: int) -> serial.Serial:
    """Open a Bluetooth serial connection with robust error handling."""
    try:
        conn = serial.Serial(
            port=port,
            baudrate=baudrate,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            xonxoff=False,
            rtscts=False,
            dsrdtr=False,
            timeout=1.0,
        )
        print(f"Bluetooth connection established on {port} at {baudrate} baud.")
        return conn
    except serial.SerialException as e:
        print(f"Error opening Bluetooth connection on {port}: {e}", file=sys.stderr)
        raise


def send_command(connection: serial.Serial, command: str) -> bool:
    """Send a command string over the serial connection. Returns True on success."""
    try:
        payload = f"X{command}\n".encode("utf-8")
        bytes_written = connection.write(payload)
        connection.flush()
        print(f"Sent {bytes_written} bytes: {payload!r}")
        return True
    except serial.SerialException as e:
        print(f"Error sending command: {e}", file=sys.stderr)
        return False


def main_loop(connection: serial.Serial) -> None:
    """Main REPL loop for sending commands until 'q' or Ctrl+C."""
    print("Enter commands (Ctrl+C or 'q' to quit).")
    try:
        while True:
            try:
                user_input = input("Enter command: ")
            except EOFError:
                print("\nEOF received, exiting.")
                break

            if user_input.lower() == "q":
                print("Quit requested.")
                break

            if not send_command(connection, user_input):
                print("Transmission failed; continuing.", file=sys.stderr)
    except KeyboardInterrupt:
        print("\nInterrupted by user.")


def main() -> None:
    """Entry point: open connection, run loop, guarantee cleanup."""
    connection = None
    try:
        connection = open_bluetooth_connection(BLUETOOTH_PORT, BLUETOOTH_BAUD_RATE)
        main_loop(connection)
    except serial.SerialException:
        sys.exit(1)
    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        if connection is not None and connection.is_open:
            connection.close()
            print("Bluetooth connection closed.")


if __name__ == "__main__":
    main()

