import time
import datetime
import threading
import queue
import json
import logging
import logging.handlers
import numpy as np
import matplotlib.pyplot as plt
import signal
import sys
import os

try:
    from picamera2 import Picamera2
except ImportError:
    Picamera2 = None

CONFIG_FILE = "config.json"
DEFAULT_CONFIG = {
    "sampling_rate": 5,
    "motion_detection_threshold": 1.0,
    "logging_file_path": "beehive.log",
    "log_max_size": 1048576,
    "enable_camera": False
}

config = DEFAULT_CONFIG.copy()
logger = None
thermal_data_queue = queue.Queue(maxsize=300)
stop_event = threading.Event()
camera = None
bus = None
amg = None

def load_config():
    global config
    try:
        with open(CONFIG_FILE, "r") as f:
            user_config = json.load(f)
        config.update(user_config)
        logger.info("Configuration loaded from %s", CONFIG_FILE)
    except FileNotFoundError:
        logger.warning("Configuration file not found. Using default settings.")
    except json.JSONDecodeError as e:
        logger.error("Invalid JSON in configuration file: %s. Using default settings.", e)
    except Exception as e:
        logger.error("Error loading configuration: %s. Using default settings.", e)

def setup_logging():
    global logger
    log_file_path = config.get("logging_file_path", DEFAULT_CONFIG["logging_file_path"])
    log_max_size = config.get("log_max_size", DEFAULT_CONFIG["log_max_size"])
    try:
        logger = logging.getLogger("BeehiveMonitor")
        logger.setLevel(logging.INFO)
        handler = logging.handlers.RotatingFileHandler(
            log_file_path, maxBytes=log_max_size, backupCount=1
        )
        formatter = logging.Formatter("%(asctime)s - %(levelname)s - %(message)s")
        handler.setFormatter(formatter)
        logger.addHandler(handler)
        console = logging.StreamHandler()
        console.setFormatter(formatter)
        logger.addHandler(console)
        logger.info("Logging initialized.")
    except Exception as e:
        print(f"Failed to set up logging: {e}", file=sys.stderr)
        sys.exit(1)

def init_thermal_sensor():
    global bus, amg
    max_retries = 3
    for attempt in range(max_retries):
        try:
            bus = smbus2.SMBus(1)
            amg = adafruit_amg88xx.AMG88XX(bus, addr=0x69)
            logger.info("Thermal sensor initialized successfully.")
            return True
        except Exception as e:
            logger.error("Failed to initialize thermal sensor (attempt %d/%d): %s", attempt + 1, max_retries, e)
            if bus:
                try:
                    bus.close()
                except Exception:
                    pass
                bus = None
            if attempt < max_retries - 1:
                time.sleep(2)
    logger.error("Failed to initialize thermal sensor after %d attempts. Exiting.", max_retries)
    return False

def init_camera():
    global camera
    if not config.get("enable_camera", False):
        logger.info("Camera disabled in config. Skipping camera initialization.")
        return False
    if Picamera2 is None:
        logger.warning("picamera2 library not installed. Camera disabled.")
        config["enable_camera"] = False
        return False
    try:
        camera = Picamera2()
        camera.configure(camera.create_still_configuration())
        camera.start()
