        except Exception as e:
            logger.error("Error in motion detection: %s", e)
        time.sleep(5)

def capture_image():
    global camera
    timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
    filename = f"image_{timestamp}.jpg"
    try:
        if camera is None:
            init_camera()
        if camera is not None:
            camera.capture_file(filename)
            logger.info("Image captured: %s", filename)
    except Exception as e:
        logger.error("Error capturing image: %s", e)

def plot_thermal_data():
    while not stop_event.is_set():
        try:
            if not thermal_data_queue.empty():
                thermal_data = thermal_data_queue.get()
                plt.clf()
                plt.imshow(thermal_data, cmap='jet', interpolation='nearest')
                plt.colorbar()
                plt.title(f"Thermal Image - {datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')}")
                plt.pause(0.001)
        except Exception as e:
            logger.error("Error plotting thermal data: %s", e)
        time.sleep(5)

def signal_handler(sig, frame):
    logger.info("Received signal %d. Shutting down...", sig)
    stop_event.set()
    if camera:
        try:
            camera.stop()
            camera.close()
        except Exception as e:
            logger.error("Error closing camera: %s", e)
    if bus:
        try:
            bus.close()
        except Exception as e:
            logger.error("Error closing I2C bus: %s", e)
    plt.close('all')
    logger.info("Shutdown complete.")
    sys.exit(0)

def main():
    global logger
    setup_logging()
    load_config()
    if not init_thermal_sensor():
        sys.exit(1)
    init_camera()
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    threads = [
        threading.Thread(target=thermal_data_thread, daemon=True),
        threading.Thread(target=detect_motion, daemon=True),
        threading.Thread(target=plot_thermal_data, daemon=True)
    ]
    for t in threads:
        t.start()
    while not stop_event.is_set():
        time.sleep(1)
    for t in threads:
        t.join(timeout=5)
    if camera:
        try:
