import io
import logging
import signal
import threading
import numpy as np
import cv2

logger = logging.getLogger(__name__)


class WebSocketHandler:
    """Stub WebSocket handler exposing the required interface."""

    def has_connections(self) -> bool:
        return False

    def broadcast(self, data: bytes) -> None:
        pass


class CameraStreamBuffer:
    """
    Receives raw JPEG bytes from picamera2, detects JPEG frame boundaries
    via the \xff\xd8 marker, and broadcasts complete frames over WebSocket.
    """

    JPEG_START_MARKER = b'\xff\xd8'

    def __init__(self, websocket_handler: WebSocketHandler):
        if not isinstance(websocket_handler, WebSocketHandler):
            raise TypeError("websocket_handler must be an instance of WebSocketHandler")
        self.websocket_handler = websocket_handler
        self.buffer = io.BytesIO()
        self.lock = threading.Lock()

    def write(self, data: bytes) -> int:
        """Write raw JPEG bytes; returns number of bytes consumed."""
        if not isinstance(data, (bytes, memoryview)):
            raise TypeError("data must be bytes or memoryview")
        if not data:
            return 0
        try:
            with self.lock:
                # Find the start of the first JPEG marker in the incoming chunk
                start_idx = data.find(self.JPEG_START_MARKER)
                if start_idx != -1:
                    # Flush any partial frame already in buffer
                    self._broadcast_if_ready()
                    # Consume bytes before the marker (should be zero or trailing)
                    data = data[start_idx:]
                # Write remaining data to the buffer
                self.buffer.write(data)
                # Broadcast if a complete JPEG is now available
                self._broadcast_if_ready()
            return len(data)
        except Exception as e:
            logger.error("Error in CameraStreamBuffer.write: %s", e)
            return 0

    def _broadcast_if_ready(self) -> None:
        """Check if the buffer contains a complete JPEG and broadcast it."""
        try:
            if self.buffer.tell() >= 2:
                self.buffer.seek(0)
                marker = self.buffer.read(2)
                self.buffer.seek(0)
                if marker == self.JPEG_START_MARKER:
                    frame_data = self.buffer.getvalue()
                    if self.websocket_handler.has_connections():
                        self.websocket_handler.broadcast(frame_data)
        except Exception as e:
            logger.error("Error broadcasting frame: %s", e)

    def flush(self) -> None:
        """Emit any remaining buffered frame."""
        try:
            with self.lock:
                if self.buffer.tell() > 0:
                    self._broadcast_if_ready()
                    self.buffer.seek(0)
                    self.buffer.truncate()
        except Exception as e:
            logger.error("Error flushing CameraStreamBuffer: %s", e)


class MotionDetectionBuffer:
    """
    Receives raw JPEG bytes from picamera2, detects JPEG frame boundaries
    via the \xff\xd8 marker, decodes frames into OpenCV BGR images, and
    runs motion detection between consecutive frames.
    """

    JPEG_START_MARKER = b'\xff\xd8'

    def __init__(self, detect_motion_function):
        if not callable(detect_motion_function):
            raise TypeError("detect_motion_function must be callable")
        self.detect_motion_function = detect_motion_function
        self.buffer = io.BytesIO()
        self.lock = threading.Lock()
        self.previous_frame = None
        self.current_frame = None

    def _convert_to_opencv_frame(self, frame_data: bytes):
        """Decode JPEG bytes into an OpenCV BGR image."""
        try:
            data = np.frombuffer(frame_data, dtype=np.uint8)
            frame = cv2.imdecode(data, cv2.IMREAD_COLOR)
            if frame is None:
                logger.error("Failed to decode frame data (imdecode returned None)")
                return None
            return frame
        except Exception as e:
            logger.error("Error converting frame data: %s", e)
            return None

    def write(self, data: bytes) -> int:
        """Write raw JPEG bytes; returns number of bytes consumed."""
        if not isinstance(data, (bytes, memoryview)):
            raise TypeError("data must be bytes or memoryview")
        if not data:
            return 0
        try:
            with self.lock:
                # Find the start of the first JPEG marker in the incoming chunk
                start_idx = data.find(self.JPEG_START_MARKER)
                if start_idx != -1:
                    # Flush any partial frame already in buffer
                    self._process_frame()
                    # Consume bytes before the marker (should be zero or trailing)
                    data = data[start_idx:]
                # Write remaining data to the buffer
                self.buffer.write(data)
                # Process if a complete JPEG is now available
                self._process_frame()
            return len(data)
        except Exception as e:
            logger.error("Error in MotionDetectionBuffer.write: %s", e)
            return 0

    def _process_frame(self) -> None:
        """Check if the buffer contains a complete JPEG and run motion detection."""
        try:
            if self.buffer.tell() >= 2:
                self.buffer.seek(0)
                marker = self.buffer.read(2)
                self.buffer.seek(0)
                if marker == self.JPEG_START_MARKER:
                    frame_data = self.buffer.getvalue()
                    self.previous_frame = self.current_frame
                    self.current_frame = self._convert_to_opencv_frame(frame_data)
                    if self.previous_frame is not None and self.current_frame is not None:
                        self.detect_motion_function(self.previous_frame, self.current_frame)
                    # Reset buffer for next frame
                    self.buffer.seek(0)
                    self.buffer.truncate()
        except Exception as e:
            logger.error("Error processing frame: %s", e)

    def flush(self) -> None:
        """Process any remaining buffered frame."""
        try:
            with self.lock:
                if self.buffer.tell() > 0:
                    self._process_frame()
                    self.buffer.seek(0)
                    self.buffer.truncate()
        except Exception as e:
            logger.error("Error flushing MotionDetectionBuffer: %s", e)


def _signal_handler(signum, frame, stream_buffer=None, motion_buffer=None):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    logger.info("Received signal %s, shutting down...", signum)
    if stream_buffer is not None:
        stream_buffer.flush()
    if motion_buffer is not None:
        motion_buffer.flush()


def main():
    logging.basicConfig(level=logging.INFO)

    ws_handler = WebSocketHandler()
    stream_buffer = CameraStreamBuffer(ws_handler)
    motion_buffer = MotionDetectionBuffer(
        lambda prev, curr: logger.info("Motion detected between frames")
    )

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, lambda s, f: _signal_handler(s, f, stream_buffer, motion_buffer))
    signal.signal(signal.SIGTERM, lambda s, f: _signal_handler(s, f, stream_buffer, motion_buffer))

    logger.info("Buffers initialized. Running capture loop (Ctrl+C to stop).")
    try:
        while True:
            signal.pause()
    except KeyboardInterrupt:
        pass
    finally:
        stream_buffer.flush()
        motion_buffer.flush()
        logger.info("Shutdown complete.")


if __name__ == "__main__":
    main()

