import io
import logging
import numpy as np
import cv2
from picamera2 import Picamera2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class CameraStreamBuffer:
    """Accumulates a picamera2 MJPEG stream and flushes non-I-frame H.264 frames to a sink."""

    def __init__(self, c: Picamera2):
        if c is None:
            raise ValueError("Picamera2 instance must not be None")
        self.c = c
        self.b = io.BytesIO()

    def write(self, d: bytes) -> int:
        try:
            self.b.write(d)
            # picamera2 exposes frame metadata via the encode pass; a complete frame
            # arrives with non-empty metadata.  We flush when the frame is complete
            # and is not an I-frame (frame_type != 1).
            meta = self.c.capture_metadata()
            if meta is not None and meta.get('encode') is not None:
                frame_type = meta.get('encode', {}).get('frame_type')
                if frame_type is not None and frame_type != 1:
                    self.flush()
        except Exception as e:
            logger.error("Error in CameraStreamBuffer.write: %s", e)
        return len(d)

    def flush(self):
        try:
            data = self.b.getvalue()
            if data:
                # In a real MJPEG-over-H.264 pipeline, the raw H.264 bytes are forwarded.
                # For this exercise we log the frame size; a real application would push
                # data to a network socket or file.
                logger.debug("Flushed frame: %d bytes", len(data))
            self.b.seek(0)
            self.b.truncate()
        except Exception as e:
            logger.error("Error in CameraStreamBuffer.flush: %s", e)


