import signal
import sys
import time
import smbus2
from luma.core.interface.serial import i2c
from luma.oled.device import ssd1306

# I2C addresses
LIGHT_SENSOR_ADDR = 0x23
OLED_ADDR = 0x3C
I2C_BUS = 1

# BH1750 commands
BH1750_POWER_ON = 0x01
BH1750_RESET = 0x07
BH1750_ONE_TIME_HIGH_RES = 0x20

# Global resources for cleanup
bus = None
display = None
running = True


def cleanup(signum=None, frame=None):
    """Release resources and clear the display on exit."""
    global running, display, bus
    running = False
    if display is not None:
        try:
            display.clear()
        except Exception:
            pass
    if bus is not None:
        try:
            bus.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


def init_i2c_bus():
    """Initialize the I2C bus; return None on failure."""
    try:
        return smbus2.SMBus(I2C_BUS)
    except FileNotFoundError:
        print("Error: I2C bus /dev/i2c-1 not found. Enable I2C with 'sudo raspi-config'.")
        return None
    except PermissionError:
        print("Error: Permission denied on /dev/i2c-1. Run as root or add user to the 'i2c' group.")
        return None
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None


def init_oled():
    """Initialize the SSD1306 OLED display; return None on failure."""
    try:
        serial = i2c(port=I2C_BUS, address=OLED_ADDR)
        return ssd1306(serial)
    except Exception as e:
        print(f"Error initializing OLED display at 0x{OLED_ADDR:02X}: {e}")
        return None


def read_light_level(i2c_bus):
    """Read ambient light in lux from the BH1750FVI sensor.

    Returns (lux, error_flag). On error or sensor-absent, lux is None.
    """
    try:
        # Power on the sensor (required after power-off or reset)
        i2c_bus.write_byte(LIGHT_SENSOR_ADDR, BH1750_POWER_ON)
        time.sleep(0.01)

        # Send One-Time High-Resolution Mode command
        i2c_bus.write_byte(LIGHT_SENSOR_ADDR, BH1750_ONE_TIME_HIGH_RES)

        # Wait for conversion (max ~180 ms for high-res mode; 120 ms is safe)
        time.sleep(0.12)

        # Read two bytes (MSB first)
        data = i2c_bus.read_i2c_block_data(LIGHT_SENSOR_ADDR, 0x00, 2)
        if len(data) < 2:
            print("Warning: Incomplete data read from BH1750.")
            return None, True

        raw = (data[0] << 8) | data[1]
        lux = raw / 1.2
        return lux, False

    except OSError as e:
        print(f"Warning: I2C bus error reading BH1750 (sensor may be absent): {e}")
        return None, True
    except Exception as e:
        print(f"Warning: Unexpected error reading BH1750: {e}")
        return None, True


def map_to_contrast(lux):
    """Map lux value to a contrast byte (0-255), clamped."""
    if lux is None:
        return 0
    # Linear mapping: 0 lux -> 0 contrast, 1000 lux -> 255 contrast
    contrast = int((lux / 1000.0) * 255)
    return max(0, min(contrast, 255))


def main():
    global bus, display

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    bus = init_i2c_bus()
    if bus is None:
        sys.exit(1)

    display = init_oled()
    if display is None:
        bus.close()
        sys.exit(1)

    last_lux = None

    try:
        while running:
            lux, error = read_light_level(bus)

            if error:
                # Keep previous value on error; warn once per cycle
                if lux is None:
                    print("Warning: Sensor read failed; keeping previous contrast.")
                lux = last_lux

            if lux is not None:
                last_lux = lux
                contrast = map_to_contrast(lux)
                try:
                    display.contrast(contrast)
                    print(f"Lux: {lux:.1f}  |  Contrast: {contrast}")
                except Exception as e:
                    print(f"Warning: Failed to set OLED contrast: {e}")

            time.sleep(1)

    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

