import adafruit_bme280
import adafruit_tsl2561

# Global resources for cleanup
i2c_bus = None
display = None
bme280 = None
tsl2561 = None
running = True

def cleanup():
    """Release resources and clear the display."""
    global display, i2c_bus
    if display is not None:
        try:
            display.fill(0)
            display.show()
        except Exception:
            pass
    if i2c_bus is not None:
        try:
            i2c_bus.deinit()
        except Exception:
            pass

def signal_handler(sig, frame):
    """Handle SIGINT for graceful shutdown."""
    global running
    running = False

def init_i2c():
    """Initialize the I2C bus on GPIO3 (SCL) and GPIO2 (SDA)."""
    global i2c_bus
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C bus: {e}", file=sys.stderr)
        return None

def init_display(i2c):
    """Initialize the SSD1306 OLED display at address 0x3C."""
    global display
    try:
        display = adafruit_ssd1306.SSD1306_I2C(128, 64, i2c, addr=0x3C)
        display.fill(0)
        display.show()
        return display
    except Exception as e:
        print(f"Error initializing SSD1306 display: {e}", file=sys.stderr)
        return None

def init_bme280(i2c):
    """Initialize the BME280 sensor at address 0x76."""
    global bme280
    try:
        bme280 = adafruit_bme280.Adafruit_BME280_I2C(i2c, address=0x76)
        return bme280
    except Exception as e:
        print(f"Error initializing BME280 sensor: {e}", file=sys.stderr)
        return None

def init_tsl2561(i2c):
    """Initialize the TSL2561 luminosity sensor at address 0x39."""
    global tsl2561
    try:
        tsl2561 = adafruit_tsl2561.TSL2561(i2c, address=0x39)
        tsl2561.enabled = True
        return tsl2561
    except Exception as e:
        print(f"Error initializing TSL2561 sensor: {e}", file=sys.stderr)
        return None

def read_sensor_data(bme, tsl):
    """Read sensor data, handling transient read errors."""
    temperature = None
    humidity = None
    pressure = None
    light = None

    if bme is not None:
        try:
            temperature = bme.temperature
            humidity = bme.humidity
            pressure = bme.pressure
        except Exception as e:
            print(f"Error reading BME280 data: {e}", file=sys.stderr)

    if tsl is not None:
        try:
            light = tsl.lux
        except Exception as e:
            print(f"Error reading TSL2561 data: {e}", file=sys.stderr)

    return temperature, humidity, pressure, light

def update_display(disp, temp, hum, pres, light):
    """Update the OLED display with sensor readings."""
    if disp is None:
        return
    try:
        disp.fill(0)
        if temp is not None:
            disp.text(f"Temp: {temp:.1f} C", 0, 0, 1)
        else:
            disp.text("Temp: N/A", 0, 0, 1)
        if hum is not None:
            disp.text(f"Humidity: {hum:.1f} %", 0, 16, 1)
        else:
            disp.text("Humidity: N/A", 0, 16, 1)
        if pres is not None:
            disp.text(f"Pressure: {pres:.1f} hPa", 0, 32, 1)
        else:
            disp.text("Pressure: N/A", 0, 32, 1)
        if light is not None:
            disp.text(f"Light: {light:.1f} lux", 0, 48, 1)
        else:
            disp.text("Light: N/A", 0, 48, 1)
        disp.show()
    except Exception as e:
        print(f"Error updating display: {e}", file=sys.stderr)

