import time
import sys
import board
import adafruit_dht

# DHT11 requires at least 1 second between reads; use 2 s for safety.
RETRY_DELAY_S = 2.0
MAX_RETRIES = 5
SENSOR_PIN = board.D4  # BCM GPIO4 (physical pin 7)

def read_dht11(sensor):
    """Attempt to read temperature from the DHT11; return float or None."""
    try:
        temperature = sensor.temperature
        if temperature is None:
            return None
        return float(temperature)
    except RuntimeError as e:
        # Common DHT11 errors: checksum failure, timeout, or device not present.
        print(f"Sensor read error: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error reading sensor: {e}")
        return None

def main():
    sensor = None
    try:
        # Initialize the DHT11 on GPIO4.
        sensor = adafruit_dht.DHT11(SENSOR_PIN, use_pulseio=False)
        print("DHT11 sensor initialized on GPIO4.")

        for attempt in range(1, MAX_RETRIES + 1):
            temperature = read_dht11(sensor)
            if temperature is not None:
                print(f"Temperature: {temperature:.1f}°C")
                sys.exit(0)

            if attempt < MAX_RETRIES:
                print(f"Attempt {attempt}/{MAX_RETRIES} failed. Retrying in {RETRY_DELAY_S:.0f} s...")
                time.sleep(RETRY_DELAY_S)

        print(f"Error: Failed to read DHT11 after {MAX_RETRIES} attempts.")
        sys.exit(1)

    except KeyboardInterrupt:
        print("\nInterrupted by user. Exiting gracefully.")
        sys.exit(130)
    except Exception as e:
        print(f"Fatal error: {e}")
        sys.exit(1)
    finally:
        # Release the GPIO resource cleanly on every exit path.
        if sensor is not None:
            try:
                sensor.exit()
            except Exception:
                pass

if __name__ == "__main__":
    main()

