import asyncio
import json
import logging
import logging.handlers
import os
import signal
import sys
import time
from datetime import datetime

import RPi.GPIO as GPIO
import adafruit_dht
import board

DEFAULT_CONFIG = {
    "gpio_transmitter_pin": 17,
    "gpio_dht22_pin": 4,
    "dht22_read_interval": 60,
    "log_file": "greenhouse.log",
    "outlet_configurations": [
        {"name": "outlet1", "system_code": "10101", "unit_code": "1"},
        {"name": "outlet2", "system_code": "10101", "unit_code": "2"},
        {"name": "outlet3", "system_code": "10101", "unit_code": "3"},
    ],
}

SHORT_PULSE = 300
LONG_PULSE = 3 * SHORT_PULSE
DEBOUNCE_DELAY = 0.5
RETRY_DELAY = 0.1
MAX_RETRIES = 3

logger = logging.getLogger(__name__)
shutdown_event = asyncio.Event()


def setup_logging(log_file: str) -> None:
    logger.setLevel(logging.INFO)
    handler = logging.handlers.RotatingFileHandler(
        log_file, maxBytes=1024 * 1024, backupCount=5
    )
    formatter = logging.Formatter("%(asctime)s - %(levelname)s - %(message)s")
    handler.setFormatter(formatter)
    logger.addHandler(handler)
    console = logging.StreamHandler()
    console.setFormatter(formatter)
    logger.addHandler(console)


def load_config(config_file: str) -> dict:
    try:
        with open(config_file, "r") as f:
            cfg = json.load(f)
        required = ["gpio_transmitter_pin", "gpio_dht22_pin", "dht22_read_interval", "log_file", "outlet_configurations"]
        for key in required:
            if key not in cfg:
                raise ValueError(f"Missing required key: {key}")
        return cfg
    except FileNotFoundError:
        logger.warning("Configuration file not found. Using default configuration.")
        return DEFAULT_CONFIG.copy()
    except (json.JSONDecodeError, ValueError) as e:
        logger.error(f"Error parsing configuration file: {e}. Using default configuration.")
        return DEFAULT_CONFIG.copy()


def setup_gpio(transmitter_pin: int) -> None:
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(transmitter_pin, GPIO.OUT, initial=GPIO.LOW)


def transmit_code(system_code: str, unit_code: str, state: str, transmitter_pin: int) -> None:
    def pulse(duration: int) -> None:
        GPIO.output(transmitter_pin, GPIO.HIGH)
        time.sleep(duration / 1_000_000.0)
        GPIO.output(transmitter_pin, GPIO.LOW)
        time.sleep(duration / 1_000_000.0)

    code = system_code + unit_code + state
    for bit in code:
        if bit == "1":
            pulse(LONG_PULSE)
            pulse(SHORT_PULSE)
        else:
            pulse(SHORT_PULSE)
            pulse(LONG_PULSE)
    pulse(LONG_PULSE)
    pulse(LONG_PULSE)


async def send_outlet_command(outlet_name: str, state: str, transmitter_pin: int, outlet_configurations: list) -> None:
    outlet = next((o for o in outlet_configurations if o["name"] == outlet_name), None)
    if outlet is None:
        logger.error(f"Outlet '{outlet_name}' not found.")
        return
    system_code = outlet["system_code"]
    unit_code = outlet["unit_code"]
    for attempt in range(MAX_RETRIES):
        try:
            transmit_code(system_code, unit_code, state, transmitter_pin)
            logger.info(f"Sent command to {outlet_name} (state={state})")
            return
        except Exception as e:
            logger.error(f"Error sending command to {outlet_name} (attempt {attempt + 1}/{MAX_RETRIES}): {e}")
            if attempt < MAX_RETRIES - 1:
                await asyncio.sleep(RETRY_DELAY)
    logger.error(f"Failed to send command to {outlet_name} after {MAX_RETRIES} retries.")


async def read_dht22(gpio_dht22_pin: int) -> tuple[float | None, float | None]:
    try:
        dht_device = adafruit_dht.DHT22(getattr(board, f"D{gpio_dht22_pin}"))
    except Exception as e:
        logger.error(f"Failed to initialize DHT22 on BCM{gpio_dht22_pin}: {e}")
        return None, None
    try:
        temperature = dht_device.temperature
        humidity = dht_device.humidity
        if temperature is None or humidity is None:
            logger.warning("DHT22 returned None values.")
            return None, None
        logger.info(f"Temperature: {temperature:.2f} C, Humidity: {humidity:.2f} %")
        return temperature, humidity
    except RuntimeError as e:
        logger.error(f"DHT22 sensor read error (RuntimeError): {e}")
        return None, None
    except OSError as e:
        logger.error(f"DHT22 sensor read error (OSError): {e}")
        return None, None
    finally:
        try:
            dht_device.exit()
        except Exception:
            pass


async def sensor_reading_loop(gpio_dht22_pin: int, interval: int) -> None:
    while not shutdown_event.is_set():
        await read_dht22(gpio_dht22_pin)
        try:
            await asyncio.wait_for(shutdown_event.wait(), timeout=interval)
        except asyncio.TimeoutError:
            pass


async def main() -> None:
    config = load_config("greenhouse_config.json")
    setup_logging(config["log_file"])
    setup_gpio(config["gpio_transmitter_pin"])
    logger.info("Greenhouse controller started.")

    async def handle_signal(signum, frame):
        logger.info(f"Signal {signum} received. Shutting down...")
        shutdown_event.set()

    loop = asyncio.get_running_loop()
    for sig in (signal.SIGINT, signal.SIGTERM):
        try:
            loop.add_signal_handler(sig, lambda s=sig: asyncio.create_task(handle_signal(s, None)))
        except NotImplementedError:
            signal.signal(sig, lambda s, f: asyncio.create_task(handle_signal(s, f)))

    sensor_task = asyncio.create_task(sensor_reading_loop(config["gpio_dht22_pin"], config["dht22_read_interval"]))

    try:
        while not shutdown_event.is_set():
            try:
                command = await asyncio.wait_for(asyncio.get_event_loop().run_in_executor(None, input, "Enter command: "), timeout=1.0)
            except asyncio.TimeoutError:
                continue
            except EOFError:
                break
            parts = command.split()
            if not parts:
                continue
            cmd = parts[0].lower()
            if cmd == "on":
                if len(parts) < 2:
                    logger.error("Usage: on <outlet_name>")
                    continue
                await send_outlet_command(parts[1], "1", config["gpio_transmitter_pin"], config["outlet_configurations"])
            elif cmd == "off":
                if len(parts) < 2:
                    logger.error("Usage: off <outlet_name>")
                    continue
                await send_outlet_command(parts[1], "0", config["gpio_transmitter_pin"], config["outlet_configurations"])
            elif cmd == "status":
                logger.info("Status requested.")
            elif cmd == "exit":
                break
            else:
                logger.error(f"Unknown command: {cmd}")
            await asyncio.sleep(DEBOUNCE_DELAY)
    finally:
        sensor_task.cancel()
        try:
            await sensor_task
        except asyncio.CancelledError:
            pass
        GPIO.cleanup()
        logger.info("Greenhouse controller stopped.")


if __name__ == "__main__":
    try:
        asyncio.run(main())
    except KeyboardInterrupt:
        pass

