import signal
import sys
import time
import logging
from typing import Optional, Tuple

import smbus2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class DHT20:
    """Driver for the Aosong DHT20 I2C temperature and humidity sensor."""

    I2C_BUS = 1
    I2C_ADDRESS = 0x38
    STATUS_REG = 0x71
    MEASURE_REG = 0xAC
    MEASURE_CMD = [0x33, 0x00]
    TIMEOUT = 0.1
    POLL_INTERVAL = 0.01

    def __init__(self, bus_number: int = I2C_BUS, address: int = I2C_ADDRESS):
        self.bus_number = bus_number
        self.address = address
        self.bus: Optional[smbus2.SMBus] = None
        self._running = True

        try:
            self.bus = smbus2.SMBus(self.bus_number)
            logger.info(f"DHT20 initialized on I2C bus {self.bus_number} at address 0x{self.address:02X}")
        except FileNotFoundError:
            logger.error(f"I2C bus /dev/i2c-{self.bus_number} not found. Enable I2C with `sudo raspi-config`.")
            self.bus = None
        except PermissionError:
            logger.error(f"Permission denied opening /dev/i2c-{self.bus_number}. Run as root or add user to i2c group.")
            self.bus = None
        except OSError as e:
            logger.error(f"Failed to open I2C bus {self.bus_number}: {e}")
            self.bus = None
        except Exception as e:
            logger.error(f"Unexpected error initializing DHT20: {e}")
            self.bus = None

    def _write_command(self, register: int, data: list) -> bool:
        if self.bus is None:
            logger.error("I2C bus not initialized; cannot write command.")
            return False
        try:
            self.bus.write_i2c_block_data(self.address, register, data)
            return True
        except OSError as e:
            logger.error(f"I/O error writing to DHT20 register 0x{register:02X}: {e}")
            return False
        except Exception as e:
            logger.error(f"Unexpected error writing to DHT20: {e}")
            return False

    def _read_register(self, register: int, length: int) -> Optional[list]:
        if self.bus is None:
            logger.error("I2C bus not initialized; cannot read register.")
            return None
        try:
            return self.bus.read_i2c_block_data(self.address, register, length)
        except OSError as e:
            logger.error(f"I/O error reading from DHT20 register 0x{register:02X}: {e}")
            return None
        except Exception as e:
            logger.error(f"Unexpected error reading from DHT20: {e}")
            return None

    @staticmethod
    def _calculate_crc8(data: list) -> int:
        crc = 0xFF
        for byte in data:
            crc ^= byte
