import signal
import sys
import time

import gpiozero
from hcsr04sensor import HCSR04

TRIGGER_PIN = 17
ECHO_PIN = 18
LED_PIN = 2
SAFE_DISTANCE = 20

running = True
led = None
sensor = None


def handle_signal(signum, frame):
    global running
    running = False


def cleanup():
    global led, sensor
    if led is not None:
        try:
            led.close()
        except Exception:
            pass
        led = None
    if sensor is not None:
        try:
            sensor.cleanup()
        except Exception:
            pass
        sensor = None


def main():
    global led, sensor

    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        led = gpiozero.LED(LED_PIN)
    except Exception as e:
        print(f"Failed to initialize LED on GPIO{LED_PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        sensor = HCSR04(trigger_pin=TRIGGER_PIN, echo_pin=ECHO_PIN, temperature=20)
    except Exception as e:
        print(f"Failed to initialize HC-SR04 sensor: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    try:
        while running:
            try:
                distance = sensor.get_distance()
            except Exception as e:
                print(f"Sensor read error: {e}", file=sys.stderr)
                distance = SAFE_DISTANCE + 10

            print(f"Distance: {distance:.2f} cm, LED: {'ON' if led.is_lit else 'OFF'}")

            if distance <= SAFE_DISTANCE:
                led.on()
            else:
                led.off()

            time.sleep(0.1)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

