#!/usr/bin/env python3
"""Greenhouse vent controller: solenoid on GPIO17, DHT22 on GPIO4/GPIO23, limit switch on GPIO5."""

import RPi.GPIO as GPIO
import time
import datetime
import signal
import sys
import board
import adafruit_dht

# --- Pin assignments (BCM) ---
SOLENOID_PIN = 17
LIMIT_SWITCH_PIN = 5
DHT22_PINS = [4, 23]

# --- Thresholds ---
MAX_TEMP = 30
MIN_HUMIDITY = 60
HYSTERESIS = 2

# --- Timing ---
SOLENOID_DURATION = 5      # seconds to energize solenoid
TIMEOUT = 10               # seconds before limit switch must trigger
POLL_INTERVAL = 60         # seconds between control cycles

# --- Future limit switch placeholders ---
FUTURE_LIMIT_PINS = [5, 6, 12, 13, 16, 20, 21, 26]

# --- Logging ---
LOG_FILE = "greenhouse.log"

# --- Globals for cleanup ---
_running = True
_sensors = []


def log(message: str) -> None:
    """Append a timestamped message to the log file and stdout."""
    timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    line = f"{timestamp} - {message}"
    try:
        with open(LOG_FILE, "a") as f:
            f.write(line + "\n")
    except OSError as e:
        print(f"Log write error: {e}", file=sys.stderr)
    print(line)


def signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global _running
    _running = False
    log(f"Received signal {signum}, shutting down.")


def setup_gpio() -> None:
    """Configure all GPIO pins: solenoid output, limit switch input, future inputs."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)

    GPIO.setup(SOLENOID_PIN, GPIO.OUT, initial=GPIO.LOW)

    GPIO.setup(LIMIT_SWITCH_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    for pin in FUTURE_LIMIT_PINS:
        GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)


def init_sensors() -> list:
    """Initialize DHT22 sensors; return list of (pin, sensor_or_None)."""
    sensors = []
    for pin in DHT22_PINS:
        try:
            # Map BCM pin number to board pin name
            board_pin = {
                4: board.D4,
                23: board.D23,
            }[pin]
            sensor = adafruit_dht.DHT22(board_pin, use_pulseio=False)
            sensors.append((pin, sensor))
            log(f"DHT22 on GPIO{pin} initialized.")
        except Exception as e:
            log(f"Failed to initialize DHT22 on GPIO{pin}: {e}")
            sensors.append((pin, None))
    return sensors


def read_sensors(sensors: list):
    """Read all DHT22 sensors; return dict of last known values."""
    readings = {}
    for pin, sensor in sensors:
        if sensor is None:
            continue
        try:
            temp = sensor.temperature
            hum = sensor.humidity
            if temp is not None and hum is not None:
                readings[pin] = (temp, hum)
        except RuntimeError as e:
            # DHT22 occasionally fails; keep last known
            log(f"DHT22 read error on GPIO{pin}: {e}")
        except Exception as e:
            log(f"Unexpected DHT22 error on GPIO{pin}: {e}")
    return readings


def control_vent(temperature: float, humidity: float, readings: dict) -> None:
    """Energize solenoid for 5 s, monitor limit switch, handle timeout."""
    if temperature is None or humidity is None:
        log("No sensor data; skipping vent control.")
        return

    if temperature > MAX_TEMP and humidity < MIN_HUMIDITY:
        log("Opening vent: temp > MAX_TEMP and humidity < MIN_HUMIDITY.")
        GPIO.output(SOLENOID_PIN, GPIO.HIGH)
        start = time.monotonic()
        limit_triggered = False

        while _running and (time.monotonic() - start) < TIMEOUT:
            if GPIO.input(LIMIT_SWITCH_PIN) == GPIO.HIGH:
                limit_triggered = True
                break
            time.sleep(0.1)

        if limit_triggered:
            GPIO.output(SOLENOID_PIN, GPIO.LOW)
            log("Vent fully opened (limit switch triggered).")
        elif not _running:
            GPIO.output(SOLENOID_PIN, GPIO.LOW)
            log("Solenoid de-energized due to shutdown signal.")
        else:
            GPIO.output(SOLENOID_PIN, GPIO.LOW)
            log("Vent actuation timed out (limit switch not triggered).")

        # Log sensor readings after actuation
        for pin, (t, h) in readings.items():
            log(f"Sensor GPIO{pin}: {t:.1f}C, {h:.1f}%")
    else:
        log("Conditions within range; vent remains closed.")


def cleanup(sensors: list) -> None:
    """Release GPIO and sensor resources."""
    GPIO.output(SOLENOID_PIN, GPIO.LOW)
    for _, sensor in sensors:
        if sensor is not None:
            try:
                sensor.exit()
            except Exception:
                pass
    GPIO.cleanup()
    log("GPIO and sensor resources released.")


def main() -> None:
    global _sensors

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        setup_gpio()
        _sensors = init_sensors()

        last_readings = {pin: (None, None) for pin in DHT22_PINS}

        while _running:
            readings = read_sensors(_sensors)
            for pin in DHT22_PINS:
                if pin in readings:
                    last_readings[pin] = readings[pin]

            # Determine current sensor values (use last known if read failed)
            temp = None
            hum = None
            for pin in DHT22_PINS:
                t, h = last_readings[pin]
                if t is not None and (temp is None or t > temp):
                    temp = t
                if h is not None and (hum is None or h < hum):
                    hum = h

            control_vent(temp, hum, last_readings)

            # Sleep in small increments so signals are caught promptly
            slept = 0
            while _running and slept < POLL_INTERVAL:
                time.sleep(1)
                slept += 1

    except Exception as e:
        log(f"Fatal error: {e}")
    finally:
        cleanup(_sensors)


if __name__ == "__main__":
    main()

