import time
import board
import busio
import adafruit_tca9548a
import adafruit_bme280
import adafruit_tsl2591

# Constants
I2C_ADDR_TCA9548A = 0x70
I2C_ADDR_BME280 = 0x76
I2C_ADDR_TSL2591 = 0x29
READ_INTERVAL_SEC = 2


def initialize_i2c():
    """Initialize the I2C bus on board.SCL / board.SDA."""
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        # Probe the bus to confirm it is operational
        while not i2c.try_lock():
            pass
        try:
            devices = i2c.scan()
        finally:
            i2c.unlock()
        if not devices:
            print("Warning: No I2C devices detected on the bus.")
        return i2c
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None


def initialize_multiplexer(i2c_bus):
    """Initialize the TCA9548A I2C multiplexer at address 0x70."""
    try:
        mux = adafruit_tca9548a.TCA9548A(i2c_bus, address=I2C_ADDR_TCA9548A)
        # Probe each channel to confirm the multiplexer is responding
        for ch in range(8):
            try:
                _ = mux[ch].scan()
            except Exception:
                pass
        return mux
    except Exception as e:
        print(f"Error initializing TCA9548A multiplexer at 0x{I2C_ADDR_TCA9548A:02X}: {e}")
        return None


def initialize_bme280(multiplexer):
