import time
import logging
import sqlite3
import random
import math
from gpiozero import LED
from gpiozero.exc import GPIOZeroError

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

STATUS_LED_PIN = 23
DATABASE_PATH = '/tmp/wearable_health.db'
WINDOW_SIZE = 20
RUL_THRESHOLD_HOURS = 100
SAMPLE_INTERVAL_S = 0.05
ITERATIONS = 30

vibration_window = []
temperature_window = []
led = None
conn = None
running = True

def setup_gpio():
    global led
    try:
        led = LED(STATUS_LED_PIN)
        led.off()
        logging.info(f"GPIO setup complete: LED on pin {STATUS_LED_PIN}")
    except GPIOZeroError as e:
        logging.error(f"GPIO setup failed: {e}")
        raise

def setup_database():
    global conn
    try:
        conn = sqlite3.connect(DATABASE_PATH)
        conn.execute('''
            CREATE TABLE IF NOT EXISTS alerts (
                remaining_life REAL,
                ts REAL
            )
        ''')
        conn.commit()
        logging.info(f"Database setup complete: {DATABASE_PATH}")
    except sqlite3.Error as e:
        logging.error(f"Database setup failed: {e}")
        raise

def read_vibration():
    return random.uniform(0.1, 0.9)

def read_temperature():
    return random.uniform(30.0, 70.0)

def compute_degradation(vibration, temperature):
    mean_vib = sum(vibration) / len(vibration)
    mean_temp = sum(temperature) / len(temperature)
    return 0.6 * mean_vib + 0.4 * (mean_temp / 100.0)

def estimate_rul(degradation):
    return max(0.0, 500.0 * math.exp(-3.0 * degradation))

def store_alert(rul):
    try:
        conn.execute("INSERT INTO alerts (remaining_life, ts) VALUES (?, ?)", (rul, time.time()))
        conn.commit()
        logging.info(f"Alert stored: RUL={rul:.2f}h")
    except sqlite3.Error as e:
        logging.error(f"Failed to store alert: {e}")

def cleanup():
    global running
    running = False
    if led is not None:
        led.off()
        led.close()
    if conn is not None:
        conn.close()
    logging.info("Cleanup complete")

def main():
    global running
    try:
        setup_gpio()
        setup_database()
        for i in range(ITERATIONS):
            if not running:
                break
            vib = read_vibration()
            temp = read_temperature()
            vibration_window.append(vib)
            temperature_window.append(temp)
            if len(vibration_window) > WINDOW_SIZE:
                vibration_window.pop(0)
            if len(temperature_window) > WINDOW_SIZE:
                temperature_window.pop(0)
            if len(vibration_window) < WINDOW_SIZE or len(temperature_window) < WINDOW_SIZE:
                time.sleep(SAMPLE_INTERVAL_S)
                continue
            degradation = compute_degradation(vibration_window, temperature_window)
            rul = estimate_rul(degradation)
            logging.info(f"Iter {i+1}: vib={vib:.3f} temp={temp:.2f} deg={degradation:.3f} rul={rul:.2f}h")
            if rul < RUL_THRESHOLD_HOURS:
                store_alert(rul)
                led.blink(on_time=1.0, off_time=1.0, background=False)
            else:
                led.off()
            time.sleep(SAMPLE_INTERVAL_S)
    except KeyboardInterrupt:
        logging.info("Interrupted by user")
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

