#!/usr/bin/env python3
"""
Reads and displays the Raspberry Pi CPU temperature every 5 seconds.

Hardware: Raspberry Pi 4 Model B
Sensor :  On-board thermal sensor exposed via /sys/class/thermal/thermal_zone0/temp

The gpiozero.CPUTemperature class is instantiated lazily inside the read
function so that a missing sysfs file is reported as a per-read error
instead of crashing the program at startup.  All exit paths release
resources cleanly and the loop continues through transient failures.
"""

import time
import sys

from gpiozero import CPUTemperature


def read_cpu_temp() -> float:
    """
    Lazily instantiate CPUTemperature and return the CPU temperature in °C.

    Instantiation is deferred so that a missing /sys/class/thermal/thermal_zone0/temp
    file is reported as a per-read error instead of crashing the program at
    startup.  The gpiozero CPUTemperature class holds no persistent OS-level
    resources that require explicit close() calls.
    """
    try:
        cpu = CPUTemperature()
        return float(cpu.temperature)
    except FileNotFoundError as exc:
        raise RuntimeError(
            "Thermal zone sysfs file not found; is this running on a Raspberry Pi?"
        ) from exc
    except Exception as exc:
        raise RuntimeError(f"Failed to read CPU temperature: {exc}") from exc


def display_temperature(temperature: float) -> None:
    """Print the CPU temperature formatted to two decimal places."""
    print(f"CPU Temperature: {temperature:.2f} °C")


def main() -> None:
    """Continuously read and display the CPU temperature every 5 seconds."""
    try:
        while True:
            try:
                temperature = read_cpu_temp()
                display_temperature(temperature)
            except Exception as exc:
                # Transient failure: log and keep the loop alive.
                print(f"Error reading temperature: {exc}", file=sys.stderr)
            time.sleep(5)
    except KeyboardInterrupt:
        print("Program terminated")
        sys.exit(0)


if __name__ == "__main__":
    main()

