import serial
import serial.tools.list_ports
import numpy as np
import matplotlib.pyplot as plt
import matplotlib.animation as animation
import threading
import queue
import time
import sys
import signal

SERIAL_PORT = '/dev/ttyS0'
BAUD_RATE = 9600
TIMEOUT = 1
EXPECTED_VALUES = 768
ROWS = 24
COLS = 32
UPDATE_INTERVAL_MS = 100


class ThermalCamera:
    def __init__(self, serial_port, baud_rate, timeout):
        self.serial_port = serial_port
        self.baud_rate = baud_rate
        self.timeout = timeout
        self.serial_connection = None
        self.data_queue = queue.Queue()
        self.stop_event = threading.Event()
        self.heatmap_image = None
        self.fig = None
        self.ax = None
        self.im = None

    def connect_serial(self):
        try:
            self.serial_connection = serial.Serial(
                self.serial_port, self.baud_rate, timeout=self.timeout
            )
            print(f"Connected to serial port: {self.serial_port}")
        except serial.SerialException as e:
            print(f"Error connecting to serial port: {e}")
            self.serial_connection = None

    def read_serial_data(self):
        while not self.stop_event.is_set():
            if self.serial_connection and self.serial_connection.is_open:
                try:
                    raw = self.serial_connection.readline()
                    if not raw:
                        continue
                    line = raw.decode('ascii', errors='replace').strip()
                    if not line:
                        continue
                    data = [int(x) for x in line.split(',')]
                    if len(data) != EXPECTED_VALUES:
                        print(f"Warning: expected {EXPECTED_VALUES} values, got {len(data)}; skipping.")
                        continue
                    self.data_queue.put(np.array(data).reshape((ROWS, COLS)))
                except ValueError:
                    print(f"Error parsing data (malformed line): {line!r}")
                except serial.SerialException as e:
                    print(f"Serial read error: {e}")
                    break
                except Exception as e:
                    print(f"Unexpected error reading serial data: {e}")
                    break
            else:
                time.sleep(0.1)
        print("Serial data reading thread stopped.")

    def update_heatmap(self, frame_num):
        try:
            if not self.data_queue.empty():
                new_data = self.data_queue.get_nowait()
                if self.heatmap_image is not None:
                    self.heatmap_image.set_array(new_data)
                else:
                    self.heatmap_image = self.ax.imshow(
                        new_data, cmap='inferno', interpolation='nearest'
                    )
                    self.fig.colorbar(self.heatmap_image, ax=self.ax)
            return self.heatmap_image,
        except queue.Empty:
            return self.heatmap_image,

    def start(self):
        self.connect_serial()
        if not self.serial_connection:
            print("Failed to start thermal camera. Check serial connection.")
            return

        try:
            self.fig, self.ax = plt.subplots()
            self.ax.set_title('Thermal Camera Heatmap')
            self.ax.set_xlabel('X')
            self.ax.set_ylabel('Y')

            serial_thread = threading.Thread(target=self.read_serial_data, daemon=True)
            serial_thread.start()

            ani = animation.FuncAnimation(
                self.fig, self.update_heatmap, interval=UPDATE_INTERVAL_MS, blit=False
            )
            plt.show()

        except KeyboardInterrupt:
            print("Program interrupted by user.")
        except Exception as e:
            print(f"An error occurred: {e}")
        finally:
            self.stop_event.set()
            if self.serial_connection and self.serial_connection.is_open:
                self.serial_connection.close()
                print("Serial port closed.")
            plt.close('all')
            print("Thermal camera stopped.")


def main():
    thermal_camera = ThermalCamera(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    thermal_camera.start()


if __name__ == "__main__":
    main()

