import time
import signal
import sys
import logging
from datetime import datetime

try:
    import board
    import adafruit_dht
except Exception:
    board = None
    adafruit_dht = None

try:
    from gpiozero import OutputDevice
except Exception:
    OutputDevice = None

# Configuration
DHT_PIN = 17
FAN_PIN = 18
TEMP_THRESHOLD = 30.0
HUMIDITY_THRESHOLD = 70.0
LOG_FILE = 'urban_data_log.txt'
READING_INTERVAL = 2
NUM_READINGS = 5

# Logging setup
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Global resources for cleanup
dht_device = None
fan = None
running = True


def signal_handler(signum, frame):
    global running
    logging.info(f"Signal {signum} received, shutting down...")
    running = False


def initialize_dht():
    if board is None or adafruit_dht is None:
        logging.warning("DHT library not available; running in degraded mode.")
        return None
    try:
        return adafruit_dht.DHT11(board.D17, use_pulseio=False)
    except Exception as e:
        logging.warning(f"DHT11 init failed (non-hardware env?): {e}")
        return None


def initialize_fan():
    if OutputDevice is None:
        logging.warning("gpiozero not available; running in degraded mode.")
        return None
    try:
        return OutputDevice(FAN_PIN)
    except Exception as e:
        logging.warning(f"Fan init failed (non-hardware env?): {e}")
        return None


def read_sensor_data():
    if dht_device is None:
        return None, None
    try:
        temperature = dht_device.temperature
        humidity = dht_device.humidity
        if temperature is None or humidity is None:
            logging.warning("DHT11 returned None values.")
            return None, None
        return temperature, humidity
    except RuntimeError as e:
        logging.error(f"DHT11 read error: {e}")
        return None, None
    except Exception as e:
        logging.error(f"Unexpected DHT11 error: {e}")
        return None, None


def control_fan(temperature, humidity):
    if fan is None:
        return
    try:
        if temperature is not None and humidity is not None:
            if temperature > TEMP_THRESHOLD or humidity > HUMIDITY_THRESHOLD:
                if not fan.is_active:
                    fan.on()
                    logging.info("Fan ON: Temp/Humidity too high.")
            else:
                if fan.is_active:
                    fan.off()
                    logging.info("Fan OFF: Temp/Humidity normal.")
    except Exception as e:
        logging.error(f"Fan control error: {e}")


def log_data(temperature, humidity):
    timestamp = datetime.now().isoformat()
    log_entry = f"{timestamp} - Temperature: {temperature}°C, Humidity: {humidity}%\n"
    try:
        with open(LOG_FILE, 'a') as f:
            f.write(log_entry)
    except Exception as e:
        logging.error(f"Log write error: {e}")


def cleanup():
    global dht_device, fan
    logging.info("Cleaning up resources...")
    if fan is not None:
        try:
            fan.off()
            fan.close()
        except Exception:
            pass
        fan = None
    if dht_device is not None:
        try:
            dht_device.exit()
        except Exception:
            pass
        dht_device = None
    logging.info("Cleanup complete.")


def main():
    global dht_device, fan
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    dht_device = initialize_dht()
    fan = initialize_fan()

    readings_done = 0
    try:
        while running and readings_done < NUM_READINGS:
            temperature, humidity = read_sensor_data()
            if temperature is not None and humidity is not None:
                logging.info(f"Temp: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
                log_data(temperature, humidity)
                control_fan(temperature, humidity)
            else:
                logging.warning("Skipping fan control due to sensor read failure.")
            readings_done += 1
            if readings_done < NUM_READINGS and running:
                time.sleep(READING_INTERVAL)
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

