                logger.warning(f"Measurement timed out (attempt {attempt + 1}).")
                time.sleep(self.RETRY_DELAY)
                continue

            raw_data = self._read_raw_data()
            if raw_data is None:
                logger.warning(f"Data read or CRC error (attempt {attempt + 1}).")
                time.sleep(self.RETRY_DELAY)
                continue

            temperature, humidity = self._convert_data(raw_data)
            self._last_temperature = temperature
            self._last_humidity = humidity
            self._last_measurement_time = time.monotonic()
            return temperature, humidity, False

        logger.error("Failed to obtain valid measurement after multiple attempts.")
        return self._last_temperature, self._last_humidity, True

    def stop(self):
        self._running = False


def _signal_handler(signum, frame):
    logger.info(f"Signal {signum} received, shutting down.")
    raise SystemExit(0)


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        with DHT20() as sensor:
            if not sensor.begin():
                print("DHT20 initialization failed. Check wiring and I2C address.")
                sys.exit(0)

            while sensor._running:
                temp, hum, err = sensor.get_temperature_and_humidity()
                if err:
                    logger.error("Measurement error occurred.")
                if temp is not None and hum is not None:
                    print(f"Temperature: {temp:.2f} C, Humidity: {hum:.2f} %")
                time.sleep(1)
    except SystemExit:
        pass
    except Exception as e:
        logger.exception(f"Unexpected error: {e}")
        sys.exit(1)


if __name__ == "__main__":
    main()

