import subprocess
import time
import signal
import sys
from gpiozero import PWMOutputDevice

PWM_PIN = 14
FREQ_HZ = 100
INTERVAL_S = 5

running = True
fan = None


def handle_signal(signum, frame):
    global running
    running = False


def get_cpu_temp():
    """Return CPU temperature in °C, or None on error."""
    try:
        out = subprocess.check_output(
            ["vcgencmd", "measure_temp"],
            stderr=subprocess.STDOUT,
            timeout=5,
        ).decode("utf-8").strip()
        # Expected format: temp=42.8'C
        if "=" not in out or "'" not in out:
            print(f"Unexpected vcgencmd output: {out!r}", file=sys.stderr)
            return None
        temp_str = out.split("=")[1].split("'")[0]
        return float(temp_str)
    except subprocess.CalledProcessError as e:
        print(f"vcgencmd failed (rc={e.returncode}): {e.output}", file=sys.stderr)
        return None
    except subprocess.TimeoutExpired:
        print("vcgencmd timed out", file=sys.stderr)
        return None
    except (ValueError, IndexError) as e:
        print(f"Failed to parse temperature: {e}", file=sys.stderr)
        return None
    except FileNotFoundError:
        print("vcgencmd not found", file=sys.stderr)
        return None


def duty_for_temp(temp):
    if temp > 70:
        return 100
    if temp > 60:
        return 85
    if temp > 50:
        return 70
    if temp > 40:
        return 50
    if temp > 32:
        return 25
    if temp > 25:
        return 15
    return 0


def main():
    global fan
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        fan = PWMOutputDevice(PWM_PIN, frequency=FREQ_HZ, initial_value=0)
    except Exception as e:
        print(f"Failed to initialize PWM on GPIO{PWM_PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    last_duty = 100
    print(f"PWM fan control started on GPIO{PWM_PIN} @ {FREQ_HZ} Hz")

    try:
        while running:
            temp = get_cpu_temp()
            if temp is not None:
                last_duty = duty_for_temp(temp)
                print(f"CPU temp {temp:.1f}°C -> duty {last_duty}%")
            else:
                print(f"Keeping last duty {last_duty}% (no valid temp)", file=sys.stderr)
            fan.value = last_duty / 100.0
            time.sleep(INTERVAL_S)
    finally:
        if fan is not None:
            fan.value = 0
            fan.close()
        print("Fan stopped and GPIO released")


if __name__ == "__main__":
    main()

