import signal
import sys
import time
import logging

import smbus2
from ina219 import INA219, DeviceRangeError

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("ups_monitor")

I2C_BUS = 1
SUPPLY_INA_ADDR = 0x40
BATT_INA_ADDR = 0x45
UPS_ADDR = 0x17
SHUNT_SUPPLY = 0.00725
SHUNT_BATT = 0.005
SAMPLE_INTERVAL = 2.0

_running = True
_bus = None


def _handle_signal(signum, frame):
    global _running
    log.info("Received signal %s, shutting down...", signum)
    _running = False


def _read_supply(ina):
    try:
        voltage = ina.voltage()
        current = ina.current()
        print(f"Supply: {voltage:.3f} V, {current:.3f} mA")
    except DeviceRangeError:
        log.error("Supply INA219 current out of range")
    except OSError as e:
        log.error("Supply INA219 I2C error: %s", e)
    except Exception as e:
        log.error("Unexpected supply read error: %s", e)


def _read_battery(ina):
    try:
        voltage = ina.voltage()
        current = ina.current()
        print(f"Battery: {voltage:.3f} V, {current:.3f} mA")
    except DeviceRangeError:
        log.error("Battery INA219 current out of range")
    except OSError as e:
        log.error("Battery INA219 I2C error: %s", e)
    except Exception as e:
        log.error("Unexpected battery read error: %s", e)


def _read_ups(bus):
    try:
        data = bus.read_i2c_block_data(UPS_ADDR, 0x00, 42)
        proc_v = (data[1] << 8) | data[2]
        batt_v = (data[5] << 8) | data[6]
        temp_c = (data[11] << 8) | data[12]
        capacity = (data[19] << 8) | data[20]
        print(f"UPS: Proc {proc_v}mV, Battery Port {batt_v}mV, Temp {temp_c}C, Capacity {capacity}%")
    except OSError as e:
        log.error("UPS I2C read error at 0x%02X: %s", UPS_ADDR, e)
    except Exception as e:
        log.error("Unexpected UPS read error: %s", e)


def main():
    global _bus
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        _bus = smbus2.SMBus(I2C_BUS)
    except OSError as e:
        log.error("Cannot open I2C bus %d: %s", I2C_BUS, e)
        sys.exit(1)

    try:
        ina_supply = INA219(SHUNT_SUPPLY, busnum=I2C_BUS, address=SUPPLY_INA_ADDR)
        ina_supply.configure()
    except Exception as e:
        log.error("Failed to init supply INA219 at 0x%02X: %s", SUPPLY_INA_ADDR, e)
        ina_supply = None

    try:
        ina_batt = INA219(SHUNT_BATT, busnum=I2C_BUS, address=BATT_INA_ADDR)
        ina_batt.configure()
    except Exception as e:
        log.error("Failed to init battery INA219 at 0x%02X: %s", BATT_INA_ADDR, e)
        ina_batt = None

    try:
        while _running:
            if ina_supply:
                _read_supply(ina_supply)
            if ina_batt:
                _read_battery(ina_batt)
            _read_ups(_bus)
            time.sleep(SAMPLE_INTERVAL)
    finally:
        if _bus is not None:
            try:
                _bus.close()
            except Exception:
                pass
        log.info("Exited cleanly.")


if __name__ == "__main__":
    main()

