import time
import signal
import sys
import logging
import urllib.request
import urllib.error
from datetime import datetime

import adafruit_dht
import board

# --- Configuration ---
DHT_PIN = board.D4          # BCM GPIO4 (physical pin 7)
THINGSPEAK_CHANNEL_ID = '1234567'
THINGSPEAK_API_KEY = 'YOUR_API_KEY'
READ_INTERVAL_SECONDS = 60
DHT_TIMEOUT_SECONDS = 2
TEMPERATURE_FILE = 'temperature.txt'
ERROR_LOG_FILE = 'error.log'

# --- Logging setup ---
logging.basicConfig(
    filename=ERROR_LOG_FILE,
    level=logging.ERROR,
    format='%(asctime)s - %(levelname)s - %(message)s',
    datefmt='%Y-%m-%d %H:%M:%S'
)

# --- Globals for cleanup ---
_running = True
_sensor = None


def _signal_handler(signum, frame):
    global _running
    _running = False


def _cleanup():
    global _sensor
    if _sensor is not None:
        try:
            _sensor.exit()
        except Exception:
            pass
        _sensor = None


def _log_error(message):
    logging.error(message)
    print(f"Error: {message}", file=sys.stderr)


def _read_temperature(sensor):
    """Return (temperature_c, error_message) with a 2-second timeout."""
    deadline = time.monotonic() + DHT_TIMEOUT_SECONDS
    while time.monotonic() < deadline:
        try:
            temperature = sensor.temperature
            if temperature is not None:
                return round(temperature, 2), None
        except RuntimeError as e:
            # DHT22 checksum / timing errors are common; retry until timeout
            time.sleep(0.5)
            continue
        except Exception as e:
            return None, str(e)
    return None, "DHT22 read timed out"


def _write_temperature(temperature):
    try:
        with open(TEMPERATURE_FILE, 'a') as f:
            f.write(f"{datetime.now().strftime('%Y-%m-%d %H:%M:%S')}, Temperature: {temperature} C\n")
            f.flush()
    except OSError as e:
        _log_error(f"Failed to write to {TEMPERATURE_FILE}: {e}")


def _send_to_thingspeak(temperature):
    url = f'https://api.thingspeak.com/update?api_key={THINGSPEAK_API_KEY}&field1={temperature}'
    try:
        with urllib.request.urlopen(url, timeout=10) as response:
            if response.status != 200:
                _log_error(f"Thingspeak returned HTTP {response.status}")
    except urllib.error.URLError as e:
        _log_error(f"Failed to send to Thingspeak: {e}")
    except Exception as e:
        _log_error(f"Unexpected error sending to Thingspeak: {e}")


def main():
    global _sensor

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        _sensor = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
    except Exception as e:
        _log_error(f"Failed to initialize DHT22 on GPIO4: {e}")
        sys.exit(1)

    print("Starting DHT22 temperature logger. Press Ctrl+C to stop.")

    while _running:
        temperature, error = _read_temperature(_sensor)

        if error is not None:
            _log_error(f"Sensor read failed: {error}")
        else:
            _write_temperature(temperature)
            _send_to_thingspeak(temperature)

        # Sleep in small increments so signals are caught promptly
        slept = 0
        while _running and slept < READ_INTERVAL_SECONDS:
            time.sleep(1)
            slept += 1

    _cleanup()
    print("Shutdown complete.")


if __name__ == '__main__':
    main()

