import serial
import serial.tools.list_ports
import sys
import time
import signal
import numpy as np
import matplotlib.pyplot as plt

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1.0
EXPECTED_VALUES = 24 * 32
REFRESH_INTERVAL = 0.1
EXPECTED_TOKENS = 768

running = True
serial_connection = None
figure = None


def signal_handler(signum, frame):
    global running
    running = False


def cleanup():
    global serial_connection, figure
    if serial_connection is not None:
        try:
            if serial_connection.is_open:
                serial_connection.close()
                print('Serial port closed.')
        except Exception as e:
            print(f'Error closing serial port: {e}', file=sys.stderr)
        serial_connection = None
    if figure is not None:
        try:
            plt.close(figure)
        except Exception:
            pass
        figure = None


def parse_frame(line):
    if not line:
        return None
    tokens = line.split(',')
    if len(tokens) != EXPECTED_TOKENS:
        return None
    values = []
    for token in tokens:
        token = token.strip()
        if not token:
            continue
        try:
            values.append(int(token))
        except ValueError:
            return None
    if len(values) != EXPECTED_VALUES:
        return None
    return np.array(values, dtype=np.float64).reshape((24, 32))


def main():
    global serial_connection, figure, running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        serial_connection = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=TIMEOUT,
        )
        print(f'Opened {SERIAL_PORT} @ {BAUD_RATE} baud.')
    except serial.SerialException as e:
        print(f'Error opening serial port: {e}', file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f'Unexpected error opening serial port: {e}', file=sys.stderr)
        sys.exit(1)

    try:
        figure, ax = plt.subplots()
        figure.canvas.manager.set_window_title('Thermal Camera Heat Map')
        image = ax.imshow(
            np.zeros((24, 32), dtype=np.float64),
            cmap='inferno',
            interpolation='nearest',
            vmin=0,
            vmax=100,
        )
        ax.set_title('Thermal Camera Heat Map')
        plt.colorbar(image, ax=ax, label='Temperature (°C)')
        plt.show(block=False)
        plt.pause(0.1)
    except Exception as e:
        print(f'Error initializing matplotlib: {e}', file=sys.stderr)
        cleanup()
        sys.exit(1)

    last_frame = None

    try:
        while running:
            try:
                raw = serial_connection.readline()
            except serial.SerialException as e:
                print(f'Serial I/O error: {e}', file=sys.stderr)
                break

            if not raw:
                continue

            try:
                line = raw.decode('ascii', errors='replace').strip()
            except Exception as e:
                print(f'Decode error: {e}', file=sys.stderr)
                continue

            if not line:
                continue

            frame = parse_frame(line)
            if frame is None:
                continue

            last_frame = frame

            try:
                image.set_data(frame)
                image.autoscale()
                plt.draw()
                plt.pause(REFRESH_INTERVAL)
            except Exception as e:
                print(f'Display update error: {e}', file=sys.stderr)
                break
    finally:
