REFRESH_INTERVAL = 0.1
EXPECTED_TOKENS = 768

running = True
serial_connection = None
figure = None


def signal_handler(signum, frame):
    global running
    running = False


def cleanup():
    global serial_connection, figure
    if serial_connection is not None:
