        return None
    values = []
    for token in tokens:
        token = token.strip()
        if not token:
            continue
        try:
            values.append(int(token))
        except ValueError:
            return None
    if len(values) != EXPECTED_VALUES:
        return None
    return np.array(values, dtype=np.float64).reshape((24, 32))


