import time
import sys

LED_PIN = 17
led_state = False

def cleanup_gpio():
    """Drive the LED low and release the GPIO pin."""
    try:
        GPIO.output(LED_PIN, GPIO.LOW)
    except Exception:
        pass
    GPIO.cleanup()

def main():
    global led_state
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"GPIO setup failed: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while True:
            try:
                user_input = input("Enter 'on' or 'off': ")
            except EOFError:
                break

            if user_input == "on":
                led_state = True
                GPIO.output(LED_PIN, GPIO.HIGH)
            elif user_input == "off":
                led_state = False
                GPIO.output(LED_PIN, GPIO.LOW)
            else:
                print("Invalid input")

            print(led_state)
            time.sleep(0.1)
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

