import signal
import sys
import time

from gpiozero import DigitalInputDevice
from gpiozero.exc import GPIOZeroError, GPIODeviceError

# BCM pin numbers for the three sensors
SENSOR_PINS = [17, 27, 22]
POLL_INTERVAL_S = 1.0

# Global list so the signal handler can close devices cleanly
_devices = []
_running = True


def _cleanup():
    """Close every DigitalInputDevice we opened."""
    for dev in _devices:
        try:
            dev.close()
        except Exception:
            pass
    _devices.clear()


def _handle_signal(signum, frame):
    """Set the running flag to False on SIGINT / SIGTERM."""
    global _running
    _running = False


def main():
    global _devices

    # Install signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # Initialize each sensor pin as a digital input with an active-high pull-up
    for pin in SENSOR_PINS:
        try:
            dev = DigitalInputDevice(pin, pull_up=True, bounce_time=None)
            _devices.append(dev)
        except (GPIOZeroError, GPIODeviceError) as exc:
            print(f"Error: failed to initialize GPIO{pin}: {exc}", file=sys.stderr)
            _cleanup()
            sys.exit(1)
        except Exception as exc:
            print(f"Unexpected error initializing GPIO{pin}: {exc}", file=sys.stderr)
            _cleanup()
            sys.exit(1)

    print(f"Monitoring pins {SENSOR_PINS} (active-high, pull-up) every {POLL_INTERVAL_S:.1f}s. Press Ctrl+C to exit.")

    try:
        while _running:
            for idx, dev in enumerate(_devices):
                try:
                    if dev.is_active:
                        print(f"Response for sensor {idx + 1}")
                except (GPIOZeroError, GPIODeviceError) as exc:
                    print(f"Error reading GPIO{dev.pin.number}: {exc}", file=sys.stderr)
                except Exception as exc:
                    print(f"Unexpected error reading GPIO{dev.pin.number}: {exc}", file=sys.stderr)

            # Sleep in small increments so signals are caught promptly
            slept = 0.0
            while _running and slept < POLL_INTERVAL_S:
                time.sleep(0.1)
                slept += 0.1

    except Exception as exc:
        print(f"Fatal error in main loop: {exc}", file=sys.stderr)
    finally:
        _cleanup()
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

