SERVER_STATE = {"is_running": False, "log_file": DEFAULT_LOG_FILE, "receive_thread": None}
HELP_MESSAGES = {
    "help": "Call 'help <command>' for details.\nCommands: display, help, send, start, stop, write, exit",
    "start": "Starts the server.\nUsage: start <filename>",
    "stop": "Stops the server.\nUsage: stop",
    "display": "Displays log file contents.\nUsage: display",
    "send": "Sends data via DOG.send().\nUsage: send <data>",
    "write": "Writes data directly to the log file.\nUsage: write <data>",
    "exit": "Stops the server and exits.",
}

# Simulated DOG module (replace with actual implementation)
class DOG:
    @staticmethod
    def send(data):
        """Sends data using DOG.send()."""
        print(f"Sending: {data}")

    @staticmethod
    def receive():
        """Receives data using DOG.receive()."""
        return None

# --- Signal Handler ---
def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM for clean shutdown."""
    print("\nSignal received, stopping server...")
    stop_server()
    GPIO.cleanup()
    sys.exit(0)

# --- Help Command ---
def help_command(args):
    """Displays help messages."""
    if not args or args[0] == "help":
        print(HELP_MESSAGES.get("help", "No help found."))
    else:
        print(HELP_MESSAGES.get(args[0], "No help found."))

# --- Start Command ---
def start_server(args):
    """Starts the server and the receive thread."""
    global SERVER_STATE
    if SERVER_STATE["is_running"]:
        print("Server is already running.")
        return

    if not args or args[0] == "start":
        print("Error: No filename provided. Usage: start <filename>")
        return

    log_filename = args[0]
    try:
        with open(log_filename, "a"):
            pass  # Create file if it doesn't exist
    except IOError as e:
        print(f"Error creating log file: {e}")
        return

    SERVER_STATE["is_running"] = True
    SERVER_STATE["log_file"] = log_filename
    SERVER_STATE["receive_thread"] = threading.Thread(target=receive_loop, daemon=True)
    SERVER_STATE["receive_thread"].start()
    print(f"Server started. Logging to: {log_filename}")

# --- Stop Command ---
def stop_server():
    """Stops the server and the receive thread."""
    global SERVER_STATE
    if SERVER_STATE["is_running"]:
        SERVER_STATE["is_running"] = False
        if SERVER_STATE["receive_thread"] and SERVER_STATE["receive_thread"].is_alive():
            SERVER_STATE["receive_thread"].join(timeout=1.0)
        print("Server stopped.")
    else:
        print("Server is not running.")

# --- Display Command ---
def display_log(args):
    """Displays the contents of the log file."""
    global SERVER_STATE
    if not SERVER_STATE["is_running"]:
        print("Error: Server must be started first. Use the 'start' command.")
        return

    try:
        with open(SERVER_STATE["log_file"], "r") as f:
            print(f.read())
    except FileNotFoundError:
        print(f"Log file not found: {SERVER_STATE['log_file']}")
    except IOError as e:
        print(f"Error reading log file: {e}")

# --- Send Command ---
def send_data(args):
    """Sends data using DOG.send()."""
    if not SERVER_STATE["is_running"]:
        print("Error: Server must be started first. Use the 'start' command.")
        return

    if not args or args[0] == "send":
        print("Error: No data provided. Usage: send <data>")
        return

    data = " ".join(args[1:])
    try:
        DOG.send(data)
    except Exception as e:
        print(f"Error sending data: {e}")

# --- Write Command ---
def write_to_log(args):
    """Writes data directly to the log file."""
    global SERVER_STATE
    if not SERVER_STATE["is_running"]:
        print("Error: Server must be started first. Use the 'start' command.")
        return

    if not args or args[0] == "write":
        print("Error: No data provided. Usage: write <data>")
        return

    data = " ".join(args[1:])
    try:
        with open(SERVER_STATE["log_file"], "a") as f:
            f.write(data + "\n")
    except IOError as e:
        print(f"Error writing to log file: {e}")

# --- Exit Command ---
def exit_server(args):
    """Stops the server and exits the program."""
    stop_server()
    GPIO.cleanup()
    sys.exit(0)

# --- Receive Loop ---
def receive_loop():
    """Continuously receives data and logs it to the file."""
    global SERVER_STATE
    while SERVER_STATE["is_running"]:
        try:
            data = DOG.receive()
            if data:
                with open(SERVER_STATE["log_file"], "a") as f:
                    f.write(data + "\n")
        except Exception as e:
            print(f"Error in receive loop: {e}")
        time.sleep(POLL_INTERVAL)

# --- Command Parser ---
def parse_command(command):
    """Parses and executes the given command."""
    parts = command.split()
    if not parts:
        return

    command_name = parts[0].lower()
    args = parts[1:]

    command_map = {
        "help": help_command,
        "start": start_server,
        "stop": stop_server,
        "display": display_log,
        "send": send_data,
        "write": write_to_log,
        "exit": exit_server,
    }

    if command_name in command_map:
        command_map[command_name](args)
    else:
        print("Unknown command. Try 'help'")

# --- Main Loop ---
def main():
    """Main function to run the server."""
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        GPIO.setmode(GPIO.BCM)
        print("GPIO initialized successfully.")
    except Exception as e:
        print(f"Failed to initialize GPIO: {e}")
        sys.exit(1)

    print("Starting DOG server...")
    print("Enter 'help' for available commands.")

    try:
        while True:
            try:
                command = input("JAYES@ROVER53:\t")
            except EOFError:
                print("\nEOF received, exiting.")
                break
            parse_command(command)
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        stop_server()
        GPIO.cleanup()
        print("GPIO cleaned up. Exiting.")

if __name__ == "__main__":
    main()

