import time
import sys

try:
    import RPi.GPIO as GPIO
    _GPIO_AVAILABLE = True
except ImportError:
    _GPIO_AVAILABLE = False

# Hardcoded sentiment lexicon (VADER-style scores)
vader_lexicon = {
    "love": 0.8, "hate": -0.8, "good": 0.6, "bad": -0.6,
    "great": 0.7, "terrible": -0.7, "excellent": 0.9, "awful": -0.9,
    "wonderful": 0.85, "horrible": -0.85, "fantastic": 0.95, "terrible": -0.95,
    "amazing": 0.9, "awful": -0.9, "beautiful": 0.8, "ugly": -0.8,
    "happy": 0.5, "sad": -0.5, "fun": 0.4, "boring": -0.4,
}

# GPIO pin definitions
GREEN_LED_PIN = 17
RED_LED_PIN = 18

# Initialize GPIO if available
_gpio_initialized = False
if _GPIO_AVAILABLE:
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(GREEN_LED_PIN, GPIO.OUT, initial=GPIO.LOW)
        GPIO.setup(RED_LED_PIN, GPIO.OUT, initial=GPIO.LOW)
        _gpio_initialized = True
    except Exception as e:
        print(f"Warning: GPIO initialization failed: {e}", file=sys.stderr)
        _gpio_initialized = False


def analyze_sentiment(text):
    """Return average sentiment score for a given text."""
    words = text.lower().split()
    total = 0.0
    count = 0
    for word in words:
        total += vader_lexicon.get(word, 0.0)
        count += 1
    return total / count if count > 0 else 0.0


def classify_sentiment(score):
    """Classify sentiment based on average score."""
    if score > 0.2:
        return "Positive"
    elif score < -0.2:
        return "Negative"
    else:
        return "Neutral"


def control_leds(sentiment):
    """Control LEDs based on sentiment classification."""
    if not _gpio_initialized:
        return
    try:
        GPIO.output(GREEN_LED_PIN, GPIO.LOW)
        GPIO.output(RED_LED_PIN, GPIO.LOW)
        if sentiment == "Positive":
            GPIO.output(GREEN_LED_PIN, GPIO.HIGH)
        elif sentiment == "Negative":
            GPIO.output(RED_LED_PIN, GPIO.HIGH)
        time.sleep(2)
        GPIO.output(GREEN_LED_PIN, GPIO.LOW)
        GPIO.output(RED_LED_PIN, GPIO.LOW)
    except Exception as e:
        print(f"Warning: GPIO control failed: {e}", file=sys.stderr)


def main():
    try:
        user_input = input("Enter a sentence: ")
        sentiment_score = analyze_sentiment(user_input)
        sentiment = classify_sentiment(sentiment_score)
        print(f"Sentiment: {sentiment} (score: {sentiment_score:.2f})")
        control_leds(sentiment)
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    finally:
        if _gpio_initialized:
            try:
                GPIO.cleanup()
            except Exception:
                pass


if __name__ == "__main__":
    main()

