import RPi.GPIO as GPIO
import time
import sys

# IR sensor pins (BCM numbering)
LEFT_SENSOR_PIN = 5
RIGHT_SENSOR_PIN = 6

# Timing constants
SAMPLE_INTERVAL = 0.5  # seconds between samples
NUM_SAMPLES = 10

def setup_sensors():
    """Configure GPIO pins for IR sensors with error handling."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LEFT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        GPIO.setup(RIGHT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    except Exception as e:
        print(f"Error setting up GPIO: {e}")
        sys.exit(1)

def read_sensor(pin):
    """Read an IR sensor pin. Returns 0 (black) or 1 (white)."""
    try:
        return GPIO.input(pin)
    except Exception as e:
        print(f"Error reading sensor on pin {pin}: {e}")
        return None

def decide_direction(left_state, right_state):
    """Determine steering action based on sensor states.
    Black line = 0, white surface = 1.
    """
    if left_state is None or right_state is None:
        return "error"
    if left_state == 0 and right_state == 0:
        return "forward"
    if left_state == 1 and right_state == 0:
        return "turn-left"
    if left_state == 0 and right_state == 1:
        return "turn-right"
    return "search"

def main():
    setup_sensors()
    try:
        for sample in range(NUM_SAMPLES):
            left = read_sensor(LEFT_SENSOR_PIN)
            right = read_sensor(RIGHT_SENSOR_PIN)
            action = decide_direction(left, right)
            print(f"Sample {sample+1}: left={left} right={right} -> {action}")
            time.sleep(SAMPLE_INTERVAL)
    except KeyboardInterrupt:
        print("\nLine following stopped by user.")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        GPIO.cleanup()
        print("GPIO cleaned up.")

if __name__ == "__main__":
    main()

