import signal
import sys
from flask import Flask, render_template_string

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError
except ImportError:
    print("Error: gpiozero is not installed. Install with: pip install gpiozero", file=sys.stderr)
    sys.exit(1)

app = Flask(__name__)

LED_PIN = 17
led = None

INDEX_HTML = """
<!DOCTYPE html>
<html>
<head><title>LED Control</title></head>
<body>
  <h1>LED Control</h1>
  <p>Current state: {{ state }}</p>
  <a href="/light_on">Turn ON</a> | <a href="/light_off">Turn OFF</a>
</body>
</html>
"""

STATUS_HTML = """
<!DOCTYPE html>
<html>
<head><title>LED Status</title></head>
<body>
  <h1>{{ message }}</h1>
  <a href="/">Back</a>
</body>
</html>
"""

def cleanup(signum=None, frame=None):
    global led
    if led is not None:
        try:
            led.close()
        except Exception:
            pass
        led = None
    if signum is not None:
        sys.exit(0)

def init_led():
    global led
    try:
        led = LED(LED_PIN)
    except GPIOZeroError as e:
        print(f"GPIO initialization error: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error initializing GPIO: {e}", file=sys.stderr)
        sys.exit(1)

@app.route('/')
def index():
    state = "ON" if led is not None and led.is_lit else "OFF"
    return render_template_string(INDEX_HTML, state=state)

@app.route('/light_on')
def light_on():
    if led is None:
        return render_template_string(STATUS_HTML, message="LED not initialized"), 500
    try:
        led.on()
        return render_template_string(STATUS_HTML, message="LED is ON")
    except Exception as e:
        return render_template_string(STATUS_HTML, message=f"Error turning LED on: {e}"), 500

@app.route('/light_off')
def light_off():
    if led is None:
        return render_template_string(STATUS_HTML, message="LED not initialized"), 500
    try:
        led.off()
        return render_template_string(STATUS_HTML, message="LED is OFF")
    except Exception as e:
        return render_template_string(STATUS_HTML, message=f"Error turning LED off: {e}"), 500

if __name__ == '__main__':
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)
    init_led()
    try:
        app.run(host='0.0.0.0', port=8080, debug=False)
    finally:
        cleanup()

