import zmq
import time
import logging
import signal
from typing import Optional, Callable, Dict, Any, List
from gpiozero import PWMOutputDevice, OutputDevice, Device
from gpiozero.pins.native import NativeFactory

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class PIDHandler:
    """
    Manages PID controllers and error output signals on a Raspberry Pi.

    Uses gpiozero for all GPIO/PWM operations (physical pin numbering).
    PWM output: physical pin 12 (BCM GPIO 18) at 1000 Hz.
    Digital output: physical pin 10 (BCM GPIO 15).
    """

    def __init__(self, config: Dict[str, Any], logger: logging.Logger):
        self.config = config
        self.logger = logger
        self.sub_list: Dict[str, List[Dict[str, Any]]] = {}
        self.last_msg: float = time.time()
        self.global_err_state: bool = False
        self.pids: Dict[str, Any] = {}
        self.error_output: Optional[OutputDevice] = None
        self.pwm_output: Optional[PWMOutputDevice] = None
        self.pwm_enabled: bool = False
        self._running: bool = True

        # Use the native pin factory to avoid RPi.GPIO dependency issues
        try:
            Device.pin_factory = NativeFactory()
        except Exception as e:
            self.logger.error(f"Failed to initialize native pin factory: {e}")
            raise

        self._setup_gpio()
        self._register_signal_handlers()

    def _setup_gpio(self) -> None:
        """Initialize GPIO devices based on configuration."""
        try:
            if self.config.get('pwm', False):
                # Physical pin 12 = BCM GPIO 18
                self.pwm_output = PWMOutputDevice(pin=18, frequency=1000, initial_value=0.0)
                self.pwm_enabled = True
                self.logger.info("PWM output initialized on physical pin 12 (BCM GPIO 18) at 1000 Hz.")
            else:
                # Physical pin 10 = BCM GPIO 15
                self.error_output = OutputDevice(pin=15, initial_value=False)
                self.logger.info("Digital error output initialized on physical pin 10 (BCM GPIO 15).")
        except Exception as e:
            self.logger.error(f"Failed to initialize GPIO devices: {e}")
            raise

    def _register_signal_handlers(self) -> None:
        """Register signal handlers for clean shutdown."""
        for sig in (signal.SIGINT, signal.SIGTERM):
            signal.signal(sig, self._signal_handler)

