import time
import board
import busio
import adafruit_fingerprint

# Initialize I2C communication on Raspberry Pi 5
i2c_bus = None
sensor = None

try:
    i2c_bus = busio.I2C(board.SCL, board.SDA)
    # Instantiate the fingerprint sensor (default I2C address 0x26)
    sensor = adafruit_fingerprint.Adafruit_Fingerprint(i2c_bus)
except ValueError as e:
    print(f"I2C bus initialization error (bus locked or GPIO conflict): {e}")
    raise SystemExit(1)
except RuntimeError as e:
    print(f"Fingerprint sensor not found or unresponsive: {e}")
    raise SystemExit(1)
except Exception as e:
    print(f"Unexpected error during sensor initialization: {e}")
    raise SystemExit(1)

try:
    while True:
        try:
            # Acquire fingerprint image
            print("Waiting for fingerprint...")
            ret = sensor.get_image()

            if ret == adafruit_fingerprint.OK:
                print("Processing fingerprint...")
                # Convert image to template
                if sensor.image_2_tz(1) != adafruit_fingerprint.OK:
                    print("Failed to convert image to template.")
                    continue

                # Search for fingerprint in database
                if sensor.finger_search() != adafruit_fingerprint.OK:
                    print("Access Denied")
                else:
                    print(f"Access Granted! ID: {sensor.finger_id}, Confidence: {sensor.confidence}")
            elif ret == adafruit_fingerprint.NOFINGER:
                # No finger detected; loop again
                continue
            else:
                print(f"Sensor error during image acquisition: {ret}")

        except RuntimeError as e:
            # Handle I2C bus errors or sensor communication failures
            print(f"Sensor communication error: {e}")
        except Exception as e:
            # Handle unexpected errors during fingerprint processing
            print(f"Unexpected error during fingerprint processing: {e}")

        # Wait 1 second before next attempt
        time.sleep(1)

except KeyboardInterrupt:
    print("\nExiting program...")

finally:
    # Clean up resources on all exit paths
    if i2c_bus is not None:
        try:
            i2c_bus.deinit()
        except Exception:
            pass
    print("Program finished.")

