except ImportError:
    OutputDevice = None

try:
    from lib_tft144 import TFT144
except ImportError:
    TFT144 = None


class StubOutputDevice:
    def __init__(self, pin: int, active_high: bool = True, initial_value: bool = False):
        self.pin = pin
        self.active_high = active_high
        self._value = bool(initial_value) if active_high else not initial_value

    def on(self):
        self._value = True

    def off(self):
        self._value = False

    def close(self):
        pass


class StubSpidev:
    def __init__(self, bus: int = 0, device: int = 0):
        self.bus = bus
        self.device = device
        self.max_speed_hz = 32000000
        self.mode = 0

    def open(self, bus: int, device: int):
        pass

    def close(self):
        pass

    def writebytes(self, data: List[int]):
        pass


class TFTDisplay:
    def __init__(self, ce_pin: int = 0, dc_pin: int, rst_pin: int, led_pin: int,
                 is_red_board: bool = False, orientation: int = 90,
                 spi_bus: int = 0, spi_device: int = 0, spi_speed: int = 32000000):
        self.ce_pin = ce_pin
        self.dc_pin = dc_pin
        self.rst_pin = rst_pin
        self.led_pin = led_pin
        self.is_red_board = is_red_board
        self.orientation = orientation
        self.spi_bus = spi_bus
        self.spi_device = spi_device
        self.spi_speed = spi_speed

        self.spi: Any = None
        self.dc: Any = None
        self.rst: Any = None
        self.led: Any = None
        self.tft: Any = None

        self._init_hardware()
        atexit.register(self.cleanup)

    def _init_hardware(self):
        if spidev is not None:
            self.spi = spidev.SpiDev()
            try:
                self.spi.open(self.spi_bus, self.spi_device)
                self.spi.max_speed_hz = self.spi_speed
                self.spi.mode = 0
            except Exception as e:
                print(f"Warning: failed to open SPI bus {self.spi_bus} device {self.spi_device}: {e}")
                self.spi = None
        else:
            self.spi = StubSpidev(self.spi_bus, self.spi_device)

        if OutputDevice is not None:
            self.dc = OutputDevice(self.dc_pin)
            self.rst = OutputDevice(self.rst_pin)
            self.led = OutputDevice(self.led_pin, initial_value=True)
        else:
            self.dc = StubOutputDevice(self.dc_pin)
            self.rst = StubOutputDevice(self.rst_pin)
            self.led = StubOutputDevice(self.led_pin, initial_value=True)

        if TFT144 is not None:
            try:
                self.tft = TFT144(self.spi, self.ce_pin, self.dc, self.rst,
                                  self.led_pin, self.is_red_board, self.orientation)
            except Exception as e:
                print(f"Warning: failed to initialize TFT144: {e}")
                self.tft = None
        else:
            self.tft = None

    def cleanup(self):
        if self.spi is not None:
            try:
                self.spi.close()
            except Exception:
                pass
            self.spi = None
        for dev in (self.dc, self.rst, self.led):
            if dev is not None:
                try:
                    dev.close()
                except Exception:
                    pass

    def display_color_cycle(self, colors: List[Tuple[int, int, int]], duration: float = 1.0):
        if self.tft is None:
            return
        for color in colors:
            self.tft.clear_display(color)
            time.sleep(duration)

    def display_character_set(self):
        if self.tft is None:
            return
        print("Displaying character sets:")
        for font_num in range(1, 9):
            print(f"Font {font_num}:")
            x_pos, y_pos = 0, 0
            for char_code in range(33, 127):
                try:
                    self.tft.put_char(chr(char_code), x_pos, y_pos, self.tft.WHITE, self.tft.BLACK, font_num)
                    x_pos += self.tft.fontW
                    if x_pos + self.tft.fontW > 128:
                        x_pos = 0
                        y_pos += self.tft.fontH
                    if y_pos + self.tft.fontH > 128:
                        break
                except Exception as e:
                    print(f"Error displaying character {char_code} in font {font_num}: {e}")
                    break
            time.sleep(2)

        for font_num in [3, 4]:
            print(f"Extended font {font_num}:")
            x_pos, y_pos = 0, 0
            for char_code in range(1, 256):
                try:
                    self.tft.put_char(chr(char_code), x_pos, y_pos, self.tft.WHITE, self.tft.BLACK, font_num)
                    x_pos += self.tft.fontW
                    if x_pos + self.tft.fontW > 128:
                        x_pos = 0
                        y_pos += self.tft.fontH
                    if y_pos + self.tft.fontH > 128:
                        break
                except Exception as e:
                    print(f"Error displaying extended character {char_code} in font {font_num}: {e}")
                    break
            time.sleep(2)

    def display_message(self):
        if self.tft is None:
            return
        print("Displaying message:")
        try:
            self.tft.put_string("Quick Brown fox jumped over", 0, 0, self.tft.WHITE, self.tft.BLACK, 6)
            self.tft.put_string("Quick Brown fox jumped over", 0, 20, self.tft.LIGHTBLUE, self.tft.BLACK, 4)
            self.tft.put_string("Quick Brown fox jumped over", 0, 40, self.tft.LIGHTGREEN, self.tft.BLACK, 2)
            self.tft.put_string("Quick Brown fox jumped over", 0, 60, self.tft.PINK, self.tft.BLACK, 2)
        except Exception as e:
            print(f"Error displaying message: {e}")

    def display_final_message(self):
        if self.tft is None:
            return
        print("Displaying final message:")
        try:
            self.tft.clear_display(self.tft.BLUE)
            self.tft.put_string("Fin.", 30, 40, self.tft.WHITE, self.tft.BLUE, 8)
        except Exception as e:
            print(f"Error displaying final message: {e}")


def _signal_handler(signum, frame):
    raise KeyboardInterrupt


def main():
    signal.signal(signal.SIGTERM, _signal_handler)
    display: Optional[TFTDisplay] = None
    try:
        display = TFTDisplay(dc_pin=22, rst_pin=18, led_pin=23, orientation=90)
        colors = [(255, 0, 0), (0, 255, 0), (0, 0, 255), (255, 255, 0), (0, 255, 255), (255, 0, 255), (255, 255, 255), (0, 0, 0)]
        display.display_color_cycle(colors)
        display.display_character_set()
        display.display_message()
        display.display_final_message()
    except KeyboardInterrupt:
        print("\nExiting program.")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        if display is not None:
            display.cleanup()


if __name__ == "__main__":
    main()

