import http.server
import socketserver
import signal
import sys
import logging

from gpiozero import LED
from gpiozero.exc import GPIOZeroError

PORT = 8080
LED_PIN = 18

logging.basicConfig(level=logging.INFO, format='%(asctime)s [%(levelname)s] %(message)s')
logger = logging.getLogger(__name__)

led = None
httpd = None


class LEDHandler(http.server.BaseHTTPRequestHandler):
    def do_GET(self):
        try:
            if self.path == '/led/on':
                led.on()
                self._respond(200, 'LED is ON')
            elif self.path == '/led/off':
                led.off()
                self._respond(200, 'LED is OFF')
            else:
                self._respond(404, 'Not Found')
        except GPIOZeroError as e:
            logger.error('GPIO error: %s', e)
            self._respond(500, 'Internal Server Error')
        except Exception as e:
            logger.error('Unexpected error: %s', e)
            self._respond(500, 'Internal Server Error')

    def _respond(self, status, message):
        body = message.encode('utf-8')
        self.send_response(status)
        self.send_header('Content-Type', 'text/plain; charset=utf-8')
        self.send_header('Content-Length', str(len(body)))
        self.end_headers()
        try:
            self.wfile.write(body)
        except BrokenPipeError:
            pass

    def log_message(self, fmt, *args):
        logger.info('HTTP: %s - %s', self.client_address[0], fmt % args)


def cleanup(signum=None, frame=None):
    global led, httpd
    logger.info('Shutting down...')
    if httpd is not None:
        httpd.shutdown()
    if led is not None:
        led.close()
    sys.exit(0)


def main():
    global led, httpd

    try:
        led = LED(LED_PIN)
    except GPIOZeroError as e:
        logger.error('Failed to initialize LED on GPIO%d: %s', LED_PIN, e)
        sys.exit(1)

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        httpd = socketserver.ThreadingTCPServer(('0.0.0.0', PORT), LEDHandler)
        logger.info('Serving on port %d', PORT)
        httpd.serve_forever()
    except OSError as e:
        logger.error('Socket error on port %d: %s', PORT, e)
    except Exception as e:
        logger.error('Server error: %s', e)
    finally:
        cleanup()


if __name__ == '__main__':
    main()

