#!/usr/bin/env python3
"""
Rainbow HAT 3-bit binary counter.

Touchpads A/B/C toggle bits 2/1/0 respectively.
Discrete LEDs (red/green/blue) mirror the bit states.
HT16K33 alphanumeric display shows the decimal value 0-7.
APA102 LED strip shows a pattern derived from the value.
Piezo buzzer on GPIO13 plays a tone at MIDI note 60 + value.
"""

import signal
import sys
import time

import board
import busio
import digitalio

try:
    from adafruit_ht16k33.segments import Seg14x4
except Exception:
    Seg14x4 = None

try:
    import adafruit_apds9960.apds9960 as apds9960
except Exception:
    apds9960 = None

try:
    import adafruit_dotstar
except Exception:
    adafruit_dotstar = None

try:
    import adafruit_apa102
except Exception:
    adafruit_apa102 = None

try:
    from gpiozero import Buzzer, LED
except Exception:
    Buzzer = None
    LED = None

# ---- Constants ---------------------------------------------------------------
TOUCH_PINS = {"A": 5, "B": 6, "C": 12}
LED_PINS = {"red": 17, "green": 7, "blue": 8}
BUZZER_PIN = 13
I2C_ADDR = 0x70
NUM_PIXELS = 7
DIM_WHITE = (32, 32, 32)
BRIGHTNESS_SCALE = 32 / 255.0

# ---- Globals -----------------------------------------------------------------
bit_states = [False, False, False]
display = None
led_strip = None
buzzer = None
discrete_leds = {}
running = True


def log_err(msg):
    print(msg, file=sys.stderr, flush=True)


def cleanup(signum=None, frame=None):
    global running
    running = False
    try:
        if display is not None:
            display.fill(0)
            display.show()
    except Exception:
        pass
    try:
        if led_strip is not None:
            led_strip.fill((0, 0, 0))
            led_strip.show()
    except Exception:
        pass
    for led in discrete_leds.values():
        try:
            led.off()
        except Exception:
            pass
    try:
        if buzzer is not None:
            buzzer.off()
    except Exception:
        pass
    if signum is not None:
        sys.exit(0)


def update_discrete_leds():
    for name, led in discrete_leds.items():
        try:
            led.value = bit_states[{"red": 0, "green": 1, "blue": 2}[name]]
        except Exception as e:
            log_err(f"Error updating {name} LED: {e}")


def update_display(value):
    if display is None:
        return
    try:
        display.fill(0)
        display.print_hex(value)
        display.show()
    except Exception as e:
        log_err(f"Error updating display: {e}")


def update_led_strip(value):
    if led_strip is None:
        return
    try:
        led_strip.fill((0, 0, 0))
        if value == 0:
            led_strip[0] = DIM_WHITE
        else:
            red = 255 if bit_states[0] else 0
            green = 255 if bit_states[1] else 0
            blue = 255 if bit_states[2] else 0
            if value == 7:
                for i in range(NUM_PIXELS):
                    led_strip[i] = (red, green, blue)
            else:
                led_strip[value] = (
                    int(red * BRIGHTNESS_SCALE),
                    int(green * BRIGHTNESS_SCALE),
                    int(blue * BRIGHTNESS_SCALE),
                )
        led_strip.show()
    except Exception as e:
        log_err(f"Error updating LED strip: {e}")


def play_tone(value):
    if buzzer is None:
        return
    try:
        midi_note = 60 + value
        freq = 440.0 * (2.0 ** ((midi_note - 69) / 12.0))
        buzzer.on()
        time.sleep(0.5)
        buzzer.off()
    except Exception as e:
        log_err(f"Error playing tone: {e}")


def on_touch(channel):
    try:
        bit_states[channel] = not bit_states[channel]
    except Exception as e:
        log_err(f"Error toggling bit {channel}: {e}")
        return
    value = (4 if bit_states[0] else 0) | (2 if bit_states[1] else 0) | (1 if bit_states[2] else 0)
    update_discrete_leds()
    update_display(value)
    update_led_strip(value)
    play_tone(value)


def init_display():
    global display
    if Seg14x4 is None:
        log_err("ht16k33 not available; display disabled.")
        return
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        display = Seg14x4(i2c, address=I2C_ADDR)
        display.brightness = 0.5
        display.fill(0)
        display.show()
    except Exception as e:
        log_err(f"Error initializing display: {e}")
        display = None


def init_led_strip():
    global led_strip
    if adafruit_apa102 is not None:
        try:
            led_strip = adafruit_apa102.APA102(
                num_led=NUM_PIXELS, global_brightness=30, mosi=board.D10, sclk=board.D11
            )
            led_strip.fill((0, 0, 0))
            led_strip.show()
        except Exception as e:
            log_err(f"Error initializing APA102: {e}")
            led_strip = None
    elif adafruit_dotstar is not None:
        try:
            led_strip = adafruit_dotstar.DotStar(
                NUM_PIXELS, brightness=0.2, data_pin=board.D10, clock_pin=board.D11
            )
            led_strip.fill((0, 0, 0))
            led_strip.show()
        except Exception as e:
            log_err(f"Error initializing DotStar: {e}")
            led_strip = None
    else:
        log_err("No LED strip library available; strip disabled.")


def init_buzzer():
    global buzzer
    if Buzzer is None:
        log_err("gpiozero not available; buzzer disabled.")
        return
    try:
        buzzer = Buzzer(BUZZER_PIN)
    except Exception as e:
        log_err(f"Error initializing buzzer: {e}")
        buzzer = None


def init_discrete_leds():
    global discrete_leds
    if LED is None:
        log_err("gpiozero not available; discrete LEDs disabled.")
        return
    for name, pin in LED_PINS.items():
        try:
            discrete_leds[name] = LED(pin)
        except Exception as e:
            log_err(f"Error initializing {name} LED: {e}")
            discrete_leds[name] = None


def init_touchpads():
    if apds9960 is None:
        log_err("apds9960 not available; touchpads disabled.")
        return
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        sensor = apds9960.APDS9960(i2c)
        sensor.enable_proximity = True
        sensor.enable_gesture = True
        sensor.enable_color = False
        sensor.enable_light = False
        sensor.proximity_threshold = (200, 255)
    except Exception as e:
        log_err(f"Error initializing touchpads: {e}")
        return
    try:
        while running:
            gesture = sensor.gesture()
            if gesture == 0x01:  # UP
                on_touch(0)
            elif gesture == 0x02:  # DOWN
                on_touch(1)
            elif gesture == 0x03:  # LEFT
                on_touch(2)
            time.sleep(0.05)
    except Exception as e:
        log_err(f"Error reading touchpads: {e}")


def main():
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    init_display()
    init_led_strip()
    init_buzzer()
    init_discrete_leds()

    if apds9960 is not None:
        import threading
        t = threading.Thread(target=init_touchpads, daemon=True)
        t.start()
    else:
        log_err("apds9960 not available; touchpads disabled.")

    try:
        while running:
            signal.pause()
    except Exception as e:
        log_err(f"Main loop error: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

