import signal
import sys
import time

from gpiozero import LED
from gpiozero.exc import GPIOZeroError, GPIODeviceError


class LEDController:
    """Controls an LED connected to a Raspberry Pi GPIO pin using gpiozero."""

    def __init__(self, pin: int):
        """
        Initialize the LEDController.

        Args:
            pin: The GPIO pin number (BCM numbering) connected to the LED.

        Raises:
            ValueError: If the pin is invalid or unavailable.
        """
        if not isinstance(pin, int) or pin < 0:
            raise ValueError(f"Invalid GPIO pin: {pin!r}")

        try:
            self.led = LED(pin)
        except (GPIOZeroError, GPIODeviceError) as exc:
            raise ValueError(f"Failed to initialize LED on GPIO {pin}: {exc}") from exc

    def on(self) -> None:
        """Turn the LED on."""
        self.led.on()

    def off(self) -> None:
        """Turn the LED off."""
        self.led.off()

    def blink(self, on_duration: float, off_duration: float) -> None:
        """
        Blink the LED once with specified on and off durations.

        Args:
            on_duration: Time in seconds the LED stays on (must be >= 0).
            off_duration: Time in seconds the LED stays off (must be >= 0).

        Raises:
            ValueError: If either duration is negative.
        """
        if on_duration < 0 or off_duration < 0:
            raise ValueError("Durations must be non-negative.")

        self.on()
        time.sleep(on_duration)
        self.off()
        time.sleep(off_duration)

    def cleanup(self) -> None:
        """Turn the LED off and release the GPIO resource."""
        try:
            self.off()
        except Exception:
            pass
        try:
            self.led.close()
        except Exception:
            pass


def main() -> None:
    """Main entry point: blink an LED on GPIO 25 until interrupted."""
    LED_PIN = 25
    controller = None

    def _signal_handler(signum, frame):
        print(f"\nReceived signal {signum}, shutting down...")
        if controller is not None:
            controller.cleanup()
        sys.exit(0)

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        controller = LEDController(LED_PIN)
        print(f"LEDController initialized on GPIO {LED_PIN}. Press Ctrl+C to stop.")
        while True:
            controller.blink(1.0, 0.5)
    except ValueError as exc:
        print(f"Initialization error: {exc}", file=sys.stderr)
        if controller is not None:
            controller.cleanup()
        sys.exit(1)
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
        if controller is not None:
            controller.cleanup()
        sys.exit(1)


if __name__ == "__main__":
    main()

