import RPi.GPIO as GPIO
import time
import signal
import sys

# Healthcare monitoring: drive a servo to point a gauge needle at heart rate
SERVO_PIN = 18
PWM_FREQUENCY = 50  # Hz, standard for SG90
DUTY_MIN = 2.5      # 0 degrees
DUTY_MAX = 12.5     # 180 degrees
HR_MIN = 40
HR_MAX = 180

# Global handle so signal handlers can release resources
servo_pwm = None


def map_to_angle(heart_rate_value):
    """Map a heart rate reading to a servo angle in degrees."""
    if heart_rate_value <= HR_MIN:
        return 0
    if heart_rate_value >= HR_MAX:
        return 180
    return int((heart_rate_value - HR_MIN) * 180 / (HR_MAX - HR_MIN))


def angle_to_duty(angle):
    """Convert a servo angle (0-180) to a PWM duty cycle percentage."""
    return DUTY_MIN + (angle / 180.0) * (DUTY_MAX - DUTY_MIN)


def cleanup(signum=None, frame=None):
    """Release GPIO resources on exit or signal."""
    global servo_pwm
    if servo_pwm is not None:
        try:
            servo_pwm.stop()
        except Exception:
            pass
        servo_pwm = None
    try:
        GPIO.cleanup()
    except Exception:
        pass
    if signum is not None:
        sys.exit(0)


def main():
    global servo_pwm

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(SERVO_PIN, GPIO.OUT)
        servo_pwm = GPIO.PWM(SERVO_PIN, PWM_FREQUENCY)
        servo_pwm.start(0)
    except Exception as e:
        print(f"Failed to initialize GPIO/PWM: {e}")
        cleanup()
        return

    heart_rate_readings = [62, 75, 88, 110, 95]

    try:
        for heart_rate in heart_rate_readings:
            target_angle = map_to_angle(heart_rate)
            duty_cycle = angle_to_duty(target_angle)
            servo_pwm.ChangeDutyCycle(duty_cycle)
            print(f"Heart rate {heart_rate} bpm -> servo angle {target_angle} degrees")
            time.sleep(0.8)
    except Exception as e:
        print(f"Error during servo operation: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

