import time
import signal
import sys
import board
import busio
import adafruit_tcs34725
from PIL import Image

# Constants
IMAGE_PATH = 'image.jpg'
RESIZE_WIDTH = 100
RESIZE_HEIGHT = 100
INTEGRATION_TIME = adafruit_tcs34725.INTEGRATION_TIME_50MS
GAIN = adafruit_tcs34725.GAIN_4X

# Global state for cleanup
i2c = None
sensor = None
running = True


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global running
    running = False


def initialize_i2c():
    """Initialize the I2C bus on board.SCL / board.SDA."""
    global i2c
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        return i2c
    except Exception as e:
        print(f"Error initializing I2C bus: {e}", file=sys.stderr)
        return None


def initialize_color_sensor(i2c_bus):
    """Initialize the TCS34725 color sensor at address 0x29."""
    global sensor
    try:
        sensor = adafruit_tcs34725.TCS34725(i2c_bus, address=0x29)
        sensor.integration_time = INTEGRATION_TIME
        sensor.gain = GAIN
        return sensor
    except ValueError as e:
        print(f"TCS34725 not found at address 0x29: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Error initializing TCS34725: {e}", file=sys.stderr)
        return None


def get_sensor_color_data(color_sensor):
    """Read (R, G, B, Clear) from the TCS34725. Returns (0,0,0,0) on error."""
    try:
        red, green, blue, clear = color_sensor.color_rgb_bytes
        return (red, green, blue, clear)
    except Exception as e:
        print(f"Error reading color sensor data: {e}", file=sys.stderr)
        return (0, 0, 0, 0)


def find_dominant_image_color(image_path):
    """Find the dominant color in a resized image. Returns (0,0,0) on error."""
    try:
        with Image.open(image_path) as img:
            img = img.resize((RESIZE_WIDTH, RESIZE_HEIGHT))
            colors = img.getcolors(RESIZE_WIDTH * RESIZE_HEIGHT)
            if colors:
                dominant_color = max(colors, key=lambda item: item[0])[1]
                return dominant_color
            return (0, 0, 0)
    except FileNotFoundError:
        print(f"Image file not found: {image_path}", file=sys.stderr)
        return (0, 0, 0)
    except Exception as e:
        print(f"Error processing image: {e}", file=sys.stderr)
        return (0, 0, 0)


def cleanup():
    """Release I2C resources."""
    global i2c
    if i2c is not None:
        try:
            i2c.deinit()
        except Exception:
            pass
        i2c = None


def main():
    """Main loop: read sensor and image color every second."""
    global running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        cleanup()
        sys.exit(1)

    color_sensor = initialize_color_sensor(i2c_bus)
    if color_sensor is None:
        cleanup()
        sys.exit(1)

    try:
        while running:
            sensor_data = get_sensor_color_data(color_sensor)
            dominant_image_color = find_dominant_image_color(IMAGE_PATH)

            print(f"Sensor Color Data (R, G, B, Clear): {sensor_data}")
            print(f"Dominant Image Color: {dominant_image_color}")
            print("-" * 40)

            # Sleep in small increments so signals are caught promptly
            for _ in range(10):
                if not running:
                    break
                time.sleep(0.1)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

