#!/usr/bin/env python3
"""
Wildlife tracking IoT controller for Raspberry Pi.
Listens on 127.0.0.1:9099 for remote control commands.
Supports Adafruit Ultimate GPS on UART (GPIO14/15) or I2C (addr 0x42).
Falls back to simulated coordinates if no GPS is present.
"""

import json
import logging
import signal
import socket
import sys
import time
from typing import Optional, Tuple

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
    stream=sys.stderr,
)
logger = logging.getLogger(__name__)

# Constants
LISTEN_HOST = "127.0.0.1"
LISTEN_PORT = 9099
GPS_UART_PORT = "/dev/serial0"  # GPIO14=TXD, GPIO15=RXD
GPS_I2C_ADDR = 0x42
GPS_READ_TIMEOUT = 5  # seconds

# Global state
tracking_state = "stopped"
gps_connection = None
shutdown_flag = False


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global shutdown_flag
    logger.info("Received signal %d, shutting down...", signum)
    shutdown_flag = True


def init_gps_uart() -> Optional[object]:
    """Initialize GPS module on UART. Returns serial object or None."""
    try:
        import serial
        ser = serial.Serial(
            port=GPS_UART_PORT,
            baudrate=9600,
            timeout=1,
            write_timeout=1,
        )
        logger.info("GPS UART initialized on %s", GPS_UART_PORT)
        return ser
    except serial.SerialException as e:
