import signal
import sys
import time
from gpiozero import LED
from gpiozero.exc import GPIOZeroError, GPIODeviceError

# Define GPIO pins for LEDs (BCM numbering)
LED_PIN_1 = 18
LED_PIN_2 = 23

# Global references for cleanup
led1 = None
led2 = None


def initialize_gpio():
    """Initializes the GPIO pins for LED control using gpiozero."""
    global led1, led2
    try:
        led1 = LED(LED_PIN_1)
        led2 = LED(LED_PIN_2)
    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"Error initializing GPIO: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error during GPIO initialization: {e}", file=sys.stderr)
        sys.exit(1)


def turn_on_leds():
    """Turns on both LEDs."""
    try:
        if led1 and led2:
            led1.on()
            led2.on()
    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"Error turning on LEDs: {e}", file=sys.stderr)


def turn_off_leds():
    """Turns off both LEDs."""
    try:
        if led1 and led2:
            led1.off()
            led2.off()
    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"Error turning off LEDs: {e}", file=sys.stderr)


def toggle_leds(cycle_count=5, on_duration=1, off_duration=1):
    """Toggles both LEDs on and off recursively for a specified number of cycles."""
    if cycle_count <= 0:
        return

    turn_on_leds()
    time.sleep(on_duration)
    turn_off_leds()
    time.sleep(off_duration)

    toggle_leds(cycle_count - 1, on_duration, off_duration)


def cleanup_gpio(signum=None, frame=None):
    """Cleans up the GPIO resources."""
    global led1, led2
    try:
        if led1:
            led1.close()
        if led2:
            led2.close()
    except Exception as e:
        print(f"Error during GPIO cleanup: {e}", file=sys.stderr)
    finally:
        led1 = None
        led2 = None
        if signum is not None:
            sys.exit(0)


def main():
    """Main function to control the LEDs."""
    signal.signal(signal.SIGINT, cleanup_gpio)

    initialize_gpio()

    try:
        toggle_leds(cycle_count=5, on_duration=1, off_duration=1)
    except Exception as e:
        print(f"Error during LED toggling: {e}", file=sys.stderr)
    finally:
        cleanup_gpio()


if __name__ == "__main__":
    main()

