import random
import time
import signal
import sys

try:
    from gpiozero import OutputDevice
    from gpiozero.exc import GPIOZeroError, GPIODeviceError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

PUMP_PIN = 17
MOISTURE_THRESHOLD = 30
ITERATIONS = 5
DELAY_SECONDS = 2

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_soil_moisture():
    """Simulate a soil-moisture reading in the range 0-100 inclusive."""
    return random.randint(0, 100)

def control_water_pump(pump, moisture_level):
    """Turn the pump on or off based on the moisture level and print the action."""
    if moisture_level < MOISTURE_THRESHOLD:
        pump.on()
        print(f"  -> Pump ON  (soil too dry: {moisture_level}% < {MOISTURE_THRESHOLD}%)")
    else:
        pump.off()
        print(f"  -> Pump OFF (soil moisture adequate: {moisture_level}% >= {MOISTURE_THRESHOLD}%)")

def main():
    global _running
    _running = True

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    pump = None
    try:
        pump = OutputDevice(PUMP_PIN)
        print(f"Pump initialized on GPIO {PUMP_PIN} (BCM). Starting {ITERATIONS} iterations...")

        for i in range(ITERATIONS):
            if not _running:
                print("\nShutdown signal received; exiting loop early.")
                break

            moisture = read_soil_moisture()
            print(f"Iteration {i + 1}/{ITERATIONS}: Soil Moisture = {moisture}%")
            control_water_pump(pump, moisture)

            if i < ITERATIONS - 1 and _running:
                time.sleep(DELAY_SECONDS)

    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"GPIO error: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if pump is not None:
            try:
                pump.off()
                pump.close()
                print("Pump turned off and GPIO released.")
            except Exception as e:
                print(f"Error during cleanup: {e}")
        print("Program finished.")

if __name__ == "__main__":
    main()

