# Healthcare monitoring cart line-following controller
# Uses two TCRT5000 reflectance sensors and two motors
LEFT_SENSOR_PIN = 5
RIGHT_SENSOR_PIN = 6
LEFT_MOTOR_PIN = 16
RIGHT_MOTOR_PIN = 26

def setup_line_sensors():
    """Configure GPIO pins for the two reflectance sensors."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LEFT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        GPIO.setup(RIGHT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    except Exception as e:
        print(f"Error setting up sensors: {e}")
        sys.exit(1)

def read_sensor(sensor_pin):
    """Read a reflectance sensor and return True when the line is detected."""
    try:
        return GPIO.input(sensor_pin) == GPIO.LOW
    except Exception as e:
        print(f"Error reading sensor on pin {sensor_pin}: {e}")
        return False

def steer_cart(left_on, right_on):
    """Drive the two motors to steer the healthcare cart."""
    try:
        GPIO.output(LEFT_MOTOR_PIN, left_on)
        GPIO.output(RIGHT_MOTOR_PIN, right_on)
    except Exception as e:
        print(f"Error setting motor outputs: {e}")

def main():
    """Main loop for the healthcare monitoring cart line following."""
    try:
        setup_line_sensors()
        GPIO.setup(LEFT_MOTOR_PIN, GPIO.OUT, initial=GPIO.LOW)
        GPIO.setup(RIGHT_MOTOR_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"Error during GPIO setup: {e}")
        GPIO.cleanup()
        sys.exit(1)

    try:
        for iteration in range(20):
            left_line = read_sensor(LEFT_SENSOR_PIN)
            right_line = read_sensor(RIGHT_SENSOR_PIN)
            if left_line and not right_line:
