import time
import struct
import logging
import signal
import sys
import serial
from pymodbus.client import ModbusSerialClient
from pymodbus.exceptions import ModbusException

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

SERIAL_PORT = '/dev/serial0'
BAUDRATE = 115200
TIMEOUT = 1.0
RETRY_COUNT = 3
RETRY_DELAY = 0.1


class Servo:
    """
    A class for controlling a servo motor via Modbus RTU over Raspberry Pi UART.
    """

    # Register map
    STATUS = {'R/W': 'R', 'Register': 0x3000, 'functioncode': 3}
    CONTROL = {'R/W': 'W', 'Register': 0x3100, 'functioncode': 6, 'Value': {'Stop': 0x0006, 'Start': 0x000F}}
    OPMODE = {'R/W': 'W', 'Register': 0x3500, 'functioncode': 6, 'Value': {'Position': 1}}
    VelocityCommand = {'R/W': 'W', 'Register': 0x6F00, 'functioncode': 16}
    VelocityFeedback = {'R/W': 'R', 'Register': 0x3B00, 'functioncode': 3, 'read_length': 2}
    PositionCommand = {'R/W': 'W', 'Register': 0x4000, 'functioncode': 16}
    PositionFeedback = {'R/W': 'R', 'Register': 0x3700, 'functioncode': 3, 'read_length': 2}

    def __init__(self, port=SERIAL_PORT, baudrate=BAUDRATE, timeout=TIMEOUT):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.client = None
        self._running = True
        self._connect()

    def _connect(self):
        try:
            self.client = ModbusSerialClient(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=8,
                parity='N',
                stopbits=1,
                timeout=self.timeout
            )
            if not self.client.connect():
                raise serial.SerialException(f"Failed to open serial port {self.port}")
            logging.info(f"Connected to Modbus RTU on {self.port} at {self.baudrate} baud.")
        except serial.SerialException as e:
            logging.warning(f"Serial port unavailable ({e}). Running in degraded mode.")
            self.client = None
        except Exception as e:
            logging.error(f"Error connecting to Modbus RTU: {e}")
            self.client = None

    def _read_register(self, register_info, read_length=1):
        if self.client is None:
            logging.warning("Client not initialized; cannot read register.")
            return None
        try:
            address = register_info['Register']
            functioncode = register_info['functioncode']
            if functioncode == 3:
                result = self.client.read_holding_registers(address, read_length, slave=1)
                if result.isError():
                    raise ModbusException(f"Modbus error reading register 0x{address:04X}: {result}")
                return result.registers
            else:
                raise ValueError(f"Invalid function code {functioncode} for read operation.")
        except ModbusException as e:
            logging.error(f"Modbus error reading register: {e}")
            return None
        except Exception as e:
            logging.error(f"Error reading register: {e}")
            return None

    def _write_register(self, register_info, value):
        if self.client is None:
            logging.warning("Client not initialized; cannot write register.")
            return False
        try:
            address = register_info['Register']
            functioncode = register_info['functioncode']
            if functioncode == 6:
                result = self.client.write_register(address, value, slave=1)
            elif functioncode == 16:
                if isinstance(value, (list, tuple)):
                    result = self.client.write_registers(address, value, slave=1)
                else:
                    result = self.client.write_registers(address, [value], slave=1)
            else:
                raise ValueError(f"Invalid function code {functioncode} for write operation.")
            if result.isError():
                raise ModbusException(f"Modbus error writing register 0x{address:04X}: {result}")
            return True
        except ModbusException as e:
            logging.error(f"Modbus error writing register: {e}")
            return False
        except Exception as e:
            logging.error(f"Error writing register: {e}")
            return False

    def read(self, register_info, retry=RETRY_COUNT):
        for attempt in range(retry):
            data = self._read_register(register_info)
            if data is not None:
                return data
            logging.warning(f"Read attempt {attempt + 1}/{retry} failed.")
            time.sleep(RETRY_DELAY)
        logging.error(f"Failed to read register {register_info['Register']} after {retry} attempts.")
        return None

    def write(self, register_info, value, retry=RETRY_COUNT):
        for attempt in range(retry):
            if self._write_register(register_info, value):
                return True
            logging.warning(f"Write attempt {attempt + 1}/{retry} failed.")
            time.sleep(RETRY_DELAY)
        logging.error(f"Failed to write to register {register_info['Register']} after {retry} attempts.")
        return False

    def close(self):
        if self.client:
            try:
                self.client.close()
                logging.info("Modbus connection closed.")
            except Exception as e:
                logging.error(f"Error closing Modbus connection: {e}")
            finally:
                self.client = None

    def signal_handler(self, signum, frame):
        logging.info(f"Signal {signum} received, shutting down.")
        self._running = False
        self.close()
        sys.exit(0)


def main():
    servo = Servo()
    signal.signal(signal.SIGINT, servo.signal_handler)
    signal.signal(signal.SIGTERM, servo.signal_handler)

    try:
        logging.info("Reading Status register...")
        status = servo.read(Servo.STATUS)
        if status is not None:
            logging.info(f"Status: {status}")

        logging.info("Setting OPMODE to Position...")
        if servo.write(Servo.OPMODE, Servo.OPMODE['Value']['Position']):
            logging.info("OPMODE set to Position.")

        logging.info("Setting VelocityCommand to 1000...")
        if servo.write(Servo.VelocityCommand, 1000):
            logging.info("VelocityCommand set to 1000.")

        logging.info("Reading VelocityFeedback...")
        velocity = servo.read(Servo.VelocityFeedback)
        if velocity is not None:
            logging.info(f"VelocityFeedback: {velocity}")

        logging.info("Reading PositionFeedback...")
        position = servo.read(Servo.PositionFeedback)
        if position is not None:
            logging.info(f"PositionFeedback: {position}")

        logging.info("Starting servo...")
        if servo.write(Servo.CONTROL, Servo.CONTROL['Value']['Start']):
            logging.info("Servo started.")

        time.sleep(2)

        logging.info("Stopping servo...")
        if servo.write(Servo.CONTROL, Servo.CONTROL['Value']['Stop']):
            logging.info("Servo stopped.")

    finally:
        servo.close()


if __name__ == '__main__':
    main()

