import signal
import sys
import time
import logging
import serial
import minimalmodbus

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class ServoMotor:
    """
    Controls a servo motor via Modbus RTU over a serial bus on a Raspberry Pi.

    Wiring (example: Pi 3/4/5):
      - Servo TX  -> Pi GPIO14 (TXD, pin 8)
      - Servo RX  -> Pi GPIO15 (RXD, pin 10)
      - Servo GND -> Pi GND
      - Servo VCC -> 24 V supply (servo adapter)
    Enable /dev/serial0 with:
      sudo raspi-config  -> Interface Options -> Serial Port
      login shell: no, hardware port: yes
    """

    def __init__(self, port='/dev/serial0', baudrate=115200, timeout=1.0, slave_address=1):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.slave_address = slave_address
        self.instrument = None
        self._running = False

    def connect(self):
        """Open the serial port and configure the minimalmodbus instrument."""
        try:
            self.instrument = minimalmodbus.Instrument(self.port, self.slave_address)
            self.instrument.serial.baudrate = self.baudrate
            self.instrument.serial.bytesize = 8
            self.instrument.serial.parity = serial.PARITY_NONE
            self.instrument.serial.stopbits = 1
            self.instrument.serial.timeout = self.timeout
            self.instrument.serial.write_timeout = self.timeout
            self.instrument.mode = minimalmodbus.MODE_RTU
            self.instrument.serial.open()
            if not self.instrument.serial.is_open:
                raise IOError(f"Failed to open serial port {self.port}")
            logger.info(f"Connected to servo on {self.port} @ {self.baudrate} baud, slave {self.slave_address}")
            return True
        except serial.SerialException as e:
            logger.error(f"Serial error connecting to servo on {self.port}: {e}")
            self.instrument = None
            return False
        except Exception as e:
            logger.error(f"Unexpected error connecting to servo: {e}")
            self.instrument = None
            return False

    def disconnect(self):
        """Close the serial port if open."""
        if self.instrument is not None:
            try:
                if self.instrument.serial.is_open:
                    self.instrument.serial.close()
                    logger.info("Serial port closed.")
            except Exception as e:
                logger.warning(f"Error closing serial port: {e}")
            finally:
                self.instrument = None

    def _write_register(self, register_address, value, functioncode=16, decimals=0):
        """Generic Modbus write to a 16-bit register."""
        if self.instrument is None:
            raise RuntimeError("Not connected to servo. Call connect() first.")
        try:
            self.instrument.write_register(register_address, value, functioncode=functioncode, signed=True, decimals=decimals)
            logger.debug(f"Wrote {value} to register 0x{register_address:04X}")
            return True
        except minimalmodbus.NoResponseError as e:
            logger.error(f"No response from servo at register 0x{register_address:04X}: {e}")
            return False
        except minimalmodbus.ModbusException as e:
            logger.error(f"Modbus error writing to register 0x{register_address:04X}: {e}")
            return False
        except serial.SerialException as e:
            logger.error(f"Serial error writing to register 0x{register_address:04X}: {e}")
            return False
        except Exception as e:
            logger.error(f"Unexpected error writing to register 0x{register_address:04X}: {e}")
            return False

    def _read_register(self, register_address, functioncode=3, decimals=0):
        """Generic Modbus read from a 16-bit register."""
        if self.instrument is None:
            raise RuntimeError("Not connected to servo. Call connect() first.")
        try:
            value = self.instrument.read_register(register_address, functioncode=functioncode, signed=True, decimals=decimals)
            logger.debug(f"Read {value} from register 0x{register_address:04X}")
            return value
        except minimalmodbus.NoResponseError as e:
            logger.error(f"No response from servo at register 0x{register_address:04X}: {e}")
            return None
        except minimalmodbus.ModbusException as e:
            logger.error(f"Modbus error reading from register 0x{register_address:04X}: {e}")
            return None
        except serial.SerialException as e:
            logger.error(f"Serial error reading from register 0x{register_address:04X}: {e}")
            return None
        except Exception as e:
            logger.error(f"Unexpected error reading from register 0x{register_address:04X}: {e}")
            return None

    def set_operation_mode(self, mode):
        """Set the servo operation mode (register 0x3500)."""
        if not isinstance(mode, int) or not (0 <= mode <= 255):
            raise ValueError(f"mode must be an int in [0, 255], got {mode!r}")
        return self._write_register(0x3500, mode)

    def write_position_command(self, value):
        """Write a position command (register 0x4000)."""
        if not isinstance(value, (int, float)):
            raise ValueError(f"value must be numeric, got {value!r}")
        return self._write_register(0x4000, value)

    def write_velocity_command(self, value):
