import time
import signal
import sys
from gpiozero import OutputDevice, Servo

# BCM pin assignments
LASER_PIN = 17
H_SERVO_PIN = 18
V_SERVO_PIN = 19

# Servo pulse width mapping: 0.0 (min) -> 1.0 (max)
# gpiozero.Servo expects values in [-1, 1]; we map [0, 1] to [-1, 1]
def _map_pw(pw):
    return pw * 2 - 1

class Laser:
    def __init__(self, pin=LASER_PIN):
        self.pin = pin
        try:
            self.device = OutputDevice(pin)
        except Exception as e:
            raise RuntimeError(f"Failed to initialize laser on GPIO{pin}: {e}") from e

    def on(self):
        self.device.on()

    def off(self):
        self.device.off()

    def close(self):
        self.device.close()


class Aim:
    def __init__(self, ld, sd):
        self.ld = ld
        self.sd = sd
        self.laser = None
        self.h_servo = None
        self.v_servo = None
        try:
            self.laser = Laser()
            self.h_servo = Servo(H_SERVO_PIN)
            self.v_servo = Servo(V_SERVO_PIN)
        except Exception as e:
            self.close()
            raise RuntimeError(f"Failed to initialize aim hardware: {e}") from e

        # Horizontal positions: 10 steps from 0.0 to 1.0
        self.hp = [i * 0.1 for i in range(10)]
        # Vertical positions: 10 steps from 0.0 to 1.0
        self.vp = [i * 0.1 for i in range(10)]

    def _move(self, h_idx, v_idx):
        if not (0 <= h_idx < len(self.hp) and 0 <= v_idx < len(self.vp)):
            raise IndexError("Position indices out of range")
        self.h_servo.value = _map_pw(self.hp[h_idx])
        self.v_servo.value = _map_pw(self.vp[v_idx])

    def aim(self, nums):
        try:
            for b in nums:
                if b < 1 or b > 10:
                    raise ValueError(f"Target index {b} out of range (1-10)")
                self._move(b - 1, b - 1)
                time.sleep(self.sd / 2)
                self.laser.on()
                time.sleep(self.ld)
                self.laser.off()
                self._move(10, 10)
                time.sleep(self.sd / 2)
        except Exception as e:
            print(f"Error during aiming: {e}", file=sys.stderr)
        finally:
            self.laser.off()

    def close(self):
        if self.laser:
            self.laser.close()
            self.laser = None
        if self.h_servo:
            self.h_servo.close()
            self.h_servo = None
        if self.v_servo:
            self.v_servo.close()
            self.v_servo = None


def main():
    aim = None
    def signal_handler(signum, frame):
        print("\nInterrupt received, cleaning up...")
        if aim:
            aim.close()
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        aim = Aim(ld=0.5, sd=0.2)
        # Example: aim at targets 1, 3, 5
        aim.aim([1, 3, 5])
    except Exception as e:
        print(f"Fatal error: {e}", file=sys.stderr)
    finally:
        if aim:
            aim.close()


if __name__ == "__main__":
    main()

