    print(f"Error initializing ServoKit: {e}", file=sys.stderr)
    sys.exit(1)

def move_servo(channel, target_angle, step_size=5, delay=0.04):
    """Moves a servo smoothly to a target angle with error handling."""
    if not 0 <= channel <= 15:
        print(f"Error: Invalid servo channel {channel}. Must be 0-15.", file=sys.stderr)
        return
    if not 0 <= target_angle <= 180:
        print(f"Error: Invalid target angle {target_angle}. Must be 0-180.", file=sys.stderr)
        return
    try:
        current_angle = kit.servo[channel].angle
        if current_angle is None:
            current_angle = 0
        current_angle = int(current_angle)
        target_angle = int(target_angle)
        if target_angle > current_angle:
            angles = range(current_angle, target_angle, step_size)
        else:
            angles = range(current_angle, target_angle, -step_size)
        for angle in angles:
            if not _running:
                return
            kit.servo[channel].angle = angle
            time.sleep(delay)
        kit.servo[channel].angle = target_angle
    except Exception as e:
        print(f"Error moving servo on channel {channel}: {e}", file=sys.stderr)

def seek(angle):
    move_servo(SEEK, angle)

def deseek(angle):
    move_servo(SEEK, angle)

def drop(angle):
    move_servo(DROP, angle)

def pick(angle):
    move_servo(BASE, angle)

def grab(angle):
    move_servo(GRAB, angle)

def release(angle):
    move_servo(GRAB, angle)

def collect_object_steps(seek_angle):
    """Performs the steps to collect an object."""
    seek(seek_angle)
    grab(90)
    drop(160)
    drop(100)
    seek(90)

def drop_object_steps(drop_angle):
    """Performs the steps to drop an object."""
    drop(drop_angle)
    release(120)
    drop(100)

def get_pos_x(x_center):
    """Calculates the x-position based on pixel coordinates."""
    if x_center < 0 or x_center > 320:
        print(f"Warning: x_center {x_center} out of expected range 0-320.", file=sys.stderr)
        return DEFAULT_ANGLE
    return int((x_center - 160) / 2 + 90)

def get_pos_y(y_center):
    """Calculates the y-position based on pixel coordinates."""
    if y_center < 0 or y_center > 240:
        print(f"Warning: y_center {y_center} out of expected range 0-240.", file=sys.stderr)
        return DEFAULT_ANGLE
    return int((y_center - 120) / 2 + 90)

def collect_object(x_center, y_center, drop_angle):
    """Collects an object and drops it in the correct bin."""
    pos_x = get_pos_x(x_center)
    pos_y = get_pos_y(y_center)
    try:
        pick(pos_x)
        collect_object_steps(pos_y)
        drop_object_steps(drop_angle)
        pick(DEFAULT_ANGLE)
    except Exception as e:
        print(f"Error during object collection: {e}", file=sys.stderr)

def cleanup():
    """Release all servos to default position and deinitialize I2C."""
    print("Cleaning up servos...")
    for ch in range(16):
        try:
            kit.servo[ch].angle = DEFAULT_ANGLE
        except Exception:
            pass
    try:
        i2c.deinit()
    except Exception:
        pass

if __name__ == "__main__":
    try:
        # Example usage
        collect_object(160, 120, METAL)
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    finally:
        cleanup()

