import logging
import signal
import sys
from typing import Dict, Callable, Optional

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

PUMP_PIN = 20
LIGHT_PIN = 21

actuators: Dict[str, OutputDevice] = {}


def parse_intent(phrase: str) -> Optional[str]:
    """Return the intent keyword for a given phrase, or None if unknown."""
    keywords: Dict[str, str] = {
        "pump on": "pump_on",
        "pump off": "pump_off",
        "light on": "light_on",
        "light off": "light_off",
        "switch the light": "light_toggle",
    }
    normalized = phrase.lower().strip()
    for key, intent in keywords.items():
        if key in normalized:
            return intent
    return None


def apply_intent(intent: str, actuators: Dict[str, OutputDevice]) -> None:
    """Drive the pump or light based on the parsed intent."""
    actions: Dict[str, Callable[[], None]] = {
        "pump_on": lambda: actuators["pump"].on(),
        "pump_off": lambda: actuators["pump"].off(),
        "light_toggle": lambda: actuators["light"].toggle(),
    }
    action = actions.get(intent)
    if action is None:
        logging.warning("Unknown intent '%s' - no action taken.", intent)
        return
    try:
        action()
        logging.info("Applied intent '%s'.", intent)
    except GPIOZeroError as exc:
        logging.error("Failed to apply intent '%s': %s", intent, exc)


def cleanup(signum: Optional[int] = None, frame=None) -> None:
    """Turn off all actuators and release GPIO resources."""
    for name, dev in actuators.items():
        try:
            dev.off()
            dev.close()
        except Exception as exc:
            logging.error("Error closing %s: %s", name, exc)
    logging.info("Actuators cleaned up. Exiting.")
    if signum is not None:
        sys.exit(0)


def main() -> None:
    """Initialize actuators, process test phrases, and ensure cleanup."""
    global actuators
    try:
        actuators = {
            "pump": OutputDevice(PUMP_PIN),
            "light": OutputDevice(LIGHT_PIN),
        }
    except GPIOZeroError as exc:
        logging.error("Failed to initialize GPIO: %s", exc)
        sys.exit(1)

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    test_phrases = [
        "turn the pump on",
        "switch the light",
        "turn pump off",
        "unknown command",
    ]

    try:
        for phrase in test_phrases:
            intent = parse_intent(phrase)
            if intent is None:
                logging.warning("Could not parse phrase: '%s'", phrase)
                continue
            logging.info("Parsed phrase '%s' -> intent '%s'", phrase, intent)
            apply_intent(intent, actuators)
    except Exception as exc:
        logging.error("Unexpected error during processing: %s", exc)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

