import signal
import sys
import time
import logging
from ina219 import INA219, DeviceRangeError
from smbus2 import SMBus

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

DEVICE_BUS = 1
DEVICE_ADDRESS = 0x17
SUPPLY_INA219_ADDRESS = 0x40
BATTERY_INA219_ADDRESS = 0x45
SHUNT_RESISTOR_SUPPLY = 0.00725
SHUNT_RESISTOR_BATTERY = 0.005
CALIBRATION_VALUE = 4096
READ_INTERVAL_SECONDS = 5

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def read_i2c_register(bus, register):
    try:
        return bus.read_word_data(DEVICE_ADDRESS, register)
    except OSError as e:
        logger.warning(f"Error reading register {register} from UPS Plus: {e}")
        return None

def read_ups_data(bus):
    data = {}
    data['processor_voltage_mv'] = read_i2c_register(bus, 1)
    data['battery_remaining_percent'] = read_i2c_register(bus, 19)
    data['power_state'] = read_i2c_register(bus, 23)
    return data

def format_ups_data(data):
    if data['processor_voltage_mv'] is None or data['battery_remaining_percent'] is None or data['power_state'] is None:
        return "Error reading UPS Plus data."
    return f"Processor Voltage: {data['processor_voltage_mv']} mV, Battery Remaining: {data['battery_remaining_percent']} %, Power State: {'Normal' if data['power_state'] == 1 else 'Off'}"

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    bus = None
    supply_ina = None
    battery_ina = None

    try:
        try:
            bus = SMBus(DEVICE_BUS)
        except OSError as e:
            logger.error(f"Failed to open I2C bus {DEVICE_BUS}: {e}")
            return

        try:
            supply_ina = INA219(SHUNT_RESISTOR_SUPPLY, busnum=DEVICE_BUS, address=SUPPLY_INA219_ADDRESS)
            supply_ina.configure()
            supply_ina.calibrate(CALIBRATION_VALUE)
        except Exception as e:
            logger.error(f"Failed to initialize supply INA219 at 0x{SUPPLY_INA219_ADDRESS:02X}: {e}")
            return

        try:
            battery_ina = INA219(SHUNT_RESISTOR_BATTERY, busnum=DEVICE_BUS, address=BATTERY_INA219_ADDRESS)
            battery_ina.configure()
            battery_ina.calibrate(CALIBRATION_VALUE)
        except Exception as e:
            logger.error(f"Failed to initialize battery INA219 at 0x{BATTERY_INA219_ADDRESS:02X}: {e}")
            return

        while _running:
            try:
                supply_voltage = supply_ina.voltage()
                supply_current = supply_ina.current()
                supply_power = supply_ina.power()
                logger.info(f"Supply Voltage: {supply_voltage:.3f} V, Current: {supply_current:.3f} mA, Power: {supply_power:.3f} mW")
            except DeviceRangeError:
                logger.warning("Supply current out of range for INA219.")
            except Exception as e:
                logger.warning(f"Error reading supply INA219: {e}")

            try:
                battery_voltage = battery_ina.voltage()
                battery_current = battery_ina.current()
                battery_power = battery_ina.power()
                logger.info(f"Battery Voltage: {battery_voltage:.3f} V, Current: {battery_current:.3f} mA, Power: {battery_power:.3f} mW")
            except DeviceRangeError:
                logger.warning("Battery current out of range for INA219.")
            except Exception as e:
                logger.warning(f"Error reading battery INA219: {e}")

            ups_data = read_ups_data(bus)
            logger.info(format_ups_data(ups_data))

            time.sleep(READ_INTERVAL_SECONDS)

    except Exception as e:
        logger.error(f"Unexpected error: {e}")
    finally:
        if bus is not None:
            try:
                bus.close()
            except Exception:
                pass
        logger.info("Resources cleaned up. Exiting.")

if __name__ == "__main__":
    main()

