import datetime
import smbus2


class DS1338:
    REG_SECONDS = 0x00
    REG_MINUTES = 0x01
    REG_HOURS = 0x02
    REG_DAY = 0x03
    REG_DATE = 0x04
    REG_MONTH = 0x05
    REG_YEAR = 0x06
    REG_CONTROL = 0x07

    def __init__(self, i2c_bus=1, address=0x68, century=21):
        self.address = address
        self.century = century
        self._bus = None
        try:
            self._bus = smbus2.SMBus(i2c_bus)
        except OSError as e:
            raise RuntimeError(f"Failed to open I2C bus {i2c_bus}: {e}") from e

        try:
            self._bus.read_byte_data(self.address, self.REG_SECONDS)
        except OSError as e:
            self.close()
            raise RuntimeError(
                f"No DS1338 found at address 0x{address:02X} on bus {i2c_bus}: {e}"
            ) from e

    def close(self):
        if self._bus is not None:
            try:
                self._bus.close()
            except OSError:
                pass
            self._bus = None

    def _write_register(self, register, value):
        if self._bus is None:
            raise RuntimeError("I2C bus is not open")
        if not (0 <= value <= 0xFF):
            raise ValueError(f"Value {value} out of byte range for register 0x{register:02X}")
        try:
            self._bus.write_byte_data(self.address, register, value)
        except OSError as e:
            raise RuntimeError(f"I2C write to register 0x{register:02X} failed: {e}") from e

    def _read_register(self, register):
        if self._bus is None:
            raise RuntimeError("I2C bus is not open")
        try:
            return self._bus.read_byte_data(self.address, register)
        except OSError as e:
            raise RuntimeError(f"I2C read from register 0x{register:02X} failed: {e}") from e

    @staticmethod
    def _bcd_to_int(bcd):
        return ((bcd >> 4) & 0x0F) * 10 + (bcd & 0x0F)

    @staticmethod
    def _int_to_bcd(n):
        if not (0 <= n <= 99):
            raise ValueError(f"Value {n} out of BCD range (0-99)")
        return ((n // 10) << 4) | (n % 10)

    def read_seconds(self):
        return self._bcd_to_int(self._read_register(self.REG_SECONDS) & 0x7F)

    def read_minutes(self):
        return self._bcd_to_int(self._read_register(self.REG_MINUTES) & 0x7F)

    def read_hours(self):
        raw = self._read_register(self.REG_HOURS)
        return self._bcd_to_int(raw & 0x3F)

    def read_date(self):
        return self._bcd_to_int(self._read_register(self.REG_DATE) & 0x3F)

    def read_month(self):
        return self._bcd_to_int(self._read_register(self.REG_MONTH) & 0x1F)

    def read_year(self):
        return self._bcd_to_int(self._read_register(self.REG_YEAR))

    def read_day(self):
        return self._bcd_to_int(self._read_register(self.REG_DAY) & 0x07)

    def read_datetime(self):
        year = self.read_year() + (self.century - 1) * 100
        return datetime.datetime(
            year, self.read_month(), self.read_date(),
            self.read_hours(), self.read_minutes(), self.read_seconds()
        )

    def write_all(self, seconds=None, minutes=None, hours=None,
                  date=None, month=None, year=None, day=None):
        if seconds is not None:
            self._write_register(self.REG_SECONDS, self._int_to_bcd(seconds))
        if minutes is not None:
            self._write_register(self.REG_MINUTES, self._int_to_bcd(minutes))
        if hours is not None:
            self._write_register(self.REG_HOURS, self._int_to_bcd(hours))
        if date is not None:
            self._write_register(self.REG_DATE, self._int_to_bcd(date))
        if month is not None:
            self._write_register(self.REG_MONTH, self._int_to_bcd(month))
        if year is not None:
            self._write_register(self.REG_YEAR, self._int_to_bcd(year % 100))
        if day is not None:
            self._write_register(self.REG_DAY, self._int_to_bcd(day))


_rtc = None


def _signal_handler(signum, frame):
    if _rtc is not None:
        _rtc.close()
    sys.exit(0)


if __name__ == "__main__":
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    try:
