import serial
import time
import signal
import sys
from gpiozero import OutputDevice

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
ALARM_PIN = 18
RADIATION_THRESHOLD = 50.0
READ_INTERVAL = 1.0

running = True
serial_connection = None
alarm = None

def signal_handler(signum, frame):
    global running
    running = False

def cleanup():
    global serial_connection, alarm
    if serial_connection is not None and serial_connection.is_open:
        try:
            serial_connection.close()
            print("Serial port closed.")
        except Exception as e:
            print(f"Error closing serial port: {e}")
    if alarm is not None:
        try:
            alarm.close()
            print("GPIO alarm pin released.")
        except Exception as e:
            print(f"Error releasing GPIO pin: {e}")

def main():
    global serial_connection, alarm
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        serial_connection = serial.Serial(
            SERIAL_PORT,
            BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=1.0
        )
        print(f"Opened {SERIAL_PORT} at {BAUD_RATE} baud.")
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        sys.exit(1)

    try:
        alarm = OutputDevice(ALARM_PIN, active_high=True, initial_value=False)
        print(f"GPIO pin {ALARM_PIN} initialized as alarm output (LOW).")
    except Exception as e:
        print(f"Error initializing GPIO pin {ALARM_PIN}: {e}")
        cleanup()
        sys.exit(1)

    alarm_active = False

    try:
        while running:
            try:
                raw_data = serial_connection.readline()
                if not raw_data:
                    continue

                try:
                    decoded_data = raw_data.decode('ascii', errors='replace').strip()
                except Exception:
                    decoded_data = ''

                if not decoded_data:
                    continue

                try:
                    radiation_level = float(decoded_data)
                except ValueError:
                    print(f"Invalid data received (not numeric): '{decoded_data}'")
                    time.sleep(READ_INTERVAL)
                    continue

                print(f"Radiation Level: {radiation_level:.2f} µSv/h")

                if radiation_level > RADIATION_THRESHOLD:
                    if not alarm_active:
                        alarm.on()
                        alarm_active = True
                        print("Alarm triggered!")
                else:
                    if alarm_active:
                        alarm.off()
                        alarm_active = False
                        print("Alarm deactivated.")

            except serial.SerialException as e:
                print(f"Serial communication error: {e}")
            except Exception as e:
                print(f"Unexpected error: {e}")

            time.sleep(READ_INTERVAL)

    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

