import serial
import pynmea2
import signal
import sys
from datetime import datetime

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'gps_coordinates_log.txt'

running = True

def signal_handler(signum, frame):
    global running
    running = False

def initialize_serial(port, baud, timeout):
    try:
        ser = serial.Serial(port, baud, timeout=timeout)
        print(f"Serial port {port} opened successfully.")
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error initializing serial port: {e}")
        return None

def parse_gps_data(serial_port):
    try:
        while running:
            try:
                raw_line = serial_port.readline()
                if not raw_line:
                    continue
                line = raw_line.decode('ascii', errors='replace').strip()
                if line.startswith('$GPGGA'):
                    msg = pynmea2.parse(line)
                    if msg.gps_qual == '1':
                        latitude = msg.latitude
                        longitude = msg.longitude
                        altitude = msg.altitude
                        timestamp = datetime.now().isoformat()
                        log_coordinates(timestamp, latitude, longitude, altitude)
                        print_coordinates(timestamp, latitude, longitude, altitude)
                    else:
                        print("No valid GPS fix yet.")
            except pynmea2.ParseError as e:
                print(f"NMEA parse error: {e}")
            except UnicodeDecodeError as e:
                print(f"Decode error: {e}")
            except serial.SerialException as e:
                print(f"Serial I/O error: {e}")
                return
            except Exception as e:
                print(f"Error processing GPS data: {e}")
    finally:
        if serial_port and serial_port.is_open:
            serial_port.close()
            print("Serial port closed.")

def log_coordinates(timestamp, latitude, longitude, altitude):
    try:
        with open(LOG_FILE, 'a') as log_file:
            log_file.write(f"{timestamp}, {latitude}, {longitude}, {altitude}\n")
    except IOError as e:
        print(f"Error writing to log file: {e}")
    except Exception as e:
        print(f"Unexpected error logging coordinates: {e}")

def print_coordinates(timestamp, latitude, longitude, altitude):
