                        if not raw:
                            print('No data received (timeout).')
                        else:
                            line = raw.decode('ascii', errors='replace').strip()
                            if not line:
                                print('Empty line received.')
                            else:
                                parts = line.split(',')
                                if len(parts) != 2:
                                    raise ValueError(f'Expected 2 fields, got {len(parts)}')
                                hr = int(parts[0].strip())
                                spo2 = int(parts[1].strip())
