import serial
import signal
import sys
import logging
from dataclasses import dataclass
from typing import Optional

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

@dataclass
class GPS_readings:
    latitude: float
    longitude: float
    altitude: float
    sats: int

class GPSReader:
    def __init__(self, port: str = "/dev/serial0", baudrate: int = 9600, timeout: float = 1.0):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial_port: Optional[serial.Serial] = None
        self._running = True

    def connect(self) -> bool:
        try:
            self.serial_port = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=self.timeout,
            )
            logging.info(f"Connected to GPS on {self.port} at {self.baudrate} baud.")
            return True
        except serial.SerialException as e:
            logging.error(f"Failed to connect to GPS on {self.port}: {e}")
            self.serial_port = None
            return False
        except Exception as e:
            logging.error(f"Unexpected error opening {self.port}: {e}")
            self.serial_port = None
            return False

    def disconnect(self) -> None:
        if self.serial_port is not None:
            try:
                if self.serial_port.is_open:
                    self.serial_port.close()
                    logging.info("GPS disconnected.")
            except Exception as e:
                logging.error(f"Error disconnecting GPS: {e}")
            finally:
                self.serial_port = None

    def _verify_checksum(self, sentence: str) -> bool:
        if "*" not in sentence:
            return False
        body, _, checksum_str = sentence.partition("*")
        if not body.startswith("$"):
            return False
        try:
            expected = int(checksum_str.strip()[:2], 16)
        except ValueError:
            return False
        computed = 0
        for ch in body[1:]:
            computed ^= ord(ch)
        return computed == expected

    def _nmea_to_decimal(self, nmea_val: str, direction: str) -> float:
        if not nmea_val:
            raise ValueError("Empty coordinate field")
        dot = nmea_val.find(".")
        if dot == -1:
            raise ValueError("Malformed coordinate field")
        deg_part = nmea_val[:dot - 2]
        min_part = nmea_val[dot - 2:]
        degrees = float(deg_part)
        minutes = float(min_part)
        decimal = degrees + minutes / 60.0
        if direction in ("S", "W"):
            decimal = -decimal
        return decimal

    def get_readings(self) -> Optional[GPS_readings]:
        if self.serial_port is None or not self.serial_port.is_open:
            logging.error("Serial port not open.")
            return None
        try:
            raw = self.serial_port.readline()
            if not raw:
                logging.warning("Serial read timeout.")
                return None
            line = raw.decode("ascii", errors="replace").strip()
            if not line.startswith("$GPGGA"):
                return None
            if not self._verify_checksum(line):
                logging.warning(f"Checksum mismatch: {line}")
                return None
            fields = line.split(",")
            if len(fields) < 11:
                logging.warning(f"Incomplete GPGGA: {line}")
                return None
            if fields[2] == "" or fields[4] == "":
                logging.warning("GPGGA missing latitude or longitude.")
                return None
            lat = self._nmea_to_decimal(fields[2], fields[3])
            lon = self._nmea_to_decimal(fields[4], fields[5])
            if fields[9] == "":
                sats = 0
            else:
                sats = int(fields[9])
            if fields[1] == "":
                logging.warning("GPGGA missing fix time.")
                return None
            if fields[10] == "":
                logging.warning("GPGGA missing altitude.")
                return None
            alt = float(fields[10])
            return GPS_readings(latitude=lat, longitude=lon, altitude=alt, sats=sats)
        except ValueError as e:
            logging.error(f"Value error parsing GPGGA: {e}")
            return None
        except Exception as e:
            logging.error(f"Unexpected error parsing GPGGA: {e}")
            return None

    def stop(self) -> None:
        self._running = False

def main() -> None:
    gps = GPSReader(port="/dev/serial0", baudrate=9600, timeout=1.0)

    def signal_handler(signum, frame):
        logging.info(f"Signal {signum} received, shutting down.")
        gps.stop()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not gps.connect():
        sys.exit(1)

    try:
        while gps._running:
            readings = gps.get_readings()
            if readings is not None:
                logging.info(
                    f"Lat={readings.latitude:.6f}, Lon={readings.longitude:.6f}, "
                    f"Alt={readings.altitude:.2f}m, Sats={readings.sats}"
                )
    except Exception as e:
        logging.error(f"Fatal error in main loop: {e}")
    finally:
        gps.disconnect()

if __name__ == "__main__":
    main()

