            raise RuntimeError(f"Failed to decode serial data: {e}") from e

        for line in text.splitlines():
            line = line.strip()
            if not line.startswith('$GPRMC'):
                continue
            parts = line.split(',')
            # $GPRMC has at least 12 fields; index 2 is the status ('A' = valid)
            if len(parts) >= 3 and parts[2] == 'A':
                return parts
        return None

    # ------------------------------------------------------------------
    # Cleanup
    # ------------------------------------------------------------------
    def close(self):
        """Release the serial port safely."""
        if self._closed:
            return
        self._closed = True
        if self.ser is not None:
            try:
                if self.ser.is_open:
                    self.ser.close()
            except Exception:
                pass
            finally:
                self.ser = None

    def __del__(self):
        self.close()

