import logging
import signal
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class SimpleGPS:
    def __init__(self, port='/dev/serial0', baudrate=9600):
        self.port = port
        self.baudrate = baudrate
        self.serial_connection = None

    def connect(self):
        try:
            self.serial_connection = serial.Serial(
                self.port, 
                self.baudrate, 
                timeout=1, 
                bytesize=serial.EIGHTBITS, 
                parity=serial.PARITY_NONE, 
                stopbits=serial.STOPBITS_ONE
            )
            logging.info(f"Connected to GPS on {self.port} at {self.baudrate} baud.")
            return True
        except serial.SerialException as e:
            logging.error(f"Serial error connecting to GPS: {e}")
            self.serial_connection = None
            return False
        except OSError as e:
            logging.error(f"OS error connecting to GPS (device may not exist): {e}")
            self.serial_connection = None
            return False

    def read_data(self):
        if not self.serial_connection or not self.serial_connection.is_open:
            logging.warning("Serial connection is not open.")
            return None
        try:
            if self.serial_connection.in_waiting > 0:
                data = self.serial_connection.readline().decode('utf-8', errors='ignore').strip()
                if data:
                    return data
                return None
            return None
        except serial.SerialException as e:
            logging.error(f"Serial error reading data: {e}")
            return None
        except OSError as e:
            logging.error(f"OS error reading data: {e}")
            return None

    def parse_gga(self, data):
        if not data:
            return None
        if not (data.startswith('$GPGGA') or data.startswith('$GNGGA')):
            return None
        try:
            parts = data.split(',')
            if len(parts) < 15:
                logging.warning(f"Malformed GGA sentence (too few fields): {data}")
                return None
            utc_time = parts[1]
            lat_raw = parts[2]
            lat_dir = parts[3]
            lon_raw = parts[4]
            lon_dir = parts[5]
            fix_quality = parts[6]
            num_satellites = parts[7]

            if not lat_raw or not lon_raw:
                logging.warning("GGA sentence missing latitude or longitude.")
                return None

            latitude = self._convert_to_decimal(lat_raw, lat_dir)
            longitude = self._convert_to_decimal(lon_raw, lon_dir)

            return {
                'utc_time': utc_time,
                'latitude': latitude,
                'longitude': longitude,
                'fix_quality': fix_quality,
                'num_satellites': num_satellites
            }
        except (IndexError, ValueError) as e:
            logging.error(f"Error parsing GGA data: {e}")
            return None

    def _convert_to_decimal(self, coordinate, direction):
        if not coordinate:
            return None
        try:
            degrees = int(coordinate[:2])
            minutes = float(coordinate[2:])
            decimal = degrees + (minutes / 60.0)
            if direction in ('S', 'W'):
                decimal = -decimal
            return decimal
        except (ValueError, IndexError) as e:
            logging.error(f"Error converting coordinate '{coordinate}' with direction '{direction}': {e}")
            return None

    def close(self):
        if self.serial_connection and self.serial_connection.is_open:
            try:
                self.serial_connection.close()
                logging.info("Serial connection closed.")
            except Exception as e:
                logging.error(f"Error closing serial connection: {e}")
        self.serial_connection = None

def main():
    gps = SimpleGPS()
    if not gps.connect():
        sys.exit(1)

    def signal_handler(sig, frame):
        logging.info("Interrupt received, shutting down...")
        gps.close()
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        while True:
            data = gps.read_data()
            if data:
                parsed = gps.parse_gga(data)
                if parsed:
                    logging.info(f"Parsed GPS data: {parsed}")
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        gps.close()

if __name__ == '__main__':
    main()

