#!/usr/bin/env python3
# -*- coding: utf-8 -*-

"""
Flask application for Raspberry Pi: in-memory data store + USB-serial
instrument control (e.g. bench power supply / SCPI device).

Wiring / setup:
  - USB-serial adapter plugged into the Raspberry Pi USB port.
  - Device appears as /dev/ttyUSB0 (or /dev/ttyACM0 for CDC-ACM).
  - Instrument expects ASCII commands terminated with '\n' and replies
    terminated with '\n' within 1 second.

Dependencies:
  pip install flask pyserial
"""

import signal
import sys
import threading
from typing import List, Optional

import serial
from flask import Flask, Response, jsonify, request

app = Flask(__name__)

# ---------------------------------------------------------------------------
# SerialCommunicator
# ---------------------------------------------------------------------------
class SerialCommunicator:
    """Thread-safe serial port wrapper supporting context-manager usage."""

    def __init__(self, port: str, baudrate: int = 9600):
        self.port = port
        self.baudrate = baudrate
        self._serial: Optional[serial.Serial] = None
        self._lock = threading.Lock()

    # -- context-manager protocol ------------------------------------------
    def __enter__(self) -> "SerialCommunicator":
        self.open()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb) -> None:
        self.close()

    # -- public API --------------------------------------------------------
    def open(self) -> None:
        """Open the serial port; raise serial.SerialException on failure."""
        with self._lock:
            if self._serial is not None and self._serial.is_open:
                return
            self._serial = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=1.0,          # read timeout
                write_timeout=1.0,    # write timeout
            )

    def close(self) -> None:
        """Idempotent, thread-safe close."""
        with self._lock:
            if self._serial is not None:
                try:
                    if self._serial.is_open:
                        self._serial.reset_input_buffer()
                        self._serial.reset_output_buffer()
                        self._serial.close()
                except Exception:
                    pass
                finally:
                    self._serial = None

    def send(self, command: str) -> None:
        """Send a command string (encoded as ASCII) and flush."""
        with self._lock:
            if self._serial is None or not self._serial.is_open:
                raise serial.SerialException("Serial port is not open")
            data = command.encode("ascii")
            written = self._serial.write(data)
            if written != len(data):
                raise serial.SerialException(
                    f"Short write: {written}/{len(data)} bytes"
                )
            self._serial.flush()

    def receive_line(self) -> Optional[str]:
        """Read one line (up to newline) with a 1 s timeout.

        Returns the stripped string, or None on timeout / error.
        """
        with self._lock:
            if self._serial is None or not self._serial.is_open:
                return None
            try:
                raw = self._serial.readline()
            except serial.SerialException:
                return None
            if not raw:
                return None  # timeout
            return raw.decode("ascii", errors="replace").strip()


# ---------------------------------------------------------------------------
# DataManager
# ---------------------------------------------------------------------------
class DataManager:
    """Thread-safe in-memory data store."""

    def __init__(self):
        self._lock = threading.Lock()
        self._items: List[dict] = []
        self._next_id = 1

    def get_all(self) -> List[dict]:
        with self._lock:
            return list(self._items)

    def get_by_id(self, item_id: int) -> Optional[dict]:
        with self._lock:
            return next((i for i in self._items if i.get("id") == item_id), None)

    def create(self, name: str, done: bool) -> dict:
        """Create a new item; validate inputs."""
        if not isinstance(name, str) or not name.strip():
            raise ValueError("name must be a non-empty string")
        if not isinstance(done, bool):
            raise ValueError("done must be a boolean")
        with self._lock:
            item = {
                "id": self._next_id,
                "name": name.strip(),
                "done": done,
            }
            self._items.append(item)
            self._next_id += 1
            return item


# ---------------------------------------------------------------------------
# Globals
# ---------------------------------------------------------------------------
serial_port = "/dev/ttyUSB0"
baud_rate = 9600
data_manager = DataManager()
serial_comm: Optional[SerialCommunicator] = None
_server: Optional[threading.Thread] = None


# ---------------------------------------------------------------------------
# Signal handling
# ---------------------------------------------------------------------------
def _signal_handler(signum, frame):
    print(f"\nReceived signal {signum}, shutting down...")
    if serial_comm is not None:
        serial_comm.close()
    if _server is not None and _server.is_alive():
        sys.exit(0)


signal.signal(signal.SIGINT, _signal_handler)
signal.signal(signal.SIGTERM, _signal_handler)


# ---------------------------------------------------------------------------
# Routes
# ---------------------------------------------------------------------------
@app.route("/version", methods=["GET"])
def get_version() -> Response:
    """Query the connected instrument for its identity string."""
    try:
        with SerialCommunicator(serial_port, baud_rate) as comm:
            comm.send("*IDN?\n")
            response = comm.receive_line()
            if response is None:
                return Response("No response from instrument (timeout)", status=504)
            return Response(response, mimetype="text/plain")
    except serial.SerialException as e:
        return Response(f"Serial port error: {e}", status=500)
    except Exception as e:
        return Response(f"Unexpected error: {e}", status=502)


@app.route("/data", methods=["GET"])
def get_data() -> Response:
    return jsonify(data_manager.get_all())


@app.route("/data/<int:item_id>", methods=["GET"])
def get_data_item(item_id: int) -> Response:
    item = data_manager.get_by_id(item_id)
    if item is None:
        return Response("Item not found", status=404)
    return jsonify(item)


@app.route("/data", methods=["POST"])
def create_data_item() -> Response:
    try:
        req = request.get_json(silent=True)
        if not isinstance(req, dict):
            return Response("Invalid JSON body", status=400)
        name = req.get("name")
        done = req.get("done", False)
        item = data_manager.create(name, done)
        return jsonify(item), 201
    except ValueError as e:
        return Response(str(e), status=400)
    except Exception as e:
        return Response(f"Internal error: {e}", status=500)


# ---------------------------------------------------------------------------
# Entry point
# ---------------------------------------------------------------------------
if __name__ == "__main__":
    # Pre-open the serial port so the app can use it immediately.
    try:
        serial_comm = SerialCommunicator(serial_port, baud_rate)
        serial_comm.open()
        print(f"Serial port {serial_port} opened at {baud_rate} baud.")
    except serial.SerialException as e:
        print(f"Warning: could not open {serial_port}: {e}")
        serial_comm = None

    # Run Flask in a daemon thread so signals are handled cleanly.
    _server = threading.Thread(
        target=lambda: app.run(host="0.0.0.0", port=5000, debug=False),
        daemon=True,
    )
    _server.start()

    # Keep main thread alive until interrupted.
    try:
        while True:
            signal.pause()
    except KeyboardInterrupt:
        _signal_handler(signal.SIGINT, None)

