import serial
import time
import logging
import sys

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'power_consumption.log'

logging.basicConfig(
    filename=LOG_FILE,
    level=logging.INFO,
    format='%(asctime)s - Power: %(message)s W',
    datefmt='%Y-%m-%d %H:%M:%S'
)

def main():
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)
    except OSError as e:
        print(f"OS error opening {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)

    print(f"Listening on {SERIAL_PORT} @ {BAUD_RATE} baud. Press Ctrl+C to stop.")

    try:
        while True:
            try:
                raw = ser.readline()
            except serial.SerialException as e:
                print(f"Serial read error: {e}", file=sys.stderr)
                time.sleep(1)
                continue

            if not raw:
                continue

            line = raw.decode('ascii', errors='replace').strip()
            if not line:
                continue

            try:
                power = float(line)
            except ValueError:
                print(f"Invalid data received (not a float): '{line}'", file=sys.stderr)
                continue

            logging.info(f"{power}")
            print(f"Power Consumption: {power} W")
    except KeyboardInterrupt:
        print("\nExiting...")
    finally:
        if ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == '__main__':
    main()

