from flask import Flask, Response, request, jsonify, abort
import serial
import time
import threading

app = Flask(__name__)

# In-memory data store
data_store = [
    {"id": 1, "name": "Item 1", "done": False},
    {"id": 2, "name": "Item 2", "done": False},
]

# Thread-safe lock for data_store mutations
_data_lock = threading.Lock()

SERIAL_PORT = '/dev/ttyUSB0'
BAUDRATE = 9600
TIMEOUT = 1


@app.route('/version', methods=['GET'])
def get_version():
    """Query a serial-connected SCPI instrument for its identity."""
    ser = None
    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUDRATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=TIMEOUT,
        )
        if not ser.is_open:
            return Response("Serial port did not open", status=503, mimetype='text/html')

        ser.write(b'*IDN?\n')
        time.sleep(0.1)
        raw = ser.read(4096)
        if not raw:
            return Response("No response from instrument", status=503, mimetype='text/html')
        text = raw.decode('ascii', errors='replace').replace('\n', '<br>')
        return Response(text, mimetype='text/html')
    except serial.SerialException as exc:
        return Response(f"Serial error: {exc}", status=503, mimetype='text/html')
    except OSError as exc:
        return Response(f"OS error: {exc}", status=503, mimetype='text/html')
    finally:
        if ser is not None:
            try:
                ser.close()
            except Exception:
                pass


@app.route('/getdata', methods=['GET'])
def get_data():
    """Return the full in-memory data store as JSON."""
    with _data_lock:
        return jsonify(data_store)


@app.route('/getset/<int:item_id>', methods=['GET'])
def get_item(item_id):
    """Return a single item by id, or 404 if not found."""
    with _data_lock:
        item = next((i for i in data_store if i['id'] == item_id), None)
    if item is None:
        abort(404, description=f"Item {item_id} not found")
    return jsonify(item)


@app.route('/getpost/<int:item_id>/<name>', methods=['GET'])
def get_post_item(item_id, name):
    """Append a new item and return the updated list as JSON."""
    with _data_lock:
        new_id = (data_store[-1]['id'] + 1) if data_store else 1
        data_store.append({"id": new_id, "name": name, "done": False})
    return jsonify(data_store)


@app.route('/postjson', methods=['POST', 'GET'])
def post_json():
    """Create a new item from JSON or form data; return the updated list as JSON."""
    if request.method == 'GET':
        with _data_lock:
            return jsonify(data_store)

    try:
        if request.is_json:
            req_data = request.get_json(silent=False)
            if not isinstance(req_data, dict):
                abort(400, description="JSON body must be an object")
            name = req_data.get('name', '')
            done = req_data.get('done', False)
        else:
            name = request.form.get('name', '')
            done_str = request.form.get('done', '')
            done = done_str.lower() in ('true', '1', 'yes')

        if not isinstance(name, str):
            abort(400, description="name must be a string")
        if not isinstance(done, bool):
            abort(400, description="done must be a boolean")

        with _data_lock:
            new_id = (data_store[-1]['id'] + 1) if data_store else 1
            data_store.append({"id": new_id, "name": name, "done": done})
        return jsonify(data_store)
    except (ValueError, TypeError) as exc:
        abort(400, description=f"Invalid input: {exc}")


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)

